-- KJV batch 6 (blocks 126-150 of 349)
-- Run this in Supabase Dashboard SQL Editor

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 24, 18, E'And they left the house of the LORD God of their fathers, and served groves and idols: and wrath came upon Judah and Jerusalem for this their trespass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 24, 19, E'Yet he sent prophets to them, to bring them again unto the LORD; and they testified against them: but they would not give ear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 24, 20, E'And the Spirit of God came upon Zechariah the son of Jehoiada the priest, which stood above the people, and said unto them, Thus saith God, Why transgress ye the commandments of the LORD, that ye cannot prosper? because ye have forsaken the LORD, he hath also forsaken you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 24, 21, E'And they conspired against him, and stoned him with stones at the commandment of the king in the court of the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 24, 22, E'Thus Joash the king remembered not the kindness which Jehoiada his father had done to him, but slew his son. And when he died, he said, The LORD look upon it, and require it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 24, 23, E'And it came to pass at the end of the year, that the host of Syria came up against him: and they came to Judah and Jerusalem, and destroyed all the princes of the people from among the people, and sent all the spoil of them unto the king of Damascus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 24, 24, E'For the army of the Syrians came with a small company of men, and the LORD delivered a very great host into their hand, because they had forsaken the LORD God of their fathers. So they executed judgment against Joash.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 24, 25, E'And when they were departed from him, (for they left him in great diseases,) his own servants conspired against him for the blood of the sons of Jehoiada the priest, and slew him on his bed, and he died: and they buried him in the city of David, but they buried him not in the sepulchres of the kings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 24, 26, E'And these are they that conspired against him; Zabad the son of Shimeath an Ammonitess, and Jehozabad the son of Shimrith a Moabitess.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 24, 27, E'Now concerning his sons, and the greatness of the burdens laid upon him, and the repairing of the house of God, behold, they are written in the story of the book of the kings. And Amaziah his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 1, E'Amaziah was twenty and five years old when he began to reign, and he reigned twenty and nine years in Jerusalem. And his mother’s name was Jehoaddan of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 2, E'And he did that which was right in the sight of the LORD, but not with a perfect heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 3, E'Now it came to pass, when the kingdom was established to him, that he slew his servants that had killed the king his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 4, E'But he slew not their children, but did as it is written in the law in the book of Moses, where the LORD commanded, saying, The fathers shall not die for the children, neither shall the children die for the fathers, but every man shall die for his own sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 5, E'Moreover Amaziah gathered Judah together, and made them captains over thousands, and captains over hundreds, according to the houses of their fathers, throughout all Judah and Benjamin: and he numbered them from twenty years old and above, and found them three hundred thousand choice men, able to go forth to war, that could handle spear and shield.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 6, E'He hired also an hundred thousand mighty men of valour out of Israel for an hundred talents of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 7, E'But there came a man of God to him, saying, O king, let not the army of Israel go with thee; for the LORD is not with Israel, to wit, with all the children of Ephraim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 8, E'But if thou wilt go, do it, be strong for the battle: God shall make thee fall before the enemy: for God hath power to help, and to cast down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 9, E'And Amaziah said to the man of God, But what shall we do for the hundred talents which I have given to the army of Israel? And the man of God answered, The LORD is able to give thee much more than this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 10, E'Then Amaziah separated them, to wit, the army that was come to him out of Ephraim, to go home again: wherefore their anger was greatly kindled against Judah, and they returned home in great anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 11, E'And Amaziah strengthened himself, and led forth his people, and went to the valley of salt, and smote of the children of Seir ten thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 12, E'And other ten thousand left alive did the children of Judah carry away captive, and brought them unto the top of the rock, and cast them down from the top of the rock, that they all were broken in pieces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 13, E'But the soldiers of the army which Amaziah sent back, that they should not go with him to battle, fell upon the cities of Judah, from Samaria even unto Bethhoron, and smote three thousand of them, and took much spoil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 14, E'Now it came to pass, after that Amaziah was come from the slaughter of the Edomites, that he brought the gods of the children of Seir, and set them up to be his gods, and bowed down himself before them, and burned incense unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 15, E'Wherefore the anger of the LORD was kindled against Amaziah, and he sent unto him a prophet, which said unto him, Why hast thou sought after the gods of the people, which could not deliver their own people out of thine hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 16, E'And it came to pass, as he talked with him, that the king said unto him, Art thou made of the king’s counsel? forbear; why shouldest thou be smitten? Then the prophet forbare, and said, I know that God hath determined to destroy thee, because thou hast done this, and hast not hearkened unto my counsel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 17, E'Then Amaziah king of Judah took advice, and sent to Joash, the son of Jehoahaz, the son of Jehu, king of Israel, saying, Come, let us see one another in the face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 18, E'And Joash king of Israel sent to Amaziah king of Judah, saying, The thistle that was in Lebanon sent to the cedar that was in Lebanon, saying, Give thy daughter to my son to wife: and there passed by a wild beast that was in Lebanon, and trode down the thistle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 19, E'Thou sayest, Lo, thou hast smitten the Edomites; and thine heart lifteth thee up to boast: abide now at home; why shouldest thou meddle to thine hurt, that thou shouldest fall, even thou, and Judah with thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 20, E'But Amaziah would not hear; for it came of God, that he might deliver them into the hand of their enemies, because they sought after the gods of Edom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 21, E'So Joash the king of Israel went up; and they saw one another in the face, both he and Amaziah king of Judah, at Bethshemesh, which belongeth to Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 22, E'And Judah was put to the worse before Israel, and they fled every man to his tent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 23, E'And Joash the king of Israel took Amaziah king of Judah, the son of Joash, the son of Jehoahaz, at Bethshemesh, and brought him to Jerusalem, and brake down the wall of Jerusalem from the gate of Ephraim to the corner gate, four hundred cubits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 24, E'And he took all the gold and the silver, and all the vessels that were found in the house of God with Obededom, and the treasures of the king’s house, the hostages also, and returned to Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 25, E'And Amaziah the son of Joash king of Judah lived after the death of Joash son of Jehoahaz king of Israel fifteen years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 26, E'Now the rest of the acts of Amaziah, first and last, behold, are they not written in the book of the kings of Judah and Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 27, E'Now after the time that Amaziah did turn away from following the LORD they made a conspiracy against him in Jerusalem; and he fled to Lachish: but they sent to Lachish after him, and slew him there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 25, 28, E'And they brought him upon horses, and buried him with his fathers in the city of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 1, E'Then all the people of Judah took Uzziah, who was sixteen years old, and made him king in the room of his father Amaziah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 2, E'He built Eloth, and restored it to Judah, after that the king slept with his fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 3, E'Sixteen years old was Uzziah when he began to reign, and he reigned fifty and two years in Jerusalem. His mother’s name also was Jecoliah of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 4, E'And he did that which was right in the sight of the LORD, according to all that his father Amaziah did.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 5, E'And he sought God in the days of Zechariah, who had understanding in the visions of God: and as long as he sought the LORD, God made him to prosper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 6, E'And he went forth and warred against the Philistines, and brake down the wall of Gath, and the wall of Jabneh, and the wall of Ashdod, and built cities about Ashdod, and among the Philistines.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 7, E'And God helped him against the Philistines, and against the Arabians that dwelt in Gurbaal, and the Mehunims.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 8, E'And the Ammonites gave gifts to Uzziah: and his name spread abroad even to the entering in of Egypt; for he strengthened himself exceedingly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 9, E'Moreover Uzziah built towers in Jerusalem at the corner gate, and at the valley gate, and at the turning of the wall, and fortified them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 10, E'Also he built towers in the desert, and digged many wells: for he had much cattle, both in the low country, and in the plains: husbandmen also, and vine dressers in the mountains, and in Carmel: for he loved husbandry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 11, E'Moreover Uzziah had an host of fighting men, that went out to war by bands, according to the number of their account by the hand of Jeiel the scribe and Maaseiah the ruler, under the hand of Hananiah, one of the king’s captains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 12, E'The whole number of the chief of the fathers of the mighty men of valour were two thousand and six hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 13, E'And under their hand was an army, three hundred thousand and seven thousand and five hundred, that made war with mighty power, to help the king against the enemy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 14, E'And Uzziah prepared for them throughout all the host shields, and spears, and helmets, and habergeons, and bows, and slings to cast stones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 15, E'And he made in Jerusalem engines, invented by cunning men, to be on the towers and upon the bulwarks, to shoot arrows and great stones withal. And his name spread far abroad; for he was marvellously helped, till he was strong.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 16, E'But when he was strong, his heart was lifted up to his destruction: for he transgressed against the LORD his God, and went into the temple of the LORD to burn incense upon the altar of incense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 17, E'And Azariah the priest went in after him, and with him fourscore priests of the LORD, that were valiant men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 18, E'And they withstood Uzziah the king, and said unto him, It appertaineth not unto thee, Uzziah, to burn incense unto the LORD, but to the priests the sons of Aaron, that are consecrated to burn incense: go out of the sanctuary; for thou hast trespassed; neither shall it be for thine honour from the LORD God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 19, E'Then Uzziah was wroth, and had a censer in his hand to burn incense: and while he was wroth with the priests, the leprosy even rose up in his forehead before the priests in the house of the LORD, from beside the incense altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 20, E'And Azariah the chief priest, and all the priests, looked upon him, and, behold, he was leprous in his forehead, and they thrust him out from thence; yea, himself hasted also to go out, because the LORD had smitten him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 21, E'And Uzziah the king was a leper unto the day of his death, and dwelt in a several house, being a leper; for he was cut off from the house of the LORD: and Jotham his son was over the king’s house, judging the people of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 22, E'Now the rest of the acts of Uzziah, first and last, did Isaiah the prophet, the son of Amoz, write.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 26, 23, E'So Uzziah slept with his fathers, and they buried him with his fathers in the field of the burial which belonged to the kings; for they said, He is a leper: and Jotham his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 27, 1, E'Jotham was twenty and five years old when he began to reign, and he reigned sixteen years in Jerusalem. His mother’s name also was Jerushah, the daughter of Zadok.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 27, 2, E'And he did that which was right in the sight of the LORD, according to all that his father Uzziah did: howbeit he entered not into the temple of the LORD. And the people did yet corruptly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 27, 3, E'He built the high gate of the house of the LORD, and on the wall of Ophel he built much.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 27, 4, E'Moreover he built cities in the mountains of Judah, and in the forests he built castles and towers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 27, 5, E'He fought also with the king of the Ammonites, and prevailed against them. And the children of Ammon gave him the same year an hundred talents of silver, and ten thousand measures of wheat, and ten thousand of barley. So much did the children of Ammon pay unto him, both the second year, and the third.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 27, 6, E'So Jotham became mighty, because he prepared his ways before the LORD his God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 27, 7, E'Now the rest of the acts of Jotham, and all his wars, and his ways, lo, they are written in the book of the kings of Israel and Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 27, 8, E'He was five and twenty years old when he began to reign, and reigned sixteen years in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 27, 9, E'And Jotham slept with his fathers, and they buried him in the city of David: and Ahaz his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 1, E'Ahaz was twenty years old when he began to reign, and he reigned sixteen years in Jerusalem: but he did not that which was right in the sight of the LORD, like David his father:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 2, E'For he walked in the ways of the kings of Israel, and made also molten images for Baalim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 3, E'Moreover he burnt incense in the valley of the son of Hinnom, and burnt his children in the fire, after the abominations of the heathen whom the LORD had cast out before the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 4, E'He sacrificed also and burnt incense in the high places, and on the hills, and under every green tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 5, E'Wherefore the LORD his God delivered him into the hand of the king of Syria; and they smote him, and carried away a great multitude of them captives, and brought them to Damascus. And he was also delivered into the hand of the king of Israel, who smote him with a great slaughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 6, E'For Pekah the son of Remaliah slew in Judah an hundred and twenty thousand in one day, which were all valiant men; because they had forsaken the LORD God of their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 7, E'And Zichri, a mighty man of Ephraim, slew Maaseiah the king’s son, and Azrikam the governor of the house, and Elkanah that was next to the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 8, E'And the children of Israel carried away captive of their brethren two hundred thousand, women, sons, and daughters, and took also away much spoil from them, and brought the spoil to Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 9, E'But a prophet of the LORD was there, whose name was Oded: and he went out before the host that came to Samaria, and said unto them, Behold, because the LORD God of your fathers was wroth with Judah, he hath delivered them into your hand, and ye have slain them in a rage that reacheth up unto heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 10, E'And now ye purpose to keep under the children of Judah and Jerusalem for bondmen and bondwomen unto you: but are there not with you, even with you, sins against the LORD your God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 11, E'Now hear me therefore, and deliver the captives again, which ye have taken captive of your brethren: for the fierce wrath of the LORD is upon you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 12, E'Then certain of the heads of the children of Ephraim, Azariah the son of Johanan, Berechiah the son of Meshillemoth, and Jehizkiah the son of Shallum, and Amasa the son of Hadlai, stood up against them that came from the war,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 13, E'And said unto them, Ye shall not bring in the captives hither: for whereas we have offended against the LORD already, ye intend to add more to our sins and to our trespass: for our trespass is great, and there is fierce wrath against Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 14, E'So the armed men left the captives and the spoil before the princes and all the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 15, E'And the men which were expressed by name rose up, and took the captives, and with the spoil clothed all that were naked among them, and arrayed them, and shod them, and gave them to eat and to drink, and anointed them, and carried all the feeble of them upon asses, and brought them to Jericho, the city of palm trees, to their brethren: then they returned to Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 16, E'At that time did king Ahaz send unto the kings of Assyria to help him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 17, E'For again the Edomites had come and smitten Judah, and carried away captives.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 18, E'The Philistines also had invaded the cities of the low country, and of the south of Judah, and had taken Bethshemesh, and Ajalon, and Gederoth, and Shocho with the villages thereof, and Timnah with the villages thereof, Gimzo also and the villages thereof: and they dwelt there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 19, E'For the LORD brought Judah low because of Ahaz king of Israel; for he made Judah naked, and transgressed sore against the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 20, E'And Tilgathpilneser king of Assyria came unto him, and distressed him, but strengthened him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 21, E'For Ahaz took away a portion out of the house of the LORD, and out of the house of the king, and of the princes, and gave it unto the king of Assyria: but he helped him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 22, E'And in the time of his distress did he trespass yet more against the LORD: this is that king Ahaz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 23, E'For he sacrificed unto the gods of Damascus, which smote him: and he said, Because the gods of the kings of Syria help them, therefore will I sacrifice to them, that they may help me. But they were the ruin of him, and of all Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 24, E'And Ahaz gathered together the vessels of the house of God, and cut in pieces the vessels of the house of God, and shut up the doors of the house of the LORD, and he made him altars in every corner of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 25, E'And in every several city of Judah he made high places to burn incense unto other gods, and provoked to anger the LORD God of his fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 26, E'Now the rest of his acts and of all his ways, first and last, behold, they are written in the book of the kings of Judah and Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 28, 27, E'And Ahaz slept with his fathers, and they buried him in the city, even in Jerusalem: but they brought him not into the sepulchres of the kings of Israel: and Hezekiah his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 1, E'Hezekiah began to reign when he was five and twenty years old, and he reigned nine and twenty years in Jerusalem. And his mother’s name was Abijah, the daughter of Zechariah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 2, E'And he did that which was right in the sight of the LORD, according to all that David his father had done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 3, E'He in the first year of his reign, in the first month, opened the doors of the house of the LORD, and repaired them.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Chronicles') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 4, E'And he brought in the priests and the Levites, and gathered them together into the east street,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 5, E'And said unto them, Hear me, ye Levites, sanctify now yourselves, and sanctify the house of the LORD God of your fathers, and carry forth the filthiness out of the holy place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 6, E'For our fathers have trespassed, and done that which was evil in the eyes of the LORD our God, and have forsaken him, and have turned away their faces from the habitation of the LORD, and turned their backs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 7, E'Also they have shut up the doors of the porch, and put out the lamps, and have not burned incense nor offered burnt offerings in the holy place unto the God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 8, E'Wherefore the wrath of the LORD was upon Judah and Jerusalem, and he hath delivered them to trouble, to astonishment, and to hissing, as ye see with your eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 9, E'For, lo, our fathers have fallen by the sword, and our sons and our daughters and our wives are in captivity for this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 10, E'Now it is in mine heart to make a covenant with the LORD God of Israel, that his fierce wrath may turn away from us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 11, E'My sons, be not now negligent: for the LORD hath chosen you to stand before him, to serve him, and that ye should minister unto him, and burn incense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 12, E'Then the Levites arose, Mahath the son of Amasai, and Joel the son of Azariah, of the sons of the Kohathites: and of the sons of Merari, Kish the son of Abdi, and Azariah the son of Jehalelel: and of the Gershonites; Joah the son of Zimmah, and Eden the son of Joah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 13, E'And of the sons of Elizaphan; Shimri, and Jeiel: and of the sons of Asaph; Zechariah, and Mattaniah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 14, E'And of the sons of Heman; Jehiel, and Shimei: and of the sons of Jeduthun; Shemaiah, and Uzziel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 15, E'And they gathered their brethren, and sanctified themselves, and came, according to the commandment of the king, by the words of the LORD, to cleanse the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 16, E'And the priests went into the inner part of the house of the LORD, to cleanse it, and brought out all the uncleanness that they found in the temple of the LORD into the court of the house of the LORD. And the Levites took it, to carry it out abroad into the brook Kidron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 17, E'Now they began on the first day of the first month to sanctify, and on the eighth day of the month came they to the porch of the LORD: so they sanctified the house of the LORD in eight days; and in the sixteenth day of the first month they made an end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 18, E'Then they went in to Hezekiah the king, and said, We have cleansed all the house of the LORD, and the altar of burnt offering, with all the vessels thereof, and the shewbread table, with all the vessels thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 19, E'Moreover all the vessels, which king Ahaz in his reign did cast away in his transgression, have we prepared and sanctified, and, behold, they are before the altar of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 20, E'Then Hezekiah the king rose early, and gathered the rulers of the city, and went up to the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 21, E'And they brought seven bullocks, and seven rams, and seven lambs, and seven he goats, for a sin offering for the kingdom, and for the sanctuary, and for Judah. And he commanded the priests the sons of Aaron to offer them on the altar of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 22, E'So they killed the bullocks, and the priests received the blood, and sprinkled it on the altar: likewise, when they had killed the rams, they sprinkled the blood upon the altar: they killed also the lambs, and they sprinkled the blood upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 23, E'And they brought forth the he goats for the sin offering before the king and the congregation; and they laid their hands upon them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 24, E'And the priests killed them, and they made reconciliation with their blood upon the altar, to make an atonement for all Israel: for the king commanded that the burnt offering and the sin offering should be made for all Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 25, E'And he set the Levites in the house of the LORD with cymbals, with psalteries, and with harps, according to the commandment of David, and of Gad the king’s seer, and Nathan the prophet: for so was the commandment of the LORD by his prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 26, E'And the Levites stood with the instruments of David, and the priests with the trumpets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 27, E'And Hezekiah commanded to offer the burnt offering upon the altar. And when the burnt offering began, the song of the LORD began also with the trumpets, and with the instruments ordained by David king of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 28, E'And all the congregation worshipped, and the singers sang, and the trumpeters sounded: and all this continued until the burnt offering was finished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 29, E'And when they had made an end of offering, the king and all that were present with him bowed themselves, and worshipped.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 30, E'Moreover Hezekiah the king and the princes commanded the Levites to sing praise unto the LORD with the words of David, and of Asaph the seer. And they sang praises with gladness, and they bowed their heads and worshipped.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 31, E'Then Hezekiah answered and said, Now ye have consecrated yourselves unto the LORD, come near and bring sacrifices and thank offerings into the house of the LORD. And the congregation brought in sacrifices and thank offerings; and as many as were of a free heart burnt offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 32, E'And the number of the burnt offerings, which the congregation brought, was threescore and ten bullocks, an hundred rams, and two hundred lambs: all these were for a burnt offering to the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 33, E'And the consecrated things were six hundred oxen and three thousand sheep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 34, E'But the priests were too few, so that they could not flay all the burnt offerings: wherefore their brethren the Levites did help them, till the work was ended, and until the other priests had sanctified themselves: for the Levites were more upright in heart to sanctify themselves than the priests.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 35, E'And also the burnt offerings were in abundance, with the fat of the peace offerings, and the drink offerings for every burnt offering. So the service of the house of the LORD was set in order.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 29, 36, E'And Hezekiah rejoiced, and all the people, that God had prepared the people: for the thing was done suddenly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 1, E'And Hezekiah sent to all Israel and Judah, and wrote letters also to Ephraim and Manasseh, that they should come to the house of the LORD at Jerusalem, to keep the passover unto the LORD God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 2, E'For the king had taken counsel, and his princes, and all the congregation in Jerusalem, to keep the passover in the second month.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 3, E'For they could not keep it at that time, because the priests had not sanctified themselves sufficiently, neither had the people gathered themselves together to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 4, E'And the thing pleased the king and all the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 5, E'So they established a decree to make proclamation throughout all Israel, from Beersheba even to Dan, that they should come to keep the passover unto the LORD God of Israel at Jerusalem: for they had not done it of a long time in such sort as it was written.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 6, E'So the posts went with the letters from the king and his princes throughout all Israel and Judah, and according to the commandment of the king, saying, Ye children of Israel, turn again unto the LORD God of Abraham, Isaac, and Israel, and he will return to the remnant of you, that are escaped out of the hand of the kings of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 7, E'And be not ye like your fathers, and like your brethren, which trespassed against the LORD God of their fathers, who therefore gave them up to desolation, as ye see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 8, E'Now be ye not stiffnecked, as your fathers were, but yield yourselves unto the LORD, and enter into his sanctuary, which he hath sanctified for ever: and serve the LORD your God, that the fierceness of his wrath may turn away from you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 9, E'For if ye turn again unto the LORD, your brethren and your children shall find compassion before them that lead them captive, so that they shall come again into this land: for the LORD your God is gracious and merciful, and will not turn away his face from you, if ye return unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 10, E'So the posts passed from city to city through the country of Ephraim and Manasseh even unto Zebulun: but they laughed them to scorn, and mocked them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 11, E'Nevertheless divers of Asher and Manasseh and of Zebulun humbled themselves, and came to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 12, E'Also in Judah the hand of God was to give them one heart to do the commandment of the king and of the princes, by the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 13, E'And there assembled at Jerusalem much people to keep the feast of unleavened bread in the second month, a very great congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 14, E'And they arose and took away the altars that were in Jerusalem, and all the altars for incense took they away, and cast them into the brook Kidron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 15, E'Then they killed the passover on the fourteenth day of the second month: and the priests and the Levites were ashamed, and sanctified themselves, and brought in the burnt offerings into the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 16, E'And they stood in their place after their manner, according to the law of Moses the man of God: the priests sprinkled the blood, which they received of the hand of the Levites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 17, E'For there were many in the congregation that were not sanctified: therefore the Levites had the charge of the killing of the passovers for every one that was not clean, to sanctify them unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 18, E'For a multitude of the people, even many of Ephraim, and Manasseh, Issachar, and Zebulun, had not cleansed themselves, yet did they eat the passover otherwise than it was written. But Hezekiah prayed for them, saying, The good LORD pardon every one'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 19, E'That prepareth his heart to seek God, the LORD God of his fathers, though he be not cleansed according to the purification of the sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 20, E'And the LORD hearkened to Hezekiah, and healed the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 21, E'And the children of Israel that were present at Jerusalem kept the feast of unleavened bread seven days with great gladness: and the Levites and the priests praised the LORD day by day, singing with loud instruments unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 22, E'And Hezekiah spake comfortably unto all the Levites that taught the good knowledge of the LORD: and they did eat throughout the feast seven days, offering peace offerings, and making confession to the LORD God of their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 23, E'And the whole assembly took counsel to keep other seven days: and they kept other seven days with gladness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 24, E'For Hezekiah king of Judah did give to the congregation a thousand bullocks and seven thousand sheep; and the princes gave to the congregation a thousand bullocks and ten thousand sheep: and a great number of priests sanctified themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 25, E'And all the congregation of Judah, with the priests and the Levites, and all the congregation that came out of Israel, and the strangers that came out of the land of Israel, and that dwelt in Judah, rejoiced.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 26, E'So there was great joy in Jerusalem: for since the time of Solomon the son of David king of Israel there was not the like in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 30, 27, E'Then the priests the Levites arose and blessed the people: and their voice was heard, and their prayer came up to his holy dwelling place, even unto heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 1, E'Now when all this was finished, all Israel that were present went out to the cities of Judah, and brake the images in pieces, and cut down the groves, and threw down the high places and the altars out of all Judah and Benjamin, in Ephraim also and Manasseh, until they had utterly destroyed them all. Then all the children of Israel returned, every man to his possession, into their own cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 2, E'And Hezekiah appointed the courses of the priests and the Levites after their courses, every man according to his service, the priests and Levites for burnt offerings and for peace offerings, to minister, and to give thanks, and to praise in the gates of the tents of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 3, E'He appointed also the king’s portion of his substance for the burnt offerings, to wit, for the morning and evening burnt offerings, and the burnt offerings for the sabbaths, and for the new moons, and for the set feasts, as it is written in the law of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 4, E'Moreover he commanded the people that dwelt in Jerusalem to give the portion of the priests and the Levites, that they might be encouraged in the law of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 5, E'And as soon as the commandment came abroad, the children of Israel brought in abundance the firstfruits of corn, wine, and oil, and honey, and of all the increase of the field; and the tithe of all things brought they in abundantly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 6, E'And concerning the children of Israel and Judah, that dwelt in the cities of Judah, they also brought in the tithe of oxen and sheep, and the tithe of holy things which were consecrated unto the LORD their God, and laid them by heaps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 7, E'In the third month they began to lay the foundation of the heaps, and finished them in the seventh month.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 8, E'And when Hezekiah and the princes came and saw the heaps, they blessed the LORD, and his people Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 9, E'Then Hezekiah questioned with the priests and the Levites concerning the heaps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 10, E'And Azariah the chief priest of the house of Zadok answered him, and said, Since the people began to bring the offerings into the house of the LORD, we have had enough to eat, and have left plenty: for the LORD hath blessed his people; and that which is left is this great store.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 11, E'Then Hezekiah commanded to prepare chambers in the house of the LORD; and they prepared them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 12, E'And brought in the offerings and the tithes and the dedicated things faithfully: over which Cononiah the Levite was ruler, and Shimei his brother was the next.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 13, E'And Jehiel, and Azaziah, and Nahath, and Asahel, and Jerimoth, and Jozabad, and Eliel, and Ismachiah, and Mahath, and Benaiah, were overseers under the hand of Cononiah and Shimei his brother, at the commandment of Hezekiah the king, and Azariah the ruler of the house of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 14, E'And Kore the son of Imnah the Levite, the porter toward the east, was over the freewill offerings of God, to distribute the oblations of the LORD, and the most holy things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 15, E'And next him were Eden, and Miniamin, and Jeshua, and Shemaiah, Amariah, and Shecaniah, in the cities of the priests, in their set office, to give to their brethren by courses, as well to the great as to the small:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 16, E'Beside their genealogy of males, from three years old and upward, even unto every one that entereth into the house of the LORD, his daily portion for their service in their charges according to their courses;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 17, E'Both to the genealogy of the priests by the house of their fathers, and the Levites from twenty years old and upward, in their charges by their courses;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 18, E'And to the genealogy of all their little ones, their wives, and their sons, and their daughters, through all the congregation: for in their set office they sanctified themselves in holiness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 19, E'Also of the sons of Aaron the priests, which were in the fields of the suburbs of their cities, in every several city, the men that were expressed by name, to give portions to all the males among the priests, and to all that were reckoned by genealogies among the Levites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 20, E'And thus did Hezekiah throughout all Judah, and wrought that which was good and right and truth before the LORD his God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 31, 21, E'And in every work that he began in the service of the house of God, and in the law, and in the commandments, to seek his God, he did it with all his heart, and prospered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 1, E'After these things, and the establishment thereof, Sennacherib king of Assyria came, and entered into Judah, and encamped against the fenced cities, and thought to win them for himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 2, E'And when Hezekiah saw that Sennacherib was come, and that he was purposed to fight against Jerusalem,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 3, E'He took counsel with his princes and his mighty men to stop the waters of the fountains which were without the city: and they did help him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 4, E'So there was gathered much people together, who stopped all the fountains, and the brook that ran through the midst of the land, saying, Why should the kings of Assyria come, and find much water?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 5, E'Also he strengthened himself, and built up all the wall that was broken, and raised it up to the towers, and another wall without, and repaired Millo in the city of David, and made darts and shields in abundance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 6, E'And he set captains of war over the people, and gathered them together to him in the street of the gate of the city, and spake comfortably to them, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 7, E'Be strong and courageous, be not afraid nor dismayed for the king of Assyria, nor for all the multitude that is with him: for there be more with us than with him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 8, E'With him is an arm of flesh; but with us is the LORD our God to help us, and to fight our battles. And the people rested themselves upon the words of Hezekiah king of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 9, E'After this did Sennacherib king of Assyria send his servants to Jerusalem, (but he himself laid siege against Lachish, and all his power with him,) unto Hezekiah king of Judah, and unto all Judah that were at Jerusalem, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 10, E'Thus saith Sennacherib king of Assyria, Whereon do ye trust, that ye abide in the siege in Jerusalem?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 11, E'Doth not Hezekiah persuade you to give over yourselves to die by famine and by thirst, saying, The LORD our God shall deliver us out of the hand of the king of Assyria?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 12, E'Hath not the same Hezekiah taken away his high places and his altars, and commanded Judah and Jerusalem, saying, Ye shall worship before one altar, and burn incense upon it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 13, E'Know ye not what I and my fathers have done unto all the people of other lands? were the gods of the nations of those lands any ways able to deliver their lands out of mine hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 14, E'Who was there among all the gods of those nations that my fathers utterly destroyed, that could deliver his people out of mine hand, that your God should be able to deliver you out of mine hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 15, E'Now therefore let not Hezekiah deceive you, nor persuade you on this manner, neither yet believe him: for no god of any nation or kingdom was able to deliver his people out of mine hand, and out of the hand of my fathers: how much less shall your God deliver you out of mine hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 16, E'And his servants spake yet more against the LORD God, and against his servant Hezekiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 17, E'He wrote also letters to rail on the LORD God of Israel, and to speak against him, saying, As the gods of the nations of other lands have not delivered their people out of mine hand, so shall not the God of Hezekiah deliver his people out of mine hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 18, E'Then they cried with a loud voice in the Jews’ speech unto the people of Jerusalem that were on the wall, to affright them, and to trouble them; that they might take the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 19, E'And they spake against the God of Jerusalem, as against the gods of the people of the earth, which were the work of the hands of man.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Chronicles') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 20, E'And for this cause Hezekiah the king, and the prophet Isaiah the son of Amoz, prayed and cried to heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 21, E'And the LORD sent an angel, which cut off all the mighty men of valour, and the leaders and captains in the camp of the king of Assyria. So he returned with shame of face to his own land. And when he was come into the house of his god, they that came forth of his own bowels slew him there with the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 22, E'Thus the LORD saved Hezekiah and the inhabitants of Jerusalem from the hand of Sennacherib the king of Assyria, and from the hand of all other, and guided them on every side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 23, E'And many brought gifts unto the LORD to Jerusalem, and presents to Hezekiah king of Judah: so that he was magnified in the sight of all nations from thenceforth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 24, E'In those days Hezekiah was sick to the death, and prayed unto the LORD: and he spake unto him, and he gave him a sign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 25, E'But Hezekiah rendered not again according to the benefit done unto him; for his heart was lifted up: therefore there was wrath upon him, and upon Judah and Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 26, E'Notwithstanding Hezekiah humbled himself for the pride of his heart, both he and the inhabitants of Jerusalem, so that the wrath of the LORD came not upon them in the days of Hezekiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 27, E'And Hezekiah had exceeding much riches and honour: and he made himself treasuries for silver, and for gold, and for precious stones, and for spices, and for shields, and for all manner of pleasant jewels;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 28, E'Storehouses also for the increase of corn, and wine, and oil; and stalls for all manner of beasts, and cotes for flocks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 29, E'Moreover he provided him cities, and possessions of flocks and herds in abundance: for God had given him substance very much.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 30, E'This same Hezekiah also stopped the upper watercourse of Gihon, and brought it straight down to the west side of the city of David. And Hezekiah prospered in all his works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 31, E'Howbeit in the business of the ambassadors of the princes of Babylon, who sent unto him to enquire of the wonder that was done in the land, God left him, to try him, that he might know all that was in his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 32, E'Now the rest of the acts of Hezekiah, and his goodness, behold, they are written in the vision of Isaiah the prophet, the son of Amoz, and in the book of the kings of Judah and Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 32, 33, E'And Hezekiah slept with his fathers, and they buried him in the chiefest of the sepulchres of the sons of David: and all Judah and the inhabitants of Jerusalem did him honour at his death. And Manasseh his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 1, E'Manasseh was twelve years old when he began to reign, and he reigned fifty and five years in Jerusalem:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 2, E'But did that which was evil in the sight of the LORD, like unto the abominations of the heathen, whom the LORD had cast out before the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 3, E'For he built again the high places which Hezekiah his father had broken down, and he reared up altars for Baalim, and made groves, and worshipped all the host of heaven, and served them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 4, E'Also he built altars in the house of the LORD, whereof the LORD had said, In Jerusalem shall my name be for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 5, E'And he built altars for all the host of heaven in the two courts of the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 6, E'And he caused his children to pass through the fire in the valley of the son of Hinnom: also he observed times, and used enchantments, and used witchcraft, and dealt with a familiar spirit, and with wizards: he wrought much evil in the sight of the LORD, to provoke him to anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 7, E'And he set a carved image, the idol which he had made, in the house of God, of which God had said to David and to Solomon his son, In this house, and in Jerusalem, which I have chosen before all the tribes of Israel, will I put my name for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 8, E'Neither will I any more remove the foot of Israel from out of the land which I have appointed for your fathers; so that they will take heed to do all that I have commanded them, according to the whole law and the statutes and the ordinances by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 9, E'So Manasseh made Judah and the inhabitants of Jerusalem to err, and to do worse than the heathen, whom the LORD had destroyed before the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 10, E'And the LORD spake to Manasseh, and to his people: but they would not hearken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 11, E'Wherefore the LORD brought upon them the captains of the host of the king of Assyria, which took Manasseh among the thorns, and bound him with fetters, and carried him to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 12, E'And when he was in affliction, he besought the LORD his God, and humbled himself greatly before the God of his fathers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 13, E'And prayed unto him: and he was intreated of him, and heard his supplication, and brought him again to Jerusalem into his kingdom. Then Manasseh knew that the LORD he was God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 14, E'Now after this he built a wall without the city of David, on the west side of Gihon, in the valley, even to the entering in at the fish gate, and compassed about Ophel, and raised it up a very great height, and put captains of war in all the fenced cities of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 15, E'And he took away the strange gods, and the idol out of the house of the LORD, and all the altars that he had built in the mount of the house of the LORD, and in Jerusalem, and cast them out of the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 16, E'And he repaired the altar of the LORD, and sacrificed thereon peace offerings and thank offerings, and commanded Judah to serve the LORD God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 17, E'Nevertheless the people did sacrifice still in the high places, yet unto the LORD their God only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 18, E'Now the rest of the acts of Manasseh, and his prayer unto his God, and the words of the seers that spake to him in the name of the LORD God of Israel, behold, they are written in the book of the kings of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 19, E'His prayer also, and how God was intreated of him, and all his sins, and his trespass, and the places wherein he built high places, and set up groves and graven images, before he was humbled: behold, they are written among the sayings of the seers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 20, E'So Manasseh slept with his fathers, and they buried him in his own house: and Amon his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 21, E'Amon was two and twenty years old when he began to reign, and reigned two years in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 22, E'But he did that which was evil in the sight of the LORD, as did Manasseh his father: for Amon sacrificed unto all the carved images which Manasseh his father had made, and served them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 23, E'And humbled not himself before the LORD, as Manasseh his father had humbled himself; but Amon trespassed more and more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 24, E'And his servants conspired against him, and slew him in his own house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 33, 25, E'But the people of the land slew all them that had conspired against king Amon; and the people of the land made Josiah his son king in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 1, E'Josiah was eight years old when he began to reign, and he reigned in Jerusalem one and thirty years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 2, E'And he did that which was right in the sight of the LORD, and walked in the ways of David his father, and declined neither to the right hand, nor to the left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 3, E'For in the eighth year of his reign, while he was yet young, he began to seek after the God of David his father: and in the twelfth year he began to purge Judah and Jerusalem from the high places, and the groves, and the carved images, and the molten images.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 4, E'And they brake down the altars of Baalim in his presence; and the images, that were on high above them, he cut down; and the groves, and the carved images, and the molten images, he brake in pieces, and made dust of them, and strowed it upon the graves of them that had sacrificed unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 5, E'And he burnt the bones of the priests upon their altars, and cleansed Judah and Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 6, E'And so did he in the cities of Manasseh, and Ephraim, and Simeon, even unto Naphtali, with their mattocks round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 7, E'And when he had broken down the altars and the groves, and had beaten the graven images into powder, and cut down all the idols throughout all the land of Israel, he returned to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 8, E'Now in the eighteenth year of his reign, when he had purged the land, and the house, he sent Shaphan the son of Azaliah, and Maaseiah the governor of the city, and Joah the son of Joahaz the recorder, to repair the house of the LORD his God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 9, E'And when they came to Hilkiah the high priest, they delivered the money that was brought into the house of God, which the Levites that kept the doors had gathered of the hand of Manasseh and Ephraim, and of all the remnant of Israel, and of all Judah and Benjamin; and they returned to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 10, E'And they put it in the hand of the workmen that had the oversight of the house of the LORD, and they gave it to the workmen that wrought in the house of the LORD, to repair and amend the house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 11, E'Even to the artificers and builders gave they it, to buy hewn stone, and timber for couplings, and to floor the houses which the kings of Judah had destroyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 12, E'And the men did the work faithfully: and the overseers of them were Jahath and Obadiah, the Levites, of the sons of Merari; and Zechariah and Meshullam, of the sons of the Kohathites, to set it forward; and other of the Levites, all that could skill of instruments of musick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 13, E'Also they were over the bearers of burdens, and were overseers of all that wrought the work in any manner of service: and of the Levites there were scribes, and officers, and porters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 14, E'And when they brought out the money that was brought into the house of the LORD, Hilkiah the priest found a book of the law of the LORD given by Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 15, E'And Hilkiah answered and said to Shaphan the scribe, I have found the book of the law in the house of the LORD. And Hilkiah delivered the book to Shaphan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 16, E'And Shaphan carried the book to the king, and brought the king word back again, saying, All that was committed to thy servants, they do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 17, E'And they have gathered together the money that was found in the house of the LORD, and have delivered it into the hand of the overseers, and to the hand of the workmen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 18, E'Then Shaphan the scribe told the king, saying, Hilkiah the priest hath given me a book. And Shaphan read it before the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 19, E'And it came to pass, when the king had heard the words of the law, that he rent his clothes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 20, E'And the king commanded Hilkiah, and Ahikam the son of Shaphan, and Abdon the son of Micah, and Shaphan the scribe, and Asaiah a servant of the king’s, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 21, E'Go, enquire of the LORD for me, and for them that are left in Israel and in Judah, concerning the words of the book that is found: for great is the wrath of the LORD that is poured out upon us, because our fathers have not kept the word of the LORD, to do after all that is written in this book.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 22, E'And Hilkiah, and they that the king had appointed, went to Huldah the prophetess, the wife of Shallum the son of Tikvath, the son of Hasrah, keeper of the wardrobe; (now she dwelt in Jerusalem in the college:) and they spake to her to that effect.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 23, E'And she answered them, Thus saith the LORD God of Israel, Tell ye the man that sent you to me,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 24, E'Thus saith the LORD, Behold, I will bring evil upon this place, and upon the inhabitants thereof, even all the curses that are written in the book which they have read before the king of Judah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 25, E'Because they have forsaken me, and have burned incense unto other gods, that they might provoke me to anger with all the works of their hands; therefore my wrath shall be poured out upon this place, and shall not be quenched.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 26, E'And as for the king of Judah, who sent you to enquire of the LORD, so shall ye say unto him, Thus saith the LORD God of Israel concerning the words which thou hast heard;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 27, E'Because thine heart was tender, and thou didst humble thyself before God, when thou heardest his words against this place, and against the inhabitants thereof, and humbledst thyself before me, and didst rend thy clothes, and weep before me; I have even heard thee also, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 28, E'Behold, I will gather thee to thy fathers, and thou shalt be gathered to thy grave in peace, neither shall thine eyes see all the evil that I will bring upon this place, and upon the inhabitants of the same. So they brought the king word again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 29, E'Then the king sent and gathered together all the elders of Judah and Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 30, E'And the king went up into the house of the LORD, and all the men of Judah, and the inhabitants of Jerusalem, and the priests, and the Levites, and all the people, great and small: and he read in their ears all the words of the book of the covenant that was found in the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 31, E'And the king stood in his place, and made a covenant before the LORD, to walk after the LORD, and to keep his commandments, and his testimonies, and his statutes, with all his heart, and with all his soul, to perform the words of the covenant which are written in this book.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 32, E'And he caused all that were present in Jerusalem and Benjamin to stand to it. And the inhabitants of Jerusalem did according to the covenant of God, the God of their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 34, 33, E'And Josiah took away all the abominations out of all the countries that pertained to the children of Israel, and made all that were present in Israel to serve, even to serve the LORD their God. And all his days they departed not from following the LORD, the God of their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 1, E'Moreover Josiah kept a passover unto the LORD in Jerusalem: and they killed the passover on the fourteenth day of the first month.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 2, E'And he set the priests in their charges, and encouraged them to the service of the house of the LORD,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 3, E'And said unto the Levites that taught all Israel, which were holy unto the LORD, Put the holy ark in the house which Solomon the son of David king of Israel did build; it shall not be a burden upon your shoulders: serve now the LORD your God, and his people Israel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 4, E'And prepare yourselves by the houses of your fathers, after your courses, according to the writing of David king of Israel, and according to the writing of Solomon his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 5, E'And stand in the holy place according to the divisions of the families of the fathers of your brethren the people, and after the division of the families of the Levites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 6, E'So kill the passover, and sanctify yourselves, and prepare your brethren, that they may do according to the word of the LORD by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 7, E'And Josiah gave to the people, of the flock, lambs and kids, all for the passover offerings, for all that were present, to the number of thirty thousand, and three thousand bullocks: these were of the king’s substance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 8, E'And his princes gave willingly unto the people, to the priests, and to the Levites: Hilkiah and Zechariah and Jehiel, rulers of the house of God, gave unto the priests for the passover offerings two thousand and six hundred small cattle, and three hundred oxen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 9, E'Conaniah also, and Shemaiah and Nethaneel, his brethren, and Hashabiah and Jeiel and Jozabad, chief of the Levites, gave unto the Levites for passover offerings five thousand small cattle, and five hundred oxen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 10, E'So the service was prepared, and the priests stood in their place, and the Levites in their courses, according to the king’s commandment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 11, E'And they killed the passover, and the priests sprinkled the blood from their hands, and the Levites flayed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 12, E'And they removed the burnt offerings, that they might give according to the divisions of the families of the people, to offer unto the LORD, as it is written in the book of Moses. And so did they with the oxen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 13, E'And they roasted the passover with fire according to the ordinance: but the other holy offerings sod they in pots, and in caldrons, and in pans, and divided them speedily among all the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 14, E'And afterward they made ready for themselves, and for the priests: because the priests the sons of Aaron were busied in offering of burnt offerings and the fat until night; therefore the Levites prepared for themselves, and for the priests the sons of Aaron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 15, E'And the singers the sons of Asaph were in their place, according to the commandment of David, and Asaph, and Heman, and Jeduthun the king’s seer; and the porters waited at every gate; they might not depart from their service; for their brethren the Levites prepared for them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 16, E'So all the service of the LORD was prepared the same day, to keep the passover, and to offer burnt offerings upon the altar of the LORD, according to the commandment of king Josiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 17, E'And the children of Israel that were present kept the passover at that time, and the feast of unleavened bread seven days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 18, E'And there was no passover like to that kept in Israel from the days of Samuel the prophet; neither did all the kings of Israel keep such a passover as Josiah kept, and the priests, and the Levites, and all Judah and Israel that were present, and the inhabitants of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 19, E'In the eighteenth year of the reign of Josiah was this passover kept.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 20, E'After all this, when Josiah had prepared the temple, Necho king of Egypt came up to fight against Charchemish by Euphrates: and Josiah went out against him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 21, E'But he sent ambassadors to him, saying, What have I to do with thee, thou king of Judah? I come not against thee this day, but against the house wherewith I have war: for God commanded me to make haste: forbear thee from meddling with God, who is with me, that he destroy thee not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 22, E'Nevertheless Josiah would not turn his face from him, but disguised himself, that he might fight with him, and hearkened not unto the words of Necho from the mouth of God, and came to fight in the valley of Megiddo.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 23, E'And the archers shot at king Josiah; and the king said to his servants, Have me away; for I am sore wounded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 24, E'His servants therefore took him out of that chariot, and put him in the second chariot that he had; and they brought him to Jerusalem, and he died, and was buried in one of the sepulchres of his fathers. And all Judah and Jerusalem mourned for Josiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 25, E'And Jeremiah lamented for Josiah: and all the singing men and the singing women spake of Josiah in their lamentations to this day, and made them an ordinance in Israel: and, behold, they are written in the lamentations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 26, E'Now the rest of the acts of Josiah, and his goodness, according to that which was written in the law of the LORD,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 35, 27, E'And his deeds, first and last, behold, they are written in the book of the kings of Israel and Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 1, E'Then the people of the land took Jehoahaz the son of Josiah, and made him king in his father’s stead in Jerusalem.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Chronicles') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 2, E'Jehoahaz was twenty and three years old when he began to reign, and he reigned three months in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 3, E'And the king of Egypt put him down at Jerusalem, and condemned the land in an hundred talents of silver and a talent of gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 4, E'And the king of Egypt made Eliakim his brother king over Judah and Jerusalem, and turned his name to Jehoiakim. And Necho took Jehoahaz his brother, and carried him to Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 5, E'Jehoiakim was twenty and five years old when he began to reign, and he reigned eleven years in Jerusalem: and he did that which was evil in the sight of the LORD his God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 6, E'Against him came up Nebuchadnezzar king of Babylon, and bound him in fetters, to carry him to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 7, E'Nebuchadnezzar also carried of the vessels of the house of the LORD to Babylon, and put them in his temple at Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 8, E'Now the rest of the acts of Jehoiakim, and his abominations which he did, and that which was found in him, behold, they are written in the book of the kings of Israel and Judah: and Jehoiachin his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 9, E'Jehoiachin was eight years old when he began to reign, and he reigned three months and ten days in Jerusalem: and he did that which was evil in the sight of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 10, E'And when the year was expired, king Nebuchadnezzar sent, and brought him to Babylon, with the goodly vessels of the house of the LORD, and made Zedekiah his brother king over Judah and Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 11, E'Zedekiah was one and twenty years old when he began to reign, and reigned eleven years in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 12, E'And he did that which was evil in the sight of the LORD his God, and humbled not himself before Jeremiah the prophet speaking from the mouth of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 13, E'And he also rebelled against king Nebuchadnezzar, who had made him swear by God: but he stiffened his neck, and hardened his heart from turning unto the LORD God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 14, E'Moreover all the chief of the priests, and the people, transgressed very much after all the abominations of the heathen; and polluted the house of the LORD which he had hallowed in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 15, E'And the LORD God of their fathers sent to them by his messengers, rising up betimes, and sending; because he had compassion on his people, and on his dwelling place:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 16, E'But they mocked the messengers of God, and despised his words, and misused his prophets, until the wrath of the LORD arose against his people, till there was no remedy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 17, E'Therefore he brought upon them the king of the Chaldees, who slew their young men with the sword in the house of their sanctuary, and had no compassion upon young man or maiden, old man, or him that stooped for age: he gave them all into his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 18, E'And all the vessels of the house of God, great and small, and the treasures of the house of the LORD, and the treasures of the king, and of his princes; all these he brought to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 19, E'And they burnt the house of God, and brake down the wall of Jerusalem, and burnt all the palaces thereof with fire, and destroyed all the goodly vessels thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 20, E'And them that had escaped from the sword carried he away to Babylon; where they were servants to him and his sons until the reign of the kingdom of Persia:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 21, E'To fulfil the word of the LORD by the mouth of Jeremiah, until the land had enjoyed her sabbaths: for as long as she lay desolate she kept sabbath, to fulfil threescore and ten years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 22, E'Now in the first year of Cyrus king of Persia, that the word of the LORD spoken by the mouth of Jeremiah might be accomplished, the LORD stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'cf495da6-5338-42eb-afed-f04e50133974', 36, 23, E'Thus saith Cyrus king of Persia, All the kingdoms of the earth hath the LORD God of heaven given me; and he hath charged me to build him an house in Jerusalem, which is in Judah. Who is there among you of all his people? The LORD his God be with him, and let him go up.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Chronicles') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 1, 1, E'Now in the first year of Cyrus king of Persia, that the word of the LORD by the mouth of Jeremiah might be fulfilled, the LORD stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 1, 2, E'Thus saith Cyrus king of Persia, The LORD God of heaven hath given me all the kingdoms of the earth; and he hath charged me to build him an house at Jerusalem, which is in Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 1, 3, E'Who is there among you of all his people? his God be with him, and let him go up to Jerusalem, which is in Judah, and build the house of the LORD God of Israel, (he is the God,) which is in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 1, 4, E'And whosoever remaineth in any place where he sojourneth, let the men of his place help him with silver, and with gold, and with goods, and with beasts, beside the freewill offering for the house of God that is in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 1, 5, E'Then rose up the chief of the fathers of Judah and Benjamin, and the priests, and the Levites, with all them whose spirit God had raised, to go up to build the house of the LORD which is in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 1, 6, E'And all they that were about them strengthened their hands with vessels of silver, with gold, with goods, and with beasts, and with precious things, beside all that was willingly offered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 1, 7, E'Also Cyrus the king brought forth the vessels of the house of the LORD, which Nebuchadnezzar had brought forth out of Jerusalem, and had put them in the house of his gods;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 1, 8, E'Even those did Cyrus king of Persia bring forth by the hand of Mithredath the treasurer, and numbered them unto Sheshbazzar, the prince of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 1, 9, E'And this is the number of them: thirty chargers of gold, a thousand chargers of silver, nine and twenty knives,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 1, 10, E'Thirty basons of gold, silver basons of a second sort four hundred and ten, and other vessels a thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 1, 11, E'All the vessels of gold and of silver were five thousand and four hundred. All these did Sheshbazzar bring up with them of the captivity that were brought up from Babylon unto Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 1, E'Now these are the children of the province that went up out of the captivity, of those which had been carried away, whom Nebuchadnezzar the king of Babylon had carried away unto Babylon, and came again unto Jerusalem and Judah, every one unto his city;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 2, E'Which came with Zerubbabel: Jeshua, Nehemiah, Seraiah, Reelaiah, Mordecai, Bilshan, Mizpar, Bigvai, Rehum, Baanah. The number of the men of the people of Israel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 3, E'The children of Parosh, two thousand an hundred seventy and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 4, E'The children of Shephatiah, three hundred seventy and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 5, E'The children of Arah, seven hundred seventy and five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 6, E'The children of Pahathmoab, of the children of Jeshua and Joab, two thousand eight hundred and twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 7, E'The children of Elam, a thousand two hundred fifty and four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 8, E'The children of Zattu, nine hundred forty and five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 9, E'The children of Zaccai, seven hundred and threescore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 10, E'The children of Bani, six hundred forty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 11, E'The children of Bebai, six hundred twenty and three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 12, E'The children of Azgad, a thousand two hundred twenty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 13, E'The children of Adonikam, six hundred sixty and six.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 14, E'The children of Bigvai, two thousand fifty and six.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 15, E'The children of Adin, four hundred fifty and four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 16, E'The children of Ater of Hezekiah, ninety and eight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 17, E'The children of Bezai, three hundred twenty and three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 18, E'The children of Jorah, an hundred and twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 19, E'The children of Hashum, two hundred twenty and three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 20, E'The children of Gibbar, ninety and five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 21, E'The children of Bethlehem, an hundred twenty and three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 22, E'The men of Netophah, fifty and six.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 23, E'The men of Anathoth, an hundred twenty and eight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 24, E'The children of Azmaveth, forty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 25, E'The children of Kirjatharim, Chephirah, and Beeroth, seven hundred and forty and three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 26, E'The children of Ramah and Gaba, six hundred twenty and one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 27, E'The men of Michmas, an hundred twenty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 28, E'The men of Bethel and Ai, two hundred twenty and three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 29, E'The children of Nebo, fifty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 30, E'The children of Magbish, an hundred fifty and six.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 31, E'The children of the other Elam, a thousand two hundred fifty and four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 32, E'The children of Harim, three hundred and twenty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 33, E'The children of Lod, Hadid, and Ono, seven hundred twenty and five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 34, E'The children of Jericho, three hundred forty and five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 35, E'The children of Senaah, three thousand and six hundred and thirty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 36, E'The priests: the children of Jedaiah, of the house of Jeshua, nine hundred seventy and three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 37, E'The children of Immer, a thousand fifty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 38, E'The children of Pashur, a thousand two hundred forty and seven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 39, E'The children of Harim, a thousand and seventeen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 40, E'The Levites: the children of Jeshua and Kadmiel, of the children of Hodaviah, seventy and four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 41, E'The singers: the children of Asaph, an hundred twenty and eight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 42, E'The children of the porters: the children of Shallum, the children of Ater, the children of Talmon, the children of Akkub, the children of Hatita, the children of Shobai, in all an hundred thirty and nine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 43, E'The Nethinims: the children of Ziha, the children of Hasupha, the children of Tabbaoth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 44, E'The children of Keros, the children of Siaha, the children of Padon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 45, E'The children of Lebanah, the children of Hagabah, the children of Akkub,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 46, E'The children of Hagab, the children of Shalmai, the children of Hanan,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 47, E'The children of Giddel, the children of Gahar, the children of Reaiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 48, E'The children of Rezin, the children of Nekoda, the children of Gazzam,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 49, E'The children of Uzza, the children of Paseah, the children of Besai,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 50, E'The children of Asnah, the children of Mehunim, the children of Nephusim,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 51, E'The children of Bakbuk, the children of Hakupha, the children of Harhur,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 52, E'The children of Bazluth, the children of Mehida, the children of Harsha,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 53, E'The children of Barkos, the children of Sisera, the children of Thamah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 54, E'The children of Neziah, the children of Hatipha.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 55, E'The children of Solomon’s servants: the children of Sotai, the children of Sophereth, the children of Peruda,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 56, E'The children of Jaalah, the children of Darkon, the children of Giddel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 57, E'The children of Shephatiah, the children of Hattil, the children of Pochereth of Zebaim, the children of Ami.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 58, E'All the Nethinims, and the children of Solomon’s servants, were three hundred ninety and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 59, E'And these were they which went up from Telmelah, Telharsa, Cherub, Addan, and Immer: but they could not shew their father’s house, and their seed, whether they were of Israel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 60, E'The children of Delaiah, the children of Tobiah, the children of Nekoda, six hundred fifty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 61, E'And of the children of the priests: the children of Habaiah, the children of Koz, the children of Barzillai; which took a wife of the daughters of Barzillai the Gileadite, and was called after their name:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 62, E'These sought their register among those that were reckoned by genealogy, but they were not found: therefore were they, as polluted, put from the priesthood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 63, E'And the Tirshatha said unto them, that they should not eat of the most holy things, till there stood up a priest with Urim and with Thummim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 64, E'The whole congregation together was forty and two thousand three hundred and threescore,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 65, E'Beside their servants and their maids, of whom there were seven thousand three hundred thirty and seven: and there were among them two hundred singing men and singing women.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 66, E'Their horses were seven hundred thirty and six; their mules, two hundred forty and five;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 67, E'Their camels, four hundred thirty and five; their asses, six thousand seven hundred and twenty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 68, E'And some of the chief of the fathers, when they came to the house of the LORD which is at Jerusalem, offered freely for the house of God to set it up in his place:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 69, E'They gave after their ability unto the treasure of the work threescore and one thousand drams of gold, and five thousand pound of silver, and one hundred priests’ garments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 2, 70, E'So the priests, and the Levites, and some of the people, and the singers, and the porters, and the Nethinims, dwelt in their cities, and all Israel in their cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 1, E'And when the seventh month was come, and the children of Israel were in the cities, the people gathered themselves together as one man to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 2, E'Then stood up Jeshua the son of Jozadak, and his brethren the priests, and Zerubbabel the son of Shealtiel, and his brethren, and builded the altar of the God of Israel, to offer burnt offerings thereon, as it is written in the law of Moses the man of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 3, E'And they set the altar upon his bases; for fear was upon them because of the people of those countries: and they offered burnt offerings thereon unto the LORD, even burnt offerings morning and evening.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 4, E'They kept also the feast of tabernacles, as it is written, and offered the daily burnt offerings by number, according to the custom, as the duty of every day required;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 5, E'And afterward offered the continual burnt offering, both of the new moons, and of all the set feasts of the LORD that were consecrated, and of every one that willingly offered a freewill offering unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 6, E'From the first day of the seventh month began they to offer burnt offerings unto the LORD. But the foundation of the temple of the LORD was not yet laid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 7, E'They gave money also unto the masons, and to the carpenters; and meat, and drink, and oil, unto them of Zidon, and to them of Tyre, to bring cedar trees from Lebanon to the sea of Joppa, according to the grant that they had of Cyrus king of Persia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 8, E'Now in the second year of their coming unto the house of God at Jerusalem, in the second month, began Zerubbabel the son of Shealtiel, and Jeshua the son of Jozadak, and the remnant of their brethren the priests and the Levites, and all they that were come out of the captivity unto Jerusalem; and appointed the Levites, from twenty years old and upward, to set forward the work of the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 9, E'Then stood Jeshua with his sons and his brethren, Kadmiel and his sons, the sons of Judah, together, to set forward the workmen in the house of God: the sons of Henadad, with their sons and their brethren the Levites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 10, E'And when the builders laid the foundation of the temple of the LORD, they set the priests in their apparel with trumpets, and the Levites the sons of Asaph with cymbals, to praise the LORD, after the ordinance of David king of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 11, E'And they sang together by course in praising and giving thanks unto the LORD; because he is good, for his mercy endureth for ever toward Israel. And all the people shouted with a great shout, when they praised the LORD, because the foundation of the house of the LORD was laid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 12, E'But many of the priests and Levites and chief of the fathers, who were ancient men, that had seen the first house, when the foundation of this house was laid before their eyes, wept with a loud voice; and many shouted aloud for joy:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 3, 13, E'So that the people could not discern the noise of the shout of joy from the noise of the weeping of the people: for the people shouted with a loud shout, and the noise was heard afar off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 1, E'Now when the adversaries of Judah and Benjamin heard that the children of the captivity builded the temple unto the LORD God of Israel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 2, E'Then they came to Zerubbabel, and to the chief of the fathers, and said unto them, Let us build with you: for we seek your God, as ye do; and we do sacrifice unto him since the days of Esarhaddon king of Assur, which brought us up hither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 3, E'But Zerubbabel, and Jeshua, and the rest of the chief of the fathers of Israel, said unto them, Ye have nothing to do with us to build an house unto our God; but we ourselves together will build unto the LORD God of Israel, as king Cyrus the king of Persia hath commanded us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 4, E'Then the people of the land weakened the hands of the people of Judah, and troubled them in building,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 5, E'And hired counsellors against them, to frustrate their purpose, all the days of Cyrus king of Persia, even until the reign of Darius king of Persia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 6, E'And in the reign of Ahasuerus, in the beginning of his reign, wrote they unto him an accusation against the inhabitants of Judah and Jerusalem.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Ezra') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 7, E'And in the days of Artaxerxes wrote Bishlam, Mithredath, Tabeel, and the rest of their companions, unto Artaxerxes king of Persia; and the writing of the letter was written in the Syrian tongue, and interpreted in the Syrian tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 8, E'Rehum the chancellor and Shimshai the scribe wrote a letter against Jerusalem to Artaxerxes the king in this sort:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 9, E'Then wrote Rehum the chancellor, and Shimshai the scribe, and the rest of their companions; the Dinaites, the Apharsathchites, the Tarpelites, the Apharsites, the Archevites, the Babylonians, the Susanchites, the Dehavites, and the Elamites,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 10, E'And the rest of the nations whom the great and noble Asnapper brought over, and set in the cities of Samaria, and the rest that are on this side the river, and at such a time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 11, E'This is the copy of the letter that they sent unto him, even unto Artaxerxes the king; Thy servants the men on this side the river, and at such a time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 12, E'Be it known unto the king, that the Jews which came up from thee to us are come unto Jerusalem, building the rebellious and the bad city, and have set up the walls thereof, and joined the foundations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 13, E'Be it known now unto the king, that, if this city be builded, and the walls set up again, then will they not pay toll, tribute, and custom, and so thou shalt endamage the revenue of the kings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 14, E'Now because we have maintenance from the king’s palace, and it was not meet for us to see the king’s dishonour, therefore have we sent and certified the king;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 15, E'That search may be made in the book of the records of thy fathers: so shalt thou find in the book of the records, and know that this city is a rebellious city, and hurtful unto kings and provinces, and that they have moved sedition within the same of old time: for which cause was this city destroyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 16, E'We certify the king that, if this city be builded again, and the walls thereof set up, by this means thou shalt have no portion on this side the river.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 17, E'Then sent the king an answer unto Rehum the chancellor, and to Shimshai the scribe, and to the rest of their companions that dwell in Samaria, and unto the rest beyond the river, Peace, and at such a time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 18, E'The letter which ye sent unto us hath been plainly read before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 19, E'And I commanded, and search hath been made, and it is found that this city of old time hath made insurrection against kings, and that rebellion and sedition have been made therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 20, E'There have been mighty kings also over Jerusalem, which have ruled over all countries beyond the river; and toll, tribute, and custom, was paid unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 21, E'Give ye now commandment to cause these men to cease, and that this city be not builded, until another commandment shall be given from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 22, E'Take heed now that ye fail not to do this: why should damage grow to the hurt of the kings?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 23, E'Now when the copy of king Artaxerxes’ letter was read before Rehum, and Shimshai the scribe, and their companions, they went up in haste to Jerusalem unto the Jews, and made them to cease by force and power.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 4, 24, E'Then ceased the work of the house of God which is at Jerusalem. So it ceased unto the second year of the reign of Darius king of Persia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 1, E'Then the prophets, Haggai the prophet, and Zechariah the son of Iddo, prophesied unto the Jews that were in Judah and Jerusalem in the name of the God of Israel, even unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 2, E'Then rose up Zerubbabel the son of Shealtiel, and Jeshua the son of Jozadak, and began to build the house of God which is at Jerusalem: and with them were the prophets of God helping them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 3, E'At the same time came to them Tatnai, governor on this side the river, and Shetharboznai, and their companions, and said thus unto them, Who hath commanded you to build this house, and to make up this wall?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 4, E'Then said we unto them after this manner, What are the names of the men that make this building?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 5, E'But the eye of their God was upon the elders of the Jews, that they could not cause them to cease, till the matter came to Darius: and then they returned answer by letter concerning this matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 6, E'The copy of the letter that Tatnai, governor on this side the river, and Shetharboznai, and his companions the Apharsachites, which were on this side the river, sent unto Darius the king:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 7, E'They sent a letter unto him, wherein was written thus; Unto Darius the king, all peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 8, E'Be it known unto the king, that we went into the province of Judea, to the house of the great God, which is builded with great stones, and timber is laid in the walls, and this work goeth fast on, and prospereth in their hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 9, E'Then asked we those elders, and said unto them thus, Who commanded you to build this house, and to make up these walls?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 10, E'We asked their names also, to certify thee, that we might write the names of the men that were the chief of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 11, E'And thus they returned us answer, saying, We are the servants of the God of heaven and earth, and build the house that was builded these many years ago, which a great king of Israel builded and set up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 12, E'But after that our fathers had provoked the God of heaven unto wrath, he gave them into the hand of Nebuchadnezzar the king of Babylon, the Chaldean, who destroyed this house, and carried the people away into Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 13, E'But in the first year of Cyrus the king of Babylon the same king Cyrus made a decree to build this house of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 14, E'And the vessels also of gold and silver of the house of God, which Nebuchadnezzar took out of the temple that was in Jerusalem, and brought them into the temple of Babylon, those did Cyrus the king take out of the temple of Babylon, and they were delivered unto one, whose name was Sheshbazzar, whom he had made governor;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 15, E'And said unto him, Take these vessels, go, carry them into the temple that is in Jerusalem, and let the house of God be builded in his place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 16, E'Then came the same Sheshbazzar, and laid the foundation of the house of God which is in Jerusalem: and since that time even until now hath it been in building, and yet it is not finished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 5, 17, E'Now therefore, if it seem good to the king, let there be search made in the king’s treasure house, which is there at Babylon, whether it be so, that a decree was made of Cyrus the king to build this house of God at Jerusalem, and let the king send his pleasure to us concerning this matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 1, E'Then Darius the king made a decree, and search was made in the house of the rolls, where the treasures were laid up in Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 2, E'And there was found at Achmetha, in the palace that is in the province of the Medes, a roll, and therein was a record thus written:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 3, E'In the first year of Cyrus the king the same Cyrus the king made a decree concerning the house of God at Jerusalem, Let the house be builded, the place where they offered sacrifices, and let the foundations thereof be strongly laid; the height thereof threescore cubits, and the breadth thereof threescore cubits;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 4, E'With three rows of great stones, and a row of new timber: and let the expenses be given out of the king’s house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 5, E'And also let the golden and silver vessels of the house of God, which Nebuchadnezzar took forth out of the temple which is at Jerusalem, and brought unto Babylon, be restored, and brought again unto the temple which is at Jerusalem, every one to his place, and place them in the house of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 6, E'Now therefore, Tatnai, governor beyond the river, Shetharboznai, and your companions the Apharsachites, which are beyond the river, be ye far from thence:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 7, E'Let the work of this house of God alone; let the governor of the Jews and the elders of the Jews build this house of God in his place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 8, E'Moreover I make a decree what ye shall do to the elders of these Jews for the building of this house of God: that of the king’s goods, even of the tribute beyond the river, forthwith expenses be given unto these men, that they be not hindered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 9, E'And that which they have need of, both young bullocks, and rams, and lambs, for the burnt offerings of the God of heaven, wheat, salt, wine, and oil, according to the appointment of the priests which are at Jerusalem, let it be given them day by day without fail:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 10, E'That they may offer sacrifices of sweet savours unto the God of heaven, and pray for the life of the king, and of his sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 11, E'Also I have made a decree, that whosoever shall alter this word, let timber be pulled down from his house, and being set up, let him be hanged thereon; and let his house be made a dunghill for this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 12, E'And the God that hath caused his name to dwell there destroy all kings and people, that shall put to their hand to alter and to destroy this house of God which is at Jerusalem. I Darius have made a decree; let it be done with speed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 13, E'Then Tatnai, governor on this side the river, Shetharboznai, and their companions, according to that which Darius the king had sent, so they did speedily.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 14, E'And the elders of the Jews builded, and they prospered through the prophesying of Haggai the prophet and Zechariah the son of Iddo. And they builded, and finished it, according to the commandment of the God of Israel, and according to the commandment of Cyrus, and Darius, and Artaxerxes king of Persia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 15, E'And this house was finished on the third day of the month Adar, which was in the sixth year of the reign of Darius the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 16, E'And the children of Israel, the priests, and the Levites, and the rest of the children of the captivity, kept the dedication of this house of God with joy,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 17, E'And offered at the dedication of this house of God an hundred bullocks, two hundred rams, four hundred lambs; and for a sin offering for all Israel, twelve he goats, according to the number of the tribes of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 18, E'And they set the priests in their divisions, and the Levites in their courses, for the service of God, which is at Jerusalem; as it is written in the book of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 19, E'And the children of the captivity kept the passover upon the fourteenth day of the first month.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 20, E'For the priests and the Levites were purified together, all of them were pure, and killed the passover for all the children of the captivity, and for their brethren the priests, and for themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 21, E'And the children of Israel, which were come again out of captivity, and all such as had separated themselves unto them from the filthiness of the heathen of the land, to seek the LORD God of Israel, did eat,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 6, 22, E'And kept the feast of unleavened bread seven days with joy: for the LORD had made them joyful, and turned the heart of the king of Assyria unto them, to strengthen their hands in the work of the house of God, the God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 1, E'Now after these things, in the reign of Artaxerxes king of Persia, Ezra the son of Seraiah, the son of Azariah, the son of Hilkiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 2, E'The son of Shallum, the son of Zadok, the son of Ahitub,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 3, E'The son of Amariah, the son of Azariah, the son of Meraioth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 4, E'The son of Zerahiah, the son of Uzzi, the son of Bukki,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 5, E'The son of Abishua, the son of Phinehas, the son of Eleazar, the son of Aaron the chief priest:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 6, E'This Ezra went up from Babylon; and he was a ready scribe in the law of Moses, which the LORD God of Israel had given: and the king granted him all his request, according to the hand of the LORD his God upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 7, E'And there went up some of the children of Israel, and of the priests, and the Levites, and the singers, and the porters, and the Nethinims, unto Jerusalem, in the seventh year of Artaxerxes the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 8, E'And he came to Jerusalem in the fifth month, which was in the seventh year of the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 9, E'For upon the first day of the first month began he to go up from Babylon, and on the first day of the fifth month came he to Jerusalem, according to the good hand of his God upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 10, E'For Ezra had prepared his heart to seek the law of the LORD, and to do it, and to teach in Israel statutes and judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 11, E'Now this is the copy of the letter that the king Artaxerxes gave unto Ezra the priest, the scribe, even a scribe of the words of the commandments of the LORD, and of his statutes to Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 12, E'Artaxerxes, king of kings, unto Ezra the priest, a scribe of the law of the God of heaven, perfect peace, and at such a time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 13, E'I make a decree, that all they of the people of Israel, and of his priests and Levites, in my realm, which are minded of their own freewill to go up to Jerusalem, go with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 14, E'Forasmuch as thou art sent of the king, and of his seven counsellors, to enquire concerning Judah and Jerusalem, according to the law of thy God which is in thine hand;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 15, E'And to carry the silver and gold, which the king and his counsellors have freely offered unto the God of Israel, whose habitation is in Jerusalem,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 16, E'And all the silver and gold that thou canst find in all the province of Babylon, with the freewill offering of the people, and of the priests, offering willingly for the house of their God which is in Jerusalem:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 17, E'That thou mayest buy speedily with this money bullocks, rams, lambs, with their meat offerings and their drink offerings, and offer them upon the altar of the house of your God which is in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 18, E'And whatsoever shall seem good to thee, and to thy brethren, to do with the rest of the silver and the gold, that do after the will of your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 19, E'The vessels also that are given thee for the service of the house of thy God, those deliver thou before the God of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 20, E'And whatsoever more shall be needful for the house of thy God, which thou shalt have occasion to bestow, bestow it out of the king’s treasure house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 21, E'And I, even I Artaxerxes the king, do make a decree to all the treasurers which are beyond the river, that whatsoever Ezra the priest, the scribe of the law of the God of heaven, shall require of you, it be done speedily,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 22, E'Unto an hundred talents of silver, and to an hundred measures of wheat, and to an hundred baths of wine, and to an hundred baths of oil, and salt without prescribing how much.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 23, E'Whatsoever is commanded by the God of heaven, let it be diligently done for the house of the God of heaven: for why should there be wrath against the realm of the king and his sons?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 24, E'Also we certify you, that touching any of the priests and Levites, singers, porters, Nethinims, or ministers of this house of God, it shall not be lawful to impose toll, tribute, or custom, upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 25, E'And thou, Ezra, after the wisdom of thy God, that is in thine hand, set magistrates and judges, which may judge all the people that are beyond the river, all such as know the laws of thy God; and teach ye them that know them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 26, E'And whosoever will not do the law of thy God, and the law of the king, let judgment be executed speedily upon him, whether it be unto death, or to banishment, or to confiscation of goods, or to imprisonment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 27, E'Blessed be the LORD God of our fathers, which hath put such a thing as this in the king’s heart, to beautify the house of the LORD which is in Jerusalem:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 7, 28, E'And hath extended mercy unto me before the king, and his counsellors, and before all the king’s mighty princes. And I was strengthened as the hand of the LORD my God was upon me, and I gathered together out of Israel chief men to go up with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 1, E'These are now the chief of their fathers, and this is the genealogy of them that went up with me from Babylon, in the reign of Artaxerxes the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 2, E'Of the sons of Phinehas; Gershom: of the sons of Ithamar; Daniel: of the sons of David; Hattush.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 3, E'Of the sons of Shechaniah, of the sons of Pharosh; Zechariah: and with him were reckoned by genealogy of the males an hundred and fifty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 4, E'Of the sons of Pahathmoab; Elihoenai the son of Zerahiah, and with him two hundred males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 5, E'Of the sons of Shechaniah; the son of Jahaziel, and with him three hundred males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 6, E'Of the sons also of Adin; Ebed the son of Jonathan, and with him fifty males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 7, E'And of the sons of Elam; Jeshaiah the son of Athaliah, and with him seventy males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 8, E'And of the sons of Shephatiah; Zebadiah the son of Michael, and with him fourscore males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 9, E'Of the sons of Joab; Obadiah the son of Jehiel, and with him two hundred and eighteen males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 10, E'And of the sons of Shelomith; the son of Josiphiah, and with him an hundred and threescore males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 11, E'And of the sons of Bebai; Zechariah the son of Bebai, and with him twenty and eight males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 12, E'And of the sons of Azgad; Johanan the son of Hakkatan, and with him an hundred and ten males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 13, E'And of the last sons of Adonikam, whose names are these, Eliphelet, Jeiel, and Shemaiah, and with them threescore males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 14, E'Of the sons also of Bigvai; Uthai, and Zabbud, and with them seventy males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 15, E'And I gathered them together to the river that runneth to Ahava; and there abode we in tents three days: and I viewed the people, and the priests, and found there none of the sons of Levi.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Ezra') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 16, E'Then sent I for Eliezer, for Ariel, for Shemaiah, and for Elnathan, and for Jarib, and for Elnathan, and for Nathan, and for Zechariah, and for Meshullam, chief men; also for Joiarib, and for Elnathan, men of understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 17, E'And I sent them with commandment unto Iddo the chief at the place Casiphia, and I told them what they should say unto Iddo, and to his brethren the Nethinims, at the place Casiphia, that they should bring unto us ministers for the house of our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 18, E'And by the good hand of our God upon us they brought us a man of understanding, of the sons of Mahli, the son of Levi, the son of Israel; and Sherebiah, with his sons and his brethren, eighteen;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 19, E'And Hashabiah, and with him Jeshaiah of the sons of Merari, his brethren and their sons, twenty;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 20, E'Also of the Nethinims, whom David and the princes had appointed for the service of the Levites, two hundred and twenty Nethinims: all of them were expressed by name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 21, E'Then I proclaimed a fast there, at the river of Ahava, that we might afflict ourselves before our God, to seek of him a right way for us, and for our little ones, and for all our substance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 22, E'For I was ashamed to require of the king a band of soldiers and horsemen to help us against the enemy in the way: because we had spoken unto the king, saying, The hand of our God is upon all them for good that seek him; but his power and his wrath is against all them that forsake him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 23, E'So we fasted and besought our God for this: and he was intreated of us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 24, E'Then I separated twelve of the chief of the priests, Sherebiah, Hashabiah, and ten of their brethren with them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 25, E'And weighed unto them the silver, and the gold, and the vessels, even the offering of the house of our God, which the king, and his counsellors, and his lords, and all Israel there present, had offered:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 26, E'I even weighed unto their hand six hundred and fifty talents of silver, and silver vessels an hundred talents, and of gold an hundred talents;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 27, E'Also twenty basons of gold, of a thousand drams; and two vessels of fine copper, precious as gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 28, E'And I said unto them, Ye are holy unto the LORD; the vessels are holy also; and the silver and the gold are a freewill offering unto the LORD God of your fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 29, E'Watch ye, and keep them, until ye weigh them before the chief of the priests and the Levites, and chief of the fathers of Israel, at Jerusalem, in the chambers of the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 30, E'So took the priests and the Levites the weight of the silver, and the gold, and the vessels, to bring them to Jerusalem unto the house of our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 31, E'Then we departed from the river of Ahava on the twelfth day of the first month, to go unto Jerusalem: and the hand of our God was upon us, and he delivered us from the hand of the enemy, and of such as lay in wait by the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 32, E'And we came to Jerusalem, and abode there three days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 33, E'Now on the fourth day was the silver and the gold and the vessels weighed in the house of our God by the hand of Meremoth the son of Uriah the priest; and with him was Eleazar the son of Phinehas; and with them was Jozabad the son of Jeshua, and Noadiah the son of Binnui, Levites;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 34, E'By number and by weight of every one: and all the weight was written at that time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 35, E'Also the children of those that had been carried away, which were come out of the captivity, offered burnt offerings unto the God of Israel, twelve bullocks for all Israel, ninety and six rams, seventy and seven lambs, twelve he goats for a sin offering: all this was a burnt offering unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 8, 36, E'And they delivered the king’s commissions unto the king’s lieutenants, and to the governors on this side the river: and they furthered the people, and the house of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 1, E'Now when these things were done, the princes came to me, saying, The people of Israel, and the priests, and the Levites, have not separated themselves from the people of the lands, doing according to their abominations, even of the Canaanites, the Hittites, the Perizzites, the Jebusites, the Ammonites, the Moabites, the Egyptians, and the Amorites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 2, E'For they have taken of their daughters for themselves, and for their sons: so that the holy seed have mingled themselves with the people of those lands: yea, the hand of the princes and rulers hath been chief in this trespass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 3, E'And when I heard this thing, I rent my garment and my mantle, and plucked off the hair of my head and of my beard, and sat down astonied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 4, E'Then were assembled unto me every one that trembled at the words of the God of Israel, because of the transgression of those that had been carried away; and I sat astonied until the evening sacrifice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 5, E'And at the evening sacrifice I arose up from my heaviness; and having rent my garment and my mantle, I fell upon my knees, and spread out my hands unto the LORD my God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 6, E'And said, O my God, I am ashamed and blush to lift up my face to thee, my God: for our iniquities are increased over our head, and our trespass is grown up unto the heavens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 7, E'Since the days of our fathers have we been in a great trespass unto this day; and for our iniquities have we, our kings, and our priests, been delivered into the hand of the kings of the lands, to the sword, to captivity, and to a spoil, and to confusion of face, as it is this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 8, E'And now for a little space grace hath been shewed from the LORD our God, to leave us a remnant to escape, and to give us a nail in his holy place, that our God may lighten our eyes, and give us a little reviving in our bondage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 9, E'For we were bondmen; yet our God hath not forsaken us in our bondage, but hath extended mercy unto us in the sight of the kings of Persia, to give us a reviving, to set up the house of our God, and to repair the desolations thereof, and to give us a wall in Judah and in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 10, E'And now, O our God, what shall we say after this? for we have forsaken thy commandments,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 11, E'Which thou hast commanded by thy servants the prophets, saying, The land, unto which ye go to possess it, is an unclean land with the filthiness of the people of the lands, with their abominations, which have filled it from one end to another with their uncleanness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 12, E'Now therefore give not your daughters unto their sons, neither take their daughters unto your sons, nor seek their peace or their wealth for ever: that ye may be strong, and eat the good of the land, and leave it for an inheritance to your children for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 13, E'And after all that is come upon us for our evil deeds, and for our great trespass, seeing that thou our God hast punished us less than our iniquities deserve, and hast given us such deliverance as this;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 14, E'Should we again break thy commandments, and join in affinity with the people of these abominations? wouldest not thou be angry with us till thou hadst consumed us, so that there should be no remnant nor escaping?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 9, 15, E'O LORD God of Israel, thou art righteous: for we remain yet escaped, as it is this day: behold, we are before thee in our trespasses: for we cannot stand before thee because of this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 1, E'Now when Ezra had prayed, and when he had confessed, weeping and casting himself down before the house of God, there assembled unto him out of Israel a very great congregation of men and women and children: for the people wept very sore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 2, E'And Shechaniah the son of Jehiel, one of the sons of Elam, answered and said unto Ezra, We have trespassed against our God, and have taken strange wives of the people of the land: yet now there is hope in Israel concerning this thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 3, E'Now therefore let us make a covenant with our God to put away all the wives, and such as are born of them, according to the counsel of my lord, and of those that tremble at the commandment of our God; and let it be done according to the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 4, E'Arise; for this matter belongeth unto thee: we also will be with thee: be of good courage, and do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 5, E'Then arose Ezra, and made the chief priests, the Levites, and all Israel, to swear that they should do according to this word. And they sware.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 6, E'Then Ezra rose up from before the house of God, and went into the chamber of Johanan the son of Eliashib: and when he came thither, he did eat no bread, nor drink water: for he mourned because of the transgression of them that had been carried away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 7, E'And they made proclamation throughout Judah and Jerusalem unto all the children of the captivity, that they should gather themselves together unto Jerusalem;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 8, E'And that whosoever would not come within three days, according to the counsel of the princes and the elders, all his substance should be forfeited, and himself separated from the congregation of those that had been carried away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 9, E'Then all the men of Judah and Benjamin gathered themselves together unto Jerusalem within three days. It was the ninth month, on the twentieth day of the month; and all the people sat in the street of the house of God, trembling because of this matter, and for the great rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 10, E'And Ezra the priest stood up, and said unto them, Ye have transgressed, and have taken strange wives, to increase the trespass of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 11, E'Now therefore make confession unto the LORD God of your fathers, and do his pleasure: and separate yourselves from the people of the land, and from the strange wives.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 12, E'Then all the congregation answered and said with a loud voice, As thou hast said, so must we do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 13, E'But the people are many, and it is a time of much rain, and we are not able to stand without, neither is this a work of one day or two: for we are many that have transgressed in this thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 14, E'Let now our rulers of all the congregation stand, and let all them which have taken strange wives in our cities come at appointed times, and with them the elders of every city, and the judges thereof, until the fierce wrath of our God for this matter be turned from us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 15, E'Only Jonathan the son of Asahel and Jahaziah the son of Tikvah were employed about this matter: and Meshullam and Shabbethai the Levite helped them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 16, E'And the children of the captivity did so. And Ezra the priest, with certain chief of the fathers, after the house of their fathers, and all of them by their names, were separated, and sat down in the first day of the tenth month to examine the matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 17, E'And they made an end with all the men that had taken strange wives by the first day of the first month.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 18, E'And among the sons of the priests there were found that had taken strange wives: namely, of the sons of Jeshua the son of Jozadak, and his brethren; Maaseiah, and Eliezer, and Jarib, and Gedaliah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 19, E'And they gave their hands that they would put away their wives; and being guilty, they offered a ram of the flock for their trespass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 20, E'And of the sons of Immer; Hanani, and Zebadiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 21, E'And of the sons of Harim; Maaseiah, and Elijah, and Shemaiah, and Jehiel, and Uzziah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 22, E'And of the sons of Pashur; Elioenai, Maaseiah, Ishmael, Nethaneel, Jozabad, and Elasah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 23, E'Also of the Levites; Jozabad, and Shimei, and Kelaiah, (the same is Kelita,) Pethahiah, Judah, and Eliezer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 24, E'Of the singers also; Eliashib: and of the porters; Shallum, and Telem, and Uri.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 25, E'Moreover of Israel: of the sons of Parosh; Ramiah, and Jeziah, and Malchiah, and Miamin, and Eleazar, and Malchijah, and Benaiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 26, E'And of the sons of Elam; Mattaniah, Zechariah, and Jehiel, and Abdi, and Jeremoth, and Eliah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 27, E'And of the sons of Zattu; Elioenai, Eliashib, Mattaniah, and Jeremoth, and Zabad, and Aziza.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 28, E'Of the sons also of Bebai; Jehohanan, Hananiah, Zabbai, and Athlai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 29, E'And of the sons of Bani; Meshullam, Malluch, and Adaiah, Jashub, and Sheal, and Ramoth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 30, E'And of the sons of Pahathmoab; Adna, and Chelal, Benaiah, Maaseiah, Mattaniah, Bezaleel, and Binnui, and Manasseh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 31, E'And of the sons of Harim; Eliezer, Ishijah, Malchiah, Shemaiah, Shimeon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 32, E'Benjamin, Malluch, and Shemariah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 33, E'Of the sons of Hashum; Mattenai, Mattathah, Zabad, Eliphelet, Jeremai, Manasseh, and Shimei.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 34, E'Of the sons of Bani; Maadai, Amram, and Uel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 35, E'Benaiah, Bedeiah, Chelluh,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 36, E'Vaniah, Meremoth, Eliashib,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 37, E'Mattaniah, Mattenai, and Jaasau,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 38, E'And Bani, and Binnui, Shimei,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 39, E'And Shelemiah, and Nathan, and Adaiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 40, E'Machnadebai, Shashai, Sharai,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 41, E'Azareel, and Shelemiah, Shemariah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 42, E'Shallum, Amariah, and Joseph.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 43, E'Of the sons of Nebo; Jeiel, Mattithiah, Zabad, Zebina, Jadau, and Joel, Benaiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '231c7c4e-b1ef-40f2-8027-ba1d9a0143a2', 10, 44, E'All these had taken strange wives: and some of them had wives by whom they had children.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Ezra') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 1, 1, E'The words of Nehemiah the son of Hachaliah. And it came to pass in the month Chisleu, in the twentieth year, as I was in Shushan the palace,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 1, 2, E'That Hanani, one of my brethren, came, he and certain men of Judah; and I asked them concerning the Jews that had escaped, which were left of the captivity, and concerning Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 1, 3, E'And they said unto me, The remnant that are left of the captivity there in the province are in great affliction and reproach: the wall of Jerusalem also is broken down, and the gates thereof are burned with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 1, 4, E'And it came to pass, when I heard these words, that I sat down and wept, and mourned certain days, and fasted, and prayed before the God of heaven,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 1, 5, E'And said, I beseech thee, O LORD God of heaven, the great and terrible God, that keepeth covenant and mercy for them that love him and observe his commandments:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 1, 6, E'Let thine ear now be attentive, and thine eyes open, that thou mayest hear the prayer of thy servant, which I pray before thee now, day and night, for the children of Israel thy servants, and confess the sins of the children of Israel, which we have sinned against thee: both I and my father’s house have sinned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 1, 7, E'We have dealt very corruptly against thee, and have not kept the commandments, nor the statutes, nor the judgments, which thou commandedst thy servant Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 1, 8, E'Remember, I beseech thee, the word that thou commandedst thy servant Moses, saying, If ye transgress, I will scatter you abroad among the nations:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 1, 9, E'But if ye turn unto me, and keep my commandments, and do them; though there were of you cast out unto the uttermost part of the heaven, yet will I gather them from thence, and will bring them unto the place that I have chosen to set my name there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 1, 10, E'Now these are thy servants and thy people, whom thou hast redeemed by thy great power, and by thy strong hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 1, 11, E'O LORD, I beseech thee, let now thine ear be attentive to the prayer of thy servant, and to the prayer of thy servants, who desire to fear thy name: and prosper, I pray thee, thy servant this day, and grant him mercy in the sight of this man. For I was the king’s cupbearer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 1, E'And it came to pass in the month Nisan, in the twentieth year of Artaxerxes the king, that wine was before him: and I took up the wine, and gave it unto the king. Now I had not been beforetime sad in his presence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 2, E'Wherefore the king said unto me, Why is thy countenance sad, seeing thou art not sick? this is nothing else but sorrow of heart. Then I was very sore afraid,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 3, E'And said unto the king, Let the king live for ever: why should not my countenance be sad, when the city, the place of my fathers’ sepulchres, lieth waste, and the gates thereof are consumed with fire?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 4, E'Then the king said unto me, For what dost thou make request? So I prayed to the God of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 5, E'And I said unto the king, If it please the king, and if thy servant have found favour in thy sight, that thou wouldest send me unto Judah, unto the city of my fathers’ sepulchres, that I may build it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 6, E'And the king said unto me, (the queen also sitting by him,) For how long shall thy journey be? and when wilt thou return? So it pleased the king to send me; and I set him a time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 7, E'Moreover I said unto the king, If it please the king, let letters be given me to the governors beyond the river, that they may convey me over till I come into Judah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 8, E'And a letter unto Asaph the keeper of the king’s forest, that he may give me timber to make beams for the gates of the palace which appertained to the house, and for the wall of the city, and for the house that I shall enter into. And the king granted me, according to the good hand of my God upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 9, E'Then I came to the governors beyond the river, and gave them the king’s letters. Now the king had sent captains of the army and horsemen with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 10, E'When Sanballat the Horonite, and Tobiah the servant, the Ammonite, heard of it, it grieved them exceedingly that there was come a man to seek the welfare of the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 11, E'So I came to Jerusalem, and was there three days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 12, E'And I arose in the night, I and some few men with me; neither told I any man what my God had put in my heart to do at Jerusalem: neither was there any beast with me, save the beast that I rode upon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 13, E'And I went out by night by the gate of the valley, even before the dragon well, and to the dung port, and viewed the walls of Jerusalem, which were broken down, and the gates thereof were consumed with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 14, E'Then I went on to the gate of the fountain, and to the king’s pool: but there was no place for the beast that was under me to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 15, E'Then went I up in the night by the brook, and viewed the wall, and turned back, and entered by the gate of the valley, and so returned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 16, E'And the rulers knew not whither I went, or what I did; neither had I as yet told it to the Jews, nor to the priests, nor to the nobles, nor to the rulers, nor to the rest that did the work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 17, E'Then said I unto them, Ye see the distress that we are in, how Jerusalem lieth waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem, that we be no more a reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 18, E'Then I told them of the hand of my God which was good upon me; as also the king’s words that he had spoken unto me. And they said, Let us rise up and build. So they strengthened their hands for this good work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 19, E'But when Sanballat the Horonite, and Tobiah the servant, the Ammonite, and Geshem the Arabian, heard it, they laughed us to scorn, and despised us, and said, What is this thing that ye do? will ye rebel against the king?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 2, 20, E'Then answered I them, and said unto them, The God of heaven, he will prosper us; therefore we his servants will arise and build: but ye have no portion, nor right, nor memorial, in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 1, E'Then Eliashib the high priest rose up with his brethren the priests, and they builded the sheep gate; they sanctified it, and set up the doors of it; even unto the tower of Meah they sanctified it, unto the tower of Hananeel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 2, E'And next unto him builded the men of Jericho. And next to them builded Zaccur the son of Imri.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 3, E'But the fish gate did the sons of Hassenaah build, who also laid the beams thereof, and set up the doors thereof, the locks thereof, and the bars thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 4, E'And next unto them repaired Meremoth the son of Urijah, the son of Koz. And next unto them repaired Meshullam the son of Berechiah, the son of Meshezabeel. And next unto them repaired Zadok the son of Baana.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 5, E'And next unto them the Tekoites repaired; but their nobles put not their necks to the work of their LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 6, E'Moreover the old gate repaired Jehoiada the son of Paseah, and Meshullam the son of Besodeiah; they laid the beams thereof, and set up the doors thereof, and the locks thereof, and the bars thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 7, E'And next unto them repaired Melatiah the Gibeonite, and Jadon the Meronothite, the men of Gibeon, and of Mizpah, unto the throne of the governor on this side the river.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 8, E'Next unto him repaired Uzziel the son of Harhaiah, of the goldsmiths. Next unto him also repaired Hananiah the son of one of the apothecaries, and they fortified Jerusalem unto the broad wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 9, E'And next unto them repaired Rephaiah the son of Hur, the ruler of the half part of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 10, E'And next unto them repaired Jedaiah the son of Harumaph, even over against his house. And next unto him repaired Hattush the son of Hashabniah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 11, E'Malchijah the son of Harim, and Hashub the son of Pahathmoab, repaired the other piece, and the tower of the furnaces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 12, E'And next unto him repaired Shallum the son of Halohesh, the ruler of the half part of Jerusalem, he and his daughters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 13, E'The valley gate repaired Hanun, and the inhabitants of Zanoah; they built it, and set up the doors thereof, the locks thereof, and the bars thereof, and a thousand cubits on the wall unto the dung gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 14, E'But the dung gate repaired Malchiah the son of Rechab, the ruler of part of Bethhaccerem; he built it, and set up the doors thereof, the locks thereof, and the bars thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 15, E'But the gate of the fountain repaired Shallun the son of Colhozeh, the ruler of part of Mizpah; he built it, and covered it, and set up the doors thereof, the locks thereof, and the bars thereof, and the wall of the pool of Siloah by the king’s garden, and unto the stairs that go down from the city of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 16, E'After him repaired Nehemiah the son of Azbuk, the ruler of the half part of Bethzur, unto the place over against the sepulchres of David, and to the pool that was made, and unto the house of the mighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 17, E'After him repaired the Levites, Rehum the son of Bani. Next unto him repaired Hashabiah, the ruler of the half part of Keilah, in his part.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 18, E'After him repaired their brethren, Bavai the son of Henadad, the ruler of the half part of Keilah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 19, E'And next to him repaired Ezer the son of Jeshua, the ruler of Mizpah, another piece over against the going up to the armoury at the turning of the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 20, E'After him Baruch the son of Zabbai earnestly repaired the other piece, from the turning of the wall unto the door of the house of Eliashib the high priest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 21, E'After him repaired Meremoth the son of Urijah the son of Koz another piece, from the door of the house of Eliashib even to the end of the house of Eliashib.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 22, E'And after him repaired the priests, the men of the plain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 23, E'After him repaired Benjamin and Hashub over against their house. After him repaired Azariah the son of Maaseiah the son of Ananiah by his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 24, E'After him repaired Binnui the son of Henadad another piece, from the house of Azariah unto the turning of the wall, even unto the corner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 25, E'Palal the son of Uzai, over against the turning of the wall, and the tower which lieth out from the king’s high house, that was by the court of the prison. After him Pedaiah the son of Parosh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 26, E'Moreover the Nethinims dwelt in Ophel, unto the place over against the water gate toward the east, and the tower that lieth out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 27, E'After them the Tekoites repaired another piece, over against the great tower that lieth out, even unto the wall of Ophel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 28, E'From above the horse gate repaired the priests, every one over against his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 29, E'After them repaired Zadok the son of Immer over against his house. After him repaired also Shemaiah the son of Shechaniah, the keeper of the east gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 30, E'After him repaired Hananiah the son of Shelemiah, and Hanun the sixth son of Zalaph, another piece. After him repaired Meshullam the son of Berechiah over against his chamber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 31, E'After him repaired Malchiah the goldsmith’s son unto the place of the Nethinims, and of the merchants, over against the gate Miphkad, and to the going up of the corner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 3, 32, E'And between the going up of the corner unto the sheep gate repaired the goldsmiths and the merchants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 1, E'But it came to pass, that when Sanballat heard that we builded the wall, he was wroth, and took great indignation, and mocked the Jews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 2, E'And he spake before his brethren and the army of Samaria, and said, What do these feeble Jews? will they fortify themselves? will they sacrifice? will they make an end in a day? will they revive the stones out of the heaps of the rubbish which are burned?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 3, E'Now Tobiah the Ammonite was by him, and he said, Even that which they build, if a fox go up, he shall even break down their stone wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 4, E'Hear, O our God; for we are despised: and turn their reproach upon their own head, and give them for a prey in the land of captivity:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 5, E'And cover not their iniquity, and let not their sin be blotted out from before thee: for they have provoked thee to anger before the builders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 6, E'So built we the wall; and all the wall was joined together unto the half thereof: for the people had a mind to work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 7, E'But it came to pass, that when Sanballat, and Tobiah, and the Arabians, and the Ammonites, and the Ashdodites, heard that the walls of Jerusalem were made up, and that the breaches began to be stopped, then they were very wroth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 8, E'And conspired all of them together to come and to fight against Jerusalem, and to hinder it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 9, E'Nevertheless we made our prayer unto our God, and set a watch against them day and night, because of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 10, E'And Judah said, The strength of the bearers of burdens is decayed, and there is much rubbish; so that we are not able to build the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 11, E'And our adversaries said, They shall not know, neither see, till we come in the midst among them, and slay them, and cause the work to cease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 12, E'And it came to pass, that when the Jews which dwelt by them came, they said unto us ten times, From all places whence ye shall return unto us they will be upon you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 13, E'Therefore set I in the lower places behind the wall, and on the higher places, I even set the people after their families with their swords, their spears, and their bows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 14, E'And I looked, and rose up, and said unto the nobles, and to the rulers, and to the rest of the people, Be not ye afraid of them: remember the LORD, which is great and terrible, and fight for your brethren, your sons, and your daughters, your wives, and your houses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 15, E'And it came to pass, when our enemies heard that it was known unto us, and God had brought their counsel to nought, that we returned all of us to the wall, every one unto his work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 16, E'And it came to pass from that time forth, that the half of my servants wrought in the work, and the other half of them held both the spears, the shields, and the bows, and the habergeons; and the rulers were behind all the house of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 17, E'They which builded on the wall, and they that bare burdens, with those that laded, every one with one of his hands wrought in the work, and with the other hand held a weapon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 18, E'For the builders, every one had his sword girded by his side, and so builded. And he that sounded the trumpet was by me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 19, E'And I said unto the nobles, and to the rulers, and to the rest of the people, The work is great and large, and we are separated upon the wall, one far from another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 20, E'In what place therefore ye hear the sound of the trumpet, resort ye thither unto us: our God shall fight for us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 21, E'So we laboured in the work: and half of them held the spears from the rising of the morning till the stars appeared.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 22, E'Likewise at the same time said I unto the people, Let every one with his servant lodge within Jerusalem, that in the night they may be a guard to us, and labour on the day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 4, 23, E'So neither I, nor my brethren, nor my servants, nor the men of the guard which followed me, none of us put off our clothes, saving that every one put them off for washing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 1, E'And there was a great cry of the people and of their wives against their brethren the Jews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 2, E'For there were that said, We, our sons, and our daughters, are many: therefore we take up corn for them, that we may eat, and live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 3, E'Some also there were that said, We have mortgaged our lands, vineyards, and houses, that we might buy corn, because of the dearth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 4, E'There were also that said, We have borrowed money for the king’s tribute, and that upon our lands and vineyards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 5, E'Yet now our flesh is as the flesh of our brethren, our children as their children: and, lo, we bring into bondage our sons and our daughters to be servants, and some of our daughters are brought unto bondage already: neither is it in our power to redeem them; for other men have our lands and vineyards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 6, E'And I was very angry when I heard their cry and these words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 7, E'Then I consulted with myself, and I rebuked the nobles, and the rulers, and said unto them, Ye exact usury, every one of his brother. And I set a great assembly against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 8, E'And I said unto them, We after our ability have redeemed our brethren the Jews, which were sold unto the heathen; and will ye even sell your brethren? or shall they be sold unto us? Then held they their peace, and found nothing to answer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 9, E'Also I said, It is not good that ye do: ought ye not to walk in the fear of our God because of the reproach of the heathen our enemies?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 10, E'I likewise, and my brethren, and my servants, might exact of them money and corn: I pray you, let us leave off this usury.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 11, E'Restore, I pray you, to them, even this day, their lands, their vineyards, their oliveyards, and their houses, also the hundredth part of the money, and of the corn, the wine, and the oil, that ye exact of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 12, E'Then said they, We will restore them, and will require nothing of them; so will we do as thou sayest. Then I called the priests, and took an oath of them, that they should do according to this promise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 13, E'Also I shook my lap, and said, So God shake out every man from his house, and from his labour, that performeth not this promise, even thus be he shaken out, and emptied. And all the congregation said, Amen, and praised the LORD. And the people did according to this promise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 14, E'Moreover from the time that I was appointed to be their governor in the land of Judah, from the twentieth year even unto the two and thirtieth year of Artaxerxes the king, that is, twelve years, I and my brethren have not eaten the bread of the governor.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Nehemiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 15, E'But the former governors that had been before me were chargeable unto the people, and had taken of them bread and wine, beside forty shekels of silver; yea, even their servants bare rule over the people: but so did not I, because of the fear of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 16, E'Yea, also I continued in the work of this wall, neither bought we any land: and all my servants were gathered thither unto the work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 17, E'Moreover there were at my table an hundred and fifty of the Jews and rulers, beside those that came unto us from among the heathen that are about us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 18, E'Now that which was prepared for me daily was one ox and six choice sheep; also fowls were prepared for me, and once in ten days store of all sorts of wine: yet for all this required not I the bread of the governor, because the bondage was heavy upon this people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 5, 19, E'Think upon me, my God, for good, according to all that I have done for this people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 1, E'Now it came to pass, when Sanballat, and Tobiah, and Geshem the Arabian, and the rest of our enemies, heard that I had builded the wall, and that there was no breach left therein; (though at that time I had not set up the doors upon the gates;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 2, E'That Sanballat and Geshem sent unto me, saying, Come, let us meet together in some one of the villages in the plain of Ono. But they thought to do me mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 3, E'And I sent messengers unto them, saying, I am doing a great work, so that I cannot come down: why should the work cease, whilst I leave it, and come down to you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 4, E'Yet they sent unto me four times after this sort; and I answered them after the same manner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 5, E'Then sent Sanballat his servant unto me in like manner the fifth time with an open letter in his hand;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 6, E'Wherein was written, It is reported among the heathen, and Gashmu saith it, that thou and the Jews think to rebel: for which cause thou buildest the wall, that thou mayest be their king, according to these words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 7, E'And thou hast also appointed prophets to preach of thee at Jerusalem, saying, There is a king in Judah: and now shall it be reported to the king according to these words. Come now therefore, and let us take counsel together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 8, E'Then I sent unto him, saying, There are no such things done as thou sayest, but thou feignest them out of thine own heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 9, E'For they all made us afraid, saying, Their hands shall be weakened from the work, that it be not done. Now therefore, O God, strengthen my hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 10, E'Afterward I came unto the house of Shemaiah the son of Delaiah the son of Mehetabeel, who was shut up; and he said, Let us meet together in the house of God, within the temple, and let us shut the doors of the temple: for they will come to slay thee; yea, in the night will they come to slay thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 11, E'And I said, Should such a man as I flee? and who is there, that, being as I am, would go into the temple to save his life? I will not go in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 12, E'And, lo, I perceived that God had not sent him; but that he pronounced this prophecy against me: for Tobiah and Sanballat had hired him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 13, E'Therefore was he hired, that I should be afraid, and do so, and sin, and that they might have matter for an evil report, that they might reproach me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 14, E'My God, think thou upon Tobiah and Sanballat according to these their works, and on the prophetess Noadiah, and the rest of the prophets, that would have put me in fear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 15, E'So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 16, E'And it came to pass, that when all our enemies heard thereof, and all the heathen that were about us saw these things, they were much cast down in their own eyes: for they perceived that this work was wrought of our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 17, E'Moreover in those days the nobles of Judah sent many letters unto Tobiah, and the letters of Tobiah came unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 18, E'For there were many in Judah sworn unto him, because he was the son in law of Shechaniah the son of Arah; and his son Johanan had taken the daughter of Meshullam the son of Berechiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 6, 19, E'Also they reported his good deeds before me, and uttered my words to him. And Tobiah sent letters to put me in fear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 1, E'Now it came to pass, when the wall was built, and I had set up the doors, and the porters and the singers and the Levites were appointed,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 2, E'That I gave my brother Hanani, and Hananiah the ruler of the palace, charge over Jerusalem: for he was a faithful man, and feared God above many.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 3, E'And I said unto them, Let not the gates of Jerusalem be opened until the sun be hot; and while they stand by, let them shut the doors, and bar them: and appoint watches of the inhabitants of Jerusalem, every one in his watch, and every one to be over against his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 4, E'Now the city was large and great: but the people were few therein, and the houses were not builded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 5, E'And my God put into mine heart to gather together the nobles, and the rulers, and the people, that they might be reckoned by genealogy. And I found a register of the genealogy of them which came up at the first, and found written therein,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 6, E'These are the children of the province, that went up out of the captivity, of those that had been carried away, whom Nebuchadnezzar the king of Babylon had carried away, and came again to Jerusalem and to Judah, every one unto his city;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 7, E'Who came with Zerubbabel, Jeshua, Nehemiah, Azariah, Raamiah, Nahamani, Mordecai, Bilshan, Mispereth, Bigvai, Nehum, Baanah. The number, I say, of the men of the people of Israel was this;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 8, E'The children of Parosh, two thousand an hundred seventy and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 9, E'The children of Shephatiah, three hundred seventy and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 10, E'The children of Arah, six hundred fifty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 11, E'The children of Pahathmoab, of the children of Jeshua and Joab, two thousand and eight hundred and eighteen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 12, E'The children of Elam, a thousand two hundred fifty and four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 13, E'The children of Zattu, eight hundred forty and five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 14, E'The children of Zaccai, seven hundred and threescore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 15, E'The children of Binnui, six hundred forty and eight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 16, E'The children of Bebai, six hundred twenty and eight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 17, E'The children of Azgad, two thousand three hundred twenty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 18, E'The children of Adonikam, six hundred threescore and seven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 19, E'The children of Bigvai, two thousand threescore and seven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 20, E'The children of Adin, six hundred fifty and five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 21, E'The children of Ater of Hezekiah, ninety and eight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 22, E'The children of Hashum, three hundred twenty and eight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 23, E'The children of Bezai, three hundred twenty and four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 24, E'The children of Hariph, an hundred and twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 25, E'The children of Gibeon, ninety and five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 26, E'The men of Bethlehem and Netophah, an hundred fourscore and eight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 27, E'The men of Anathoth, an hundred twenty and eight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 28, E'The men of Bethazmaveth, forty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 29, E'The men of Kirjathjearim, Chephirah, and Beeroth, seven hundred forty and three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 30, E'The men of Ramah and Gaba, six hundred twenty and one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 31, E'The men of Michmas, an hundred and twenty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 32, E'The men of Bethel and Ai, an hundred twenty and three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 33, E'The men of the other Nebo, fifty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 34, E'The children of the other Elam, a thousand two hundred fifty and four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 35, E'The children of Harim, three hundred and twenty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 36, E'The children of Jericho, three hundred forty and five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 37, E'The children of Lod, Hadid, and Ono, seven hundred twenty and one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 38, E'The children of Senaah, three thousand nine hundred and thirty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 39, E'The priests: the children of Jedaiah, of the house of Jeshua, nine hundred seventy and three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 40, E'The children of Immer, a thousand fifty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 41, E'The children of Pashur, a thousand two hundred forty and seven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 42, E'The children of Harim, a thousand and seventeen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 43, E'The Levites: the children of Jeshua, of Kadmiel, and of the children of Hodevah, seventy and four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 44, E'The singers: the children of Asaph, an hundred forty and eight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 45, E'The porters: the children of Shallum, the children of Ater, the children of Talmon, the children of Akkub, the children of Hatita, the children of Shobai, an hundred thirty and eight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 46, E'The Nethinims: the children of Ziha, the children of Hashupha, the children of Tabbaoth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 47, E'The children of Keros, the children of Sia, the children of Padon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 48, E'The children of Lebana, the children of Hagaba, the children of Shalmai,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 49, E'The children of Hanan, the children of Giddel, the children of Gahar,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 50, E'The children of Reaiah, the children of Rezin, the children of Nekoda,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 51, E'The children of Gazzam, the children of Uzza, the children of Phaseah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 52, E'The children of Besai, the children of Meunim, the children of Nephishesim,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 53, E'The children of Bakbuk, the children of Hakupha, the children of Harhur,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 54, E'The children of Bazlith, the children of Mehida, the children of Harsha,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 55, E'The children of Barkos, the children of Sisera, the children of Tamah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 56, E'The children of Neziah, the children of Hatipha.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 57, E'The children of Solomon’s servants: the children of Sotai, the children of Sophereth, the children of Perida,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 58, E'The children of Jaala, the children of Darkon, the children of Giddel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 59, E'The children of Shephatiah, the children of Hattil, the children of Pochereth of Zebaim, the children of Amon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 60, E'All the Nethinims, and the children of Solomon’s servants, were three hundred ninety and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 61, E'And these were they which went up also from Telmelah, Telharesha, Cherub, Addon, and Immer: but they could not shew their father’s house, nor their seed, whether they were of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 62, E'The children of Delaiah, the children of Tobiah, the children of Nekoda, six hundred forty and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 63, E'And of the priests: the children of Habaiah, the children of Koz, the children of Barzillai, which took one of the daughters of Barzillai the Gileadite to wife, and was called after their name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 64, E'These sought their register among those that were reckoned by genealogy, but it was not found: therefore were they, as polluted, put from the priesthood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 65, E'And the Tirshatha said unto them, that they should not eat of the most holy things, till there stood up a priest with Urim and Thummim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 66, E'The whole congregation together was forty and two thousand three hundred and threescore,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 67, E'Beside their manservants and their maidservants, of whom there were seven thousand three hundred thirty and seven: and they had two hundred forty and five singing men and singing women.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 68, E'Their horses, seven hundred thirty and six: their mules, two hundred forty and five:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 69, E'Their camels, four hundred thirty and five: six thousand seven hundred and twenty asses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 70, E'And some of the chief of the fathers gave unto the work. The Tirshatha gave to the treasure a thousand drams of gold, fifty basons, five hundred and thirty priests’ garments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 71, E'And some of the chief of the fathers gave to the treasure of the work twenty thousand drams of gold, and two thousand and two hundred pound of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 72, E'And that which the rest of the people gave was twenty thousand drams of gold, and two thousand pound of silver, and threescore and seven priests’ garments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 7, 73, E'So the priests, and the Levites, and the porters, and the singers, and some of the people, and the Nethinims, and all Israel, dwelt in their cities; and when the seventh month came, the children of Israel were in their cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 1, E'And all the people gathered themselves together as one man into the street that was before the water gate; and they spake unto Ezra the scribe to bring the book of the law of Moses, which the LORD had commanded to Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 2, E'And Ezra the priest brought the law before the congregation both of men and women, and all that could hear with understanding, upon the first day of the seventh month.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 3, E'And he read therein before the street that was before the water gate from the morning until midday, before the men and the women, and those that could understand; and the ears of all the people were attentive unto the book of the law.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Nehemiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 4, E'And Ezra the scribe stood upon a pulpit of wood, which they had made for the purpose; and beside him stood Mattithiah, and Shema, and Anaiah, and Urijah, and Hilkiah, and Maaseiah, on his right hand; and on his left hand, Pedaiah, and Mishael, and Malchiah, and Hashum, and Hashbadana, Zechariah, and Meshullam.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 5, E'And Ezra opened the book in the sight of all the people; (for he was above all the people;) and when he opened it, all the people stood up:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 6, E'And Ezra blessed the LORD, the great God. And all the people answered, Amen, Amen, with lifting up their hands: and they bowed their heads, and worshipped the LORD with their faces to the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 7, E'Also Jeshua, and Bani, and Sherebiah, Jamin, Akkub, Shabbethai, Hodijah, Maaseiah, Kelita, Azariah, Jozabad, Hanan, Pelaiah, and the Levites, caused the people to understand the law: and the people stood in their place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 8, E'So they read in the book in the law of God distinctly, and gave the sense, and caused them to understand the reading.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 9, E'And Nehemiah, which is the Tirshatha, and Ezra the priest the scribe, and the Levites that taught the people, said unto all the people, This day is holy unto the LORD your God; mourn not, nor weep. For all the people wept, when they heard the words of the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 10, E'Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our LORD: neither be ye sorry; for the joy of the LORD is your strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 11, E'So the Levites stilled all the people, saying, Hold your peace, for the day is holy; neither be ye grieved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 12, E'And all the people went their way to eat, and to drink, and to send portions, and to make great mirth, because they had understood the words that were declared unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 13, E'And on the second day were gathered together the chief of the fathers of all the people, the priests, and the Levites, unto Ezra the scribe, even to understand the words of the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 14, E'And they found written in the law which the LORD had commanded by Moses, that the children of Israel should dwell in booths in the feast of the seventh month:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 15, E'And that they should publish and proclaim in all their cities, and in Jerusalem, saying, Go forth unto the mount, and fetch olive branches, and pine branches, and myrtle branches, and palm branches, and branches of thick trees, to make booths, as it is written.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 16, E'So the people went forth, and brought them, and made themselves booths, every one upon the roof of his house, and in their courts, and in the courts of the house of God, and in the street of the water gate, and in the street of the gate of Ephraim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 17, E'And all the congregation of them that were come again out of the captivity made booths, and sat under the booths: for since the days of Jeshua the son of Nun unto that day had not the children of Israel done so. And there was very great gladness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 8, 18, E'Also day by day, from the first day unto the last day, he read in the book of the law of God. And they kept the feast seven days; and on the eighth day was a solemn assembly, according unto the manner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 1, E'Now in the twenty and fourth day of this month the children of Israel were assembled with fasting, and with sackclothes, and earth upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 2, E'And the seed of Israel separated themselves from all strangers, and stood and confessed their sins, and the iniquities of their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 3, E'And they stood up in their place, and read in the book of the law of the LORD their God one fourth part of the day; and another fourth part they confessed, and worshipped the LORD their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 4, E'Then stood up upon the stairs, of the Levites, Jeshua, and Bani, Kadmiel, Shebaniah, Bunni, Sherebiah, Bani, and Chenani, and cried with a loud voice unto the LORD their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 5, E'Then the Levites, Jeshua, and Kadmiel, Bani, Hashabniah, Sherebiah, Hodijah, Shebaniah, and Pethahiah, said, Stand up and bless the LORD your God for ever and ever: and blessed be thy glorious name, which is exalted above all blessing and praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 6, E'Thou, even thou, art LORD alone; thou hast made heaven, the heaven of heavens, with all their host, the earth, and all things that are therein, the seas, and all that is therein, and thou preservest them all; and the host of heaven worshippeth thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 7, E'Thou art the LORD the God, who didst choose Abram, and broughtest him forth out of Ur of the Chaldees, and gavest him the name of Abraham;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 8, E'And foundest his heart faithful before thee, and madest a covenant with him to give the land of the Canaanites, the Hittites, the Amorites, and the Perizzites, and the Jebusites, and the Girgashites, to give it, I say, to his seed, and hast performed thy words; for thou art righteous:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 9, E'And didst see the affliction of our fathers in Egypt, and heardest their cry by the Red sea;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 10, E'And shewedst signs and wonders upon Pharaoh, and on all his servants, and on all the people of his land: for thou knewest that they dealt proudly against them. So didst thou get thee a name, as it is this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 11, E'And thou didst divide the sea before them, so that they went through the midst of the sea on the dry land; and their persecutors thou threwest into the deeps, as a stone into the mighty waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 12, E'Moreover thou leddest them in the day by a cloudy pillar; and in the night by a pillar of fire, to give them light in the way wherein they should go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 13, E'Thou camest down also upon mount Sinai, and spakest with them from heaven, and gavest them right judgments, and true laws, good statutes and commandments:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 14, E'And madest known unto them thy holy sabbath, and commandedst them precepts, statutes, and laws, by the hand of Moses thy servant:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 15, E'And gavest them bread from heaven for their hunger, and broughtest forth water for them out of the rock for their thirst, and promisedst them that they should go in to possess the land which thou hadst sworn to give them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 16, E'But they and our fathers dealt proudly, and hardened their necks, and hearkened not to thy commandments,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 17, E'And refused to obey, neither were mindful of thy wonders that thou didst among them; but hardened their necks, and in their rebellion appointed a captain to return to their bondage: but thou art a God ready to pardon, gracious and merciful, slow to anger, and of great kindness, and forsookest them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 18, E'Yea, when they had made them a molten calf, and said, This is thy God that brought thee up out of Egypt, and had wrought great provocations;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 19, E'Yet thou in thy manifold mercies forsookest them not in the wilderness: the pillar of the cloud departed not from them by day, to lead them in the way; neither the pillar of fire by night, to shew them light, and the way wherein they should go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 20, E'Thou gavest also thy good spirit to instruct them, and withheldest not thy manna from their mouth, and gavest them water for their thirst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 21, E'Yea, forty years didst thou sustain them in the wilderness, so that they lacked nothing; their clothes waxed not old, and their feet swelled not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 22, E'Moreover thou gavest them kingdoms and nations, and didst divide them into corners: so they possessed the land of Sihon, and the land of the king of Heshbon, and the land of Og king of Bashan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 23, E'Their children also multipliedst thou as the stars of heaven, and broughtest them into the land, concerning which thou hadst promised to their fathers, that they should go in to possess it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 24, E'So the children went in and possessed the land, and thou subduedst before them the inhabitants of the land, the Canaanites, and gavest them into their hands, with their kings, and the people of the land, that they might do with them as they would.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 25, E'And they took strong cities, and a fat land, and possessed houses full of all goods, wells digged, vineyards, and oliveyards, and fruit trees in abundance: so they did eat, and were filled, and became fat, and delighted themselves in thy great goodness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 26, E'Nevertheless they were disobedient, and rebelled against thee, and cast thy law behind their backs, and slew thy prophets which testified against them to turn them to thee, and they wrought great provocations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 27, E'Therefore thou deliveredst them into the hand of their enemies, who vexed them: and in the time of their trouble, when they cried unto thee, thou heardest them from heaven; and according to thy manifold mercies thou gavest them saviours, who saved them out of the hand of their enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 28, E'But after they had rest, they did evil again before thee: therefore leftest thou them in the hand of their enemies, so that they had the dominion over them: yet when they returned, and cried unto thee, thou heardest them from heaven; and many times didst thou deliver them according to thy mercies;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 29, E'And testifiedst against them, that thou mightest bring them again unto thy law: yet they dealt proudly, and hearkened not unto thy commandments, but sinned against thy judgments, (which if a man do, he shall live in them;) and withdrew the shoulder, and hardened their neck, and would not hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 30, E'Yet many years didst thou forbear them, and testifiedst against them by thy spirit in thy prophets: yet would they not give ear: therefore gavest thou them into the hand of the people of the lands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 31, E'Nevertheless for thy great mercies’ sake thou didst not utterly consume them, nor forsake them; for thou art a gracious and merciful God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 32, E'Now therefore, our God, the great, the mighty, and the terrible God, who keepest covenant and mercy, let not all the trouble seem little before thee, that hath come upon us, on our kings, on our princes, and on our priests, and on our prophets, and on our fathers, and on all thy people, since the time of the kings of Assyria unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 33, E'Howbeit thou art just in all that is brought upon us; for thou hast done right, but we have done wickedly:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 34, E'Neither have our kings, our princes, our priests, nor our fathers, kept thy law, nor hearkened unto thy commandments and thy testimonies, wherewith thou didst testify against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 35, E'For they have not served thee in their kingdom, and in thy great goodness that thou gavest them, and in the large and fat land which thou gavest before them, neither turned they from their wicked works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 36, E'Behold, we are servants this day, and for the land that thou gavest unto our fathers to eat the fruit thereof and the good thereof, behold, we are servants in it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 37, E'And it yieldeth much increase unto the kings whom thou hast set over us because of our sins: also they have dominion over our bodies, and over our cattle, at their pleasure, and we are in great distress.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 9, 38, E'And because of all this we make a sure covenant, and write it; and our princes, Levites, and priests, seal unto it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 1, E'Now those that sealed were, Nehemiah, the Tirshatha, the son of Hachaliah, and Zidkijah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 2, E'Seraiah, Azariah, Jeremiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 3, E'Pashur, Amariah, Malchijah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 4, E'Hattush, Shebaniah, Malluch,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 5, E'Harim, Meremoth, Obadiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 6, E'Daniel, Ginnethon, Baruch,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 7, E'Meshullam, Abijah, Mijamin,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 8, E'Maaziah, Bilgai, Shemaiah: these were the priests.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 9, E'And the Levites: both Jeshua the son of Azaniah, Binnui of the sons of Henadad, Kadmiel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 10, E'And their brethren, Shebaniah, Hodijah, Kelita, Pelaiah, Hanan,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 11, E'Micha, Rehob, Hashabiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 12, E'Zaccur, Sherebiah, Shebaniah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 13, E'Hodijah, Bani, Beninu.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 14, E'The chief of the people; Parosh, Pahathmoab, Elam, Zatthu, Bani,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 15, E'Bunni, Azgad, Bebai,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 16, E'Adonijah, Bigvai, Adin,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 17, E'Ater, Hizkijah, Azzur,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 18, E'Hodijah, Hashum, Bezai,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 19, E'Hariph, Anathoth, Nebai,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 20, E'Magpiash, Meshullam, Hezir,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 21, E'Meshezabeel, Zadok, Jaddua,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 22, E'Pelatiah, Hanan, Anaiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 23, E'Hoshea, Hananiah, Hashub,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 24, E'Hallohesh, Pileha, Shobek,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 25, E'Rehum, Hashabnah, Maaseiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 26, E'And Ahijah, Hanan, Anan,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 27, E'Malluch, Harim, Baanah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 28, E'And the rest of the people, the priests, the Levites, the porters, the singers, the Nethinims, and all they that had separated themselves from the people of the lands unto the law of God, their wives, their sons, and their daughters, every one having knowledge, and having understanding;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 29, E'They clave to their brethren, their nobles, and entered into a curse, and into an oath, to walk in God’s law, which was given by Moses the servant of God, and to observe and do all the commandments of the LORD our Lord, and his judgments and his statutes;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 30, E'And that we would not give our daughters unto the people of the land, nor take their daughters for our sons:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 31, E'And if the people of the land bring ware or any victuals on the sabbath day to sell, that we would not buy it of them on the sabbath, or on the holy day: and that we would leave the seventh year, and the exaction of every debt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 32, E'Also we made ordinances for us, to charge ourselves yearly with the third part of a shekel for the service of the house of our God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 33, E'For the shewbread, and for the continual meat offering, and for the continual burnt offering, of the sabbaths, of the new moons, for the set feasts, and for the holy things, and for the sin offerings to make an atonement for Israel, and for all the work of the house of our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 34, E'And we cast the lots among the priests, the Levites, and the people, for the wood offering, to bring it into the house of our God, after the houses of our fathers, at times appointed year by year, to burn upon the altar of the LORD our God, as it is written in the law:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 35, E'And to bring the firstfruits of our ground, and the firstfruits of all fruit of all trees, year by year, unto the house of the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 36, E'Also the firstborn of our sons, and of our cattle, as it is written in the law, and the firstlings of our herds and of our flocks, to bring to the house of our God, unto the priests that minister in the house of our God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 37, E'And that we should bring the firstfruits of our dough, and our offerings, and the fruit of all manner of trees, of wine and of oil, unto the priests, to the chambers of the house of our God; and the tithes of our ground unto the Levites, that the same Levites might have the tithes in all the cities of our tillage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 38, E'And the priest the son of Aaron shall be with the Levites, when the Levites take tithes: and the Levites shall bring up the tithe of the tithes unto the house of our God, to the chambers, into the treasure house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 10, 39, E'For the children of Israel and the children of Levi shall bring the offering of the corn, of the new wine, and the oil, unto the chambers, where are the vessels of the sanctuary, and the priests that minister, and the porters, and the singers: and we will not forsake the house of our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 1, E'And the rulers of the people dwelt at Jerusalem: the rest of the people also cast lots, to bring one of ten to dwell in Jerusalem the holy city, and nine parts to dwell in other cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 2, E'And the people blessed all the men, that willingly offered themselves to dwell at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 3, E'Now these are the chief of the province that dwelt in Jerusalem: but in the cities of Judah dwelt every one in his possession in their cities, to wit, Israel, the priests, and the Levites, and the Nethinims, and the children of Solomon’s servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 4, E'And at Jerusalem dwelt certain of the children of Judah, and of the children of Benjamin. Of the children of Judah; Athaiah the son of Uzziah, the son of Zechariah, the son of Amariah, the son of Shephatiah, the son of Mahalaleel, of the children of Perez;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 5, E'And Maaseiah the son of Baruch, the son of Colhozeh, the son of Hazaiah, the son of Adaiah, the son of Joiarib, the son of Zechariah, the son of Shiloni.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 6, E'All the sons of Perez that dwelt at Jerusalem were four hundred threescore and eight valiant men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 7, E'And these are the sons of Benjamin; Sallu the son of Meshullam, the son of Joed, the son of Pedaiah, the son of Kolaiah, the son of Maaseiah, the son of Ithiel, the son of Jesaiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 8, E'And after him Gabbai, Sallai, nine hundred twenty and eight.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Nehemiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 9, E'And Joel the son of Zichri was their overseer: and Judah the son of Senuah was second over the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 10, E'Of the priests: Jedaiah the son of Joiarib, Jachin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 11, E'Seraiah the son of Hilkiah, the son of Meshullam, the son of Zadok, the son of Meraioth, the son of Ahitub, was the ruler of the house of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 12, E'And their brethren that did the work of the house were eight hundred twenty and two: and Adaiah the son of Jeroham, the son of Pelaliah, the son of Amzi, the son of Zechariah, the son of Pashur, the son of Malchiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 13, E'And his brethren, chief of the fathers, two hundred forty and two: and Amashai the son of Azareel, the son of Ahasai, the son of Meshillemoth, the son of Immer,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 14, E'And their brethren, mighty men of valour, an hundred twenty and eight: and their overseer was Zabdiel, the son of one of the great men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 15, E'Also of the Levites: Shemaiah the son of Hashub, the son of Azrikam, the son of Hashabiah, the son of Bunni;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 16, E'And Shabbethai and Jozabad, of the chief of the Levites, had the oversight of the outward business of the house of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 17, E'And Mattaniah the son of Micha, the son of Zabdi, the son of Asaph, was the principal to begin the thanksgiving in prayer: and Bakbukiah the second among his brethren, and Abda the son of Shammua, the son of Galal, the son of Jeduthun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 18, E'All the Levites in the holy city were two hundred fourscore and four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 19, E'Moreover the porters, Akkub, Talmon, and their brethren that kept the gates, were an hundred seventy and two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 20, E'And the residue of Israel, of the priests, and the Levites, were in all the cities of Judah, every one in his inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 21, E'But the Nethinims dwelt in Ophel: and Ziha and Gispa were over the Nethinims.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 22, E'The overseer also of the Levites at Jerusalem was Uzzi the son of Bani, the son of Hashabiah, the son of Mattaniah, the son of Micha. Of the sons of Asaph, the singers were over the business of the house of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 23, E'For it was the king’s commandment concerning them, that a certain portion should be for the singers, due for every day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 24, E'And Pethahiah the son of Meshezabeel, of the children of Zerah the son of Judah, was at the king’s hand in all matters concerning the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 25, E'And for the villages, with their fields, some of the children of Judah dwelt at Kirjatharba, and in the villages thereof, and at Dibon, and in the villages thereof, and at Jekabzeel, and in the villages thereof,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 26, E'And at Jeshua, and at Moladah, and at Bethphelet,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 27, E'And at Hazarshual, and at Beersheba, and in the villages thereof,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 28, E'And at Ziklag, and at Mekonah, and in the villages thereof,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 29, E'And at Enrimmon, and at Zareah, and at Jarmuth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 30, E'Zanoah, Adullam, and in their villages, at Lachish, and the fields thereof, at Azekah, and in the villages thereof. And they dwelt from Beersheba unto the valley of Hinnom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 31, E'The children also of Benjamin from Geba dwelt at Michmash, and Aija, and Bethel, and in their villages,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 32, E'And at Anathoth, Nob, Ananiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 33, E'Hazor, Ramah, Gittaim,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 34, E'Hadid, Zeboim, Neballat,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 35, E'Lod, and Ono, the valley of craftsmen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 11, 36, E'And of the Levites were divisions in Judah, and in Benjamin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 1, E'Now these are the priests and the Levites that went up with Zerubbabel the son of Shealtiel, and Jeshua: Seraiah, Jeremiah, Ezra,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 2, E'Amariah, Malluch, Hattush,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 3, E'Shechaniah, Rehum, Meremoth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 4, E'Iddo, Ginnetho, Abijah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 5, E'Miamin, Maadiah, Bilgah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 6, E'Shemaiah, and Joiarib, Jedaiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 7, E'Sallu, Amok, Hilkiah, Jedaiah. These were the chief of the priests and of their brethren in the days of Jeshua.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 8, E'Moreover the Levites: Jeshua, Binnui, Kadmiel, Sherebiah, Judah, and Mattaniah, which was over the thanksgiving, he and his brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 9, E'Also Bakbukiah and Unni, their brethren, were over against them in the watches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 10, E'And Jeshua begat Joiakim, Joiakim also begat Eliashib, and Eliashib begat Joiada,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 11, E'And Joiada begat Jonathan, and Jonathan begat Jaddua.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 12, E'And in the days of Joiakim were priests, the chief of the fathers: of Seraiah, Meraiah; of Jeremiah, Hananiah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 13, E'Of Ezra, Meshullam; of Amariah, Jehohanan;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 14, E'Of Melicu, Jonathan; of Shebaniah, Joseph;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 15, E'Of Harim, Adna; of Meraioth, Helkai;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 16, E'Of Iddo, Zechariah; of Ginnethon, Meshullam;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 17, E'Of Abijah, Zichri; of Miniamin, of Moadiah, Piltai;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 18, E'Of Bilgah, Shammua; of Shemaiah, Jehonathan;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 19, E'And of Joiarib, Mattenai; of Jedaiah, Uzzi;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 20, E'Of Sallai, Kallai; of Amok, Eber;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 21, E'Of Hilkiah, Hashabiah; of Jedaiah, Nethaneel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 22, E'The Levites in the days of Eliashib, Joiada, and Johanan, and Jaddua, were recorded chief of the fathers: also the priests, to the reign of Darius the Persian.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 23, E'The sons of Levi, the chief of the fathers, were written in the book of the chronicles, even until the days of Johanan the son of Eliashib.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 24, E'And the chief of the Levites: Hashabiah, Sherebiah, and Jeshua the son of Kadmiel, with their brethren over against them, to praise and to give thanks, according to the commandment of David the man of God, ward over against ward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 25, E'Mattaniah, and Bakbukiah, Obadiah, Meshullam, Talmon, Akkub, were porters keeping the ward at the thresholds of the gates.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 26, E'These were in the days of Joiakim the son of Jeshua, the son of Jozadak, and in the days of Nehemiah the governor, and of Ezra the priest, the scribe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 27, E'And at the dedication of the wall of Jerusalem they sought the Levites out of all their places, to bring them to Jerusalem, to keep the dedication with gladness, both with thanksgivings, and with singing, with cymbals, psalteries, and with harps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 28, E'And the sons of the singers gathered themselves together, both out of the plain country round about Jerusalem, and from the villages of Netophathi;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 29, E'Also from the house of Gilgal, and out of the fields of Geba and Azmaveth: for the singers had builded them villages round about Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 30, E'And the priests and the Levites purified themselves, and purified the people, and the gates, and the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 31, E'Then I brought up the princes of Judah upon the wall, and appointed two great companies of them that gave thanks, whereof one went on the right hand upon the wall toward the dung gate:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 32, E'And after them went Hoshaiah, and half of the princes of Judah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 33, E'And Azariah, Ezra, and Meshullam,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 34, E'Judah, and Benjamin, and Shemaiah, and Jeremiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 35, E'And certain of the priests’ sons with trumpets; namely, Zechariah the son of Jonathan, the son of Shemaiah, the son of Mattaniah, the son of Michaiah, the son of Zaccur, the son of Asaph:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 36, E'And his brethren, Shemaiah, and Azarael, Milalai, Gilalai, Maai, Nethaneel, and Judah, Hanani, with the musical instruments of David the man of God, and Ezra the scribe before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 37, E'And at the fountain gate, which was over against them, they went up by the stairs of the city of David, at the going up of the wall, above the house of David, even unto the water gate eastward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 38, E'And the other company of them that gave thanks went over against them, and I after them, and the half of the people upon the wall, from beyond the tower of the furnaces even unto the broad wall;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 39, E'And from above the gate of Ephraim, and above the old gate, and above the fish gate, and the tower of Hananeel, and the tower of Meah, even unto the sheep gate: and they stood still in the prison gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 40, E'So stood the two companies of them that gave thanks in the house of God, and I, and the half of the rulers with me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 41, E'And the priests; Eliakim, Maaseiah, Miniamin, Michaiah, Elioenai, Zechariah, and Hananiah, with trumpets;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 42, E'And Maaseiah, and Shemaiah, and Eleazar, and Uzzi, and Jehohanan, and Malchijah, and Elam, and Ezer. And the singers sang loud, with Jezrahiah their overseer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 43, E'Also that day they offered great sacrifices, and rejoiced: for God had made them rejoice with great joy: the wives also and the children rejoiced: so that the joy of Jerusalem was heard even afar off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 44, E'And at that time were some appointed over the chambers for the treasures, for the offerings, for the firstfruits, and for the tithes, to gather into them out of the fields of the cities the portions of the law for the priests and Levites: for Judah rejoiced for the priests and for the Levites that waited.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 45, E'And both the singers and the porters kept the ward of their God, and the ward of the purification, according to the commandment of David, and of Solomon his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 46, E'For in the days of David and Asaph of old there were chief of the singers, and songs of praise and thanksgiving unto God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 12, 47, E'And all Israel in the days of Zerubbabel, and in the days of Nehemiah, gave the portions of the singers and the porters, every day his portion: and they sanctified holy things unto the Levites; and the Levites sanctified them unto the children of Aaron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 1, E'On that day they read in the book of Moses in the audience of the people; and therein was found written, that the Ammonite and the Moabite should not come into the congregation of God for ever;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 2, E'Because they met not the children of Israel with bread and with water, but hired Balaam against them, that he should curse them: howbeit our God turned the curse into a blessing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 3, E'Now it came to pass, when they had heard the law, that they separated from Israel all the mixed multitude.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 4, E'And before this, Eliashib the priest, having the oversight of the chamber of the house of our God, was allied unto Tobiah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 5, E'And he had prepared for him a great chamber, where aforetime they laid the meat offerings, the frankincense, and the vessels, and the tithes of the corn, the new wine, and the oil, which was commanded to be given to the Levites, and the singers, and the porters; and the offerings of the priests.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 6, E'But in all this time was not I at Jerusalem: for in the two and thirtieth year of Artaxerxes king of Babylon came I unto the king, and after certain days obtained I leave of the king:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 7, E'And I came to Jerusalem, and understood of the evil that Eliashib did for Tobiah, in preparing him a chamber in the courts of the house of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 8, E'And it grieved me sore: therefore I cast forth all the household stuff of Tobiah out of the chamber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 9, E'Then I commanded, and they cleansed the chambers: and thither brought I again the vessels of the house of God, with the meat offering and the frankincense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 10, E'And I perceived that the portions of the Levites had not been given them: for the Levites and the singers, that did the work, were fled every one to his field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 11, E'Then contended I with the rulers, and said, Why is the house of God forsaken? And I gathered them together, and set them in their place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 12, E'Then brought all Judah the tithe of the corn and the new wine and the oil unto the treasuries.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 13, E'And I made treasurers over the treasuries, Shelemiah the priest, and Zadok the scribe, and of the Levites, Pedaiah: and next to them was Hanan the son of Zaccur, the son of Mattaniah: for they were counted faithful, and their office was to distribute unto their brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 14, E'Remember me, O my God, concerning this, and wipe not out my good deeds that I have done for the house of my God, and for the offices thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 15, E'In those days saw I in Judah some treading wine presses on the sabbath, and bringing in sheaves, and lading asses; as also wine, grapes, and figs, and all manner of burdens, which they brought into Jerusalem on the sabbath day: and I testified against them in the day wherein they sold victuals.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 16, E'There dwelt men of Tyre also therein, which brought fish, and all manner of ware, and sold on the sabbath unto the children of Judah, and in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 17, E'Then I contended with the nobles of Judah, and said unto them, What evil thing is this that ye do, and profane the sabbath day?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 18, E'Did not your fathers thus, and did not our God bring all this evil upon us, and upon this city? yet ye bring more wrath upon Israel by profaning the sabbath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 19, E'And it came to pass, that when the gates of Jerusalem began to be dark before the sabbath, I commanded that the gates should be shut, and charged that they should not be opened till after the sabbath: and some of my servants set I at the gates, that there should no burden be brought in on the sabbath day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 20, E'So the merchants and sellers of all kind of ware lodged without Jerusalem once or twice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 21, E'Then I testified against them, and said unto them, Why lodge ye about the wall? if ye do so again, I will lay hands on you. From that time forth came they no more on the sabbath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 22, E'And I commanded the Levites that they should cleanse themselves, and that they should come and keep the gates, to sanctify the sabbath day. Remember me, O my God, concerning this also, and spare me according to the greatness of thy mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 23, E'In those days also saw I Jews that had married wives of Ashdod, of Ammon, and of Moab:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 24, E'And their children spake half in the speech of Ashdod, and could not speak in the Jews’ language, but according to the language of each people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 25, E'And I contended with them, and cursed them, and smote certain of them, and plucked off their hair, and made them swear by God, saying, Ye shall not give your daughters unto their sons, nor take their daughters unto your sons, or for yourselves.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Nehemiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 26, E'Did not Solomon king of Israel sin by these things? yet among many nations was there no king like him, who was beloved of his God, and God made him king over all Israel: nevertheless even him did outlandish women cause to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 27, E'Shall we then hearken unto you to do all this great evil, to transgress against our God in marrying strange wives?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 28, E'And one of the sons of Joiada, the son of Eliashib the high priest, was son in law to Sanballat the Horonite: therefore I chased him from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 29, E'Remember them, O my God, because they have defiled the priesthood, and the covenant of the priesthood, and of the Levites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 30, E'Thus cleansed I them from all strangers, and appointed the wards of the priests and the Levites, every one in his business;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0cf7952e-9b08-47ab-94b3-c02b80fd64c2', 13, 31, E'And for the wood offering, at times appointed, and for the firstfruits. Remember me, O my God, for good.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Nehemiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 1, E'Now it came to pass in the days of Ahasuerus, (this is Ahasuerus which reigned, from India even unto Ethiopia, over an hundred and seven and twenty provinces:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 2, E'That in those days, when the king Ahasuerus sat on the throne of his kingdom, which was in Shushan the palace,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 3, E'In the third year of his reign, he made a feast unto all his princes and his servants; the power of Persia and Media, the nobles and princes of the provinces, being before him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 4, E'When he shewed the riches of his glorious kingdom and the honour of his excellent majesty many days, even an hundred and fourscore days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 5, E'And when these days were expired, the king made a feast unto all the people that were present in Shushan the palace, both unto great and small, seven days, in the court of the garden of the king’s palace;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 6, E'Where were white, green, and blue, hangings, fastened with cords of fine linen and purple to silver rings and pillars of marble: the beds were of gold and silver, upon a pavement of red, and blue, and white, and black, marble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 7, E'And they gave them drink in vessels of gold, (the vessels being diverse one from another,) and royal wine in abundance, according to the state of the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 8, E'And the drinking was according to the law; none did compel: for so the king had appointed to all the officers of his house, that they should do according to every man’s pleasure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 9, E'Also Vashti the queen made a feast for the women in the royal house which belonged to king Ahasuerus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 10, E'On the seventh day, when the heart of the king was merry with wine, he commanded Mehuman, Biztha, Harbona, Bigtha, and Abagtha, Zethar, and Carcas, the seven chamberlains that served in the presence of Ahasuerus the king,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 11, E'To bring Vashti the queen before the king with the crown royal, to shew the people and the princes her beauty: for she was fair to look on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 12, E'But the queen Vashti refused to come at the king’s commandment by his chamberlains: therefore was the king very wroth, and his anger burned in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 13, E'Then the king said to the wise men, which knew the times, (for so was the king’s manner toward all that knew law and judgment:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 14, E'And the next unto him was Carshena, Shethar, Admatha, Tarshish, Meres, Marsena, and Memucan, the seven princes of Persia and Media, which saw the king’s face, and which sat the first in the kingdom;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 15, E'What shall we do unto the queen Vashti according to law, because she hath not performed the commandment of the king Ahasuerus by the chamberlains?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 16, E'And Memucan answered before the king and the princes, Vashti the queen hath not done wrong to the king only, but also to all the princes, and to all the people that are in all the provinces of the king Ahasuerus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 17, E'For this deed of the queen shall come abroad unto all women, so that they shall despise their husbands in their eyes, when it shall be reported, The king Ahasuerus commanded Vashti the queen to be brought in before him, but she came not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 18, E'Likewise shall the ladies of Persia and Media say this day unto all the king’s princes, which have heard of the deed of the queen. Thus shall there arise too much contempt and wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 19, E'If it please the king, let there go a royal commandment from him, and let it be written among the laws of the Persians and the Medes, that it be not altered, That Vashti come no more before king Ahasuerus; and let the king give her royal estate unto another that is better than she.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 20, E'And when the king’s decree which he shall make shall be published throughout all his empire, (for it is great,) all the wives shall give to their husbands honour, both to great and small.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 21, E'And the saying pleased the king and the princes; and the king did according to the word of Memucan:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 1, 22, E'For he sent letters into all the king’s provinces, into every province according to the writing thereof, and to every people after their language, that every man should bear rule in his own house, and that it should be published according to the language of every people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 1, E'After these things, when the wrath of king Ahasuerus was appeased, he remembered Vashti, and what she had done, and what was decreed against her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 2, E'Then said the king’s servants that ministered unto him, Let there be fair young virgins sought for the king:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 3, E'And let the king appoint officers in all the provinces of his kingdom, that they may gather together all the fair young virgins unto Shushan the palace, to the house of the women, unto the custody of Hege the king’s chamberlain, keeper of the women; and let their things for purification be given them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 4, E'And let the maiden which pleaseth the king be queen instead of Vashti. And the thing pleased the king; and he did so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 5, E'Now in Shushan the palace there was a certain Jew, whose name was Mordecai, the son of Jair, the son of Shimei, the son of Kish, a Benjamite;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 6, E'Who had been carried away from Jerusalem with the captivity which had been carried away with Jeconiah king of Judah, whom Nebuchadnezzar the king of Babylon had carried away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 7, E'And he brought up Hadassah, that is, Esther, his uncle’s daughter: for she had neither father nor mother, and the maid was fair and beautiful; whom Mordecai, when her father and mother were dead, took for his own daughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 8, E'So it came to pass, when the king’s commandment and his decree was heard, and when many maidens were gathered together unto Shushan the palace, to the custody of Hegai, that Esther was brought also unto the king’s house, to the custody of Hegai, keeper of the women.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 9, E'And the maiden pleased him, and she obtained kindness of him; and he speedily gave her her things for purification, with such things as belonged to her, and seven maidens, which were meet to be given her, out of the king’s house: and he preferred her and her maids unto the best place of the house of the women.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 10, E'Esther had not shewed her people nor her kindred: for Mordecai had charged her that she should not shew it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 11, E'And Mordecai walked every day before the court of the women’s house, to know how Esther did, and what should become of her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 12, E'Now when every maid’s turn was come to go in to king Ahasuerus, after that she had been twelve months, according to the manner of the women, (for so were the days of their purifications accomplished, to wit, six months with oil of myrrh, and six months with sweet odours, and with other things for the purifying of the women;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 13, E'Then thus came every maiden unto the king; whatsoever she desired was given her to go with her out of the house of the women unto the king’s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 14, E'In the evening she went, and on the morrow she returned into the second house of the women, to the custody of Shaashgaz, the king’s chamberlain, which kept the concubines: she came in unto the king no more, except the king delighted in her, and that she were called by name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 15, E'Now when the turn of Esther, the daughter of Abihail the uncle of Mordecai, who had taken her for his daughter, was come to go in unto the king, she required nothing but what Hegai the king’s chamberlain, the keeper of the women, appointed. And Esther obtained favour in the sight of all them that looked upon her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 16, E'So Esther was taken unto king Ahasuerus into his house royal in the tenth month, which is the month Tebeth, in the seventh year of his reign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 17, E'And the king loved Esther above all the women, and she obtained grace and favour in his sight more than all the virgins; so that he set the royal crown upon her head, and made her queen instead of Vashti.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 18, E'Then the king made a great feast unto all his princes and his servants, even Esther’s feast; and he made a release to the provinces, and gave gifts, according to the state of the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 19, E'And when the virgins were gathered together the second time, then Mordecai sat in the king’s gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 20, E'Esther had not yet shewed her kindred nor her people; as Mordecai had charged her: for Esther did the commandment of Mordecai, like as when she was brought up with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 21, E'In those days, while Mordecai sat in the king’s gate, two of the king’s chamberlains, Bigthan and Teresh, of those which kept the door, were wroth, and sought to lay hand on the king Ahasuerus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 22, E'And the thing was known to Mordecai, who told it unto Esther the queen; and Esther certified the king thereof in Mordecai’s name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 2, 23, E'And when inquisition was made of the matter, it was found out; therefore they were both hanged on a tree: and it was written in the book of the chronicles before the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 1, E'After these things did king Ahasuerus promote Haman the son of Hammedatha the Agagite, and advanced him, and set his seat above all the princes that were with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 2, E'And all the king’s servants, that were in the king’s gate, bowed, and reverenced Haman: for the king had so commanded concerning him. But Mordecai bowed not, nor did him reverence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 3, E'Then the king’s servants, which were in the king’s gate, said unto Mordecai, Why transgressest thou the king’s commandment?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 4, E'Now it came to pass, when they spake daily unto him, and he hearkened not unto them, that they told Haman, to see whether Mordecai’s matters would stand: for he had told them that he was a Jew.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 5, E'And when Haman saw that Mordecai bowed not, nor did him reverence, then was Haman full of wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 6, E'And he thought scorn to lay hands on Mordecai alone; for they had shewed him the people of Mordecai: wherefore Haman sought to destroy all the Jews that were throughout the whole kingdom of Ahasuerus, even the people of Mordecai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 7, E'In the first month, that is, the month Nisan, in the twelfth year of king Ahasuerus, they cast Pur, that is, the lot, before Haman from day to day, and from month to month, to the twelfth month, that is, the month Adar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 8, E'And Haman said unto king Ahasuerus, There is a certain people scattered abroad and dispersed among the people in all the provinces of thy kingdom; and their laws are diverse from all people; neither keep they the king’s laws: therefore it is not for the king’s profit to suffer them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 9, E'If it please the king, let it be written that they may be destroyed: and I will pay ten thousand talents of silver to the hands of those that have the charge of the business, to bring it into the king’s treasuries.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 10, E'And the king took his ring from his hand, and gave it unto Haman the son of Hammedatha the Agagite, the Jews’ enemy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 11, E'And the king said unto Haman, The silver is given to thee, the people also, to do with them as it seemeth good to thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 12, E'Then were the king’s scribes called on the thirteenth day of the first month, and there was written according to all that Haman had commanded unto the king’s lieutenants, and to the governors that were over every province, and to the rulers of every people of every province according to the writing thereof, and to every people after their language; in the name of king Ahasuerus was it written, and sealed with the king’s ring.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 13, E'And the letters were sent by posts into all the king’s provinces, to destroy, to kill, and to cause to perish, all Jews, both young and old, little children and women, in one day, even upon the thirteenth day of the twelfth month, which is the month Adar, and to take the spoil of them for a prey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 14, E'The copy of the writing for a commandment to be given in every province was published unto all people, that they should be ready against that day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 3, 15, E'The posts went out, being hastened by the king’s commandment, and the decree was given in Shushan the palace. And the king and Haman sat down to drink; but the city Shushan was perplexed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 1, E'When Mordecai perceived all that was done, Mordecai rent his clothes, and put on sackcloth with ashes, and went out into the midst of the city, and cried with a loud and a bitter cry;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 2, E'And came even before the king’s gate: for none might enter into the king’s gate clothed with sackcloth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 3, E'And in every province, whithersoever the king’s commandment and his decree came, there was great mourning among the Jews, and fasting, and weeping, and wailing; and many lay in sackcloth and ashes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 4, E'So Esther’s maids and her chamberlains came and told it her. Then was the queen exceedingly grieved; and she sent raiment to clothe Mordecai, and to take away his sackcloth from him: but he received it not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 5, E'Then called Esther for Hatach, one of the king’s chamberlains, whom he had appointed to attend upon her, and gave him a commandment to Mordecai, to know what it was, and why it was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 6, E'So Hatach went forth to Mordecai unto the street of the city, which was before the king’s gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 7, E'And Mordecai told him of all that had happened unto him, and of the sum of the money that Haman had promised to pay to the king’s treasuries for the Jews, to destroy them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 8, E'Also he gave him the copy of the writing of the decree that was given at Shushan to destroy them, to shew it unto Esther, and to declare it unto her, and to charge her that she should go in unto the king, to make supplication unto him, and to make request before him for her people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 9, E'And Hatach came and told Esther the words of Mordecai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 10, E'Again Esther spake unto Hatach, and gave him commandment unto Mordecai;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 11, E'All the king’s servants, and the people of the king’s provinces, do know, that whosoever, whether man or woman, shall come unto the king into the inner court, who is not called, there is one law of his to put him to death, except such to whom the king shall hold out the golden sceptre, that he may live: but I have not been called to come in unto the king these thirty days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 12, E'And they told to Mordecai Esther’s words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 13, E'Then Mordecai commanded to answer Esther, Think not with thyself that thou shalt escape in the king’s house, more than all the Jews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 14, E'For if thou altogether holdest thy peace at this time, then shall there enlargement and deliverance arise to the Jews from another place; but thou and thy father’s house shall be destroyed: and who knoweth whether thou art come to the kingdom for such a time as this?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 15, E'Then Esther bade them return Mordecai this answer,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 16, E'Go, gather together all the Jews that are present in Shushan, and fast ye for me, and neither eat nor drink three days, night or day: I also and my maidens will fast likewise; and so will I go in unto the king, which is not according to the law: and if I perish, I perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 4, 17, E'So Mordecai went his way, and did according to all that Esther had commanded him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 1, E'Now it came to pass on the third day, that Esther put on her royal apparel, and stood in the inner court of the king’s house, over against the king’s house: and the king sat upon his royal throne in the royal house, over against the gate of the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 2, E'And it was so, when the king saw Esther the queen standing in the court, that she obtained favour in his sight: and the king held out to Esther the golden sceptre that was in his hand. So Esther drew near, and touched the top of the sceptre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 3, E'Then said the king unto her, What wilt thou, queen Esther? and what is thy request? it shall be even given thee to the half of the kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 4, E'And Esther answered, If it seem good unto the king, let the king and Haman come this day unto the banquet that I have prepared for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 5, E'Then the king said, Cause Haman to make haste, that he may do as Esther hath said. So the king and Haman came to the banquet that Esther had prepared.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 6, E'And the king said unto Esther at the banquet of wine, What is thy petition? and it shall be granted thee: and what is thy request? even to the half of the kingdom it shall be performed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 7, E'Then answered Esther, and said, My petition and my request is;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 8, E'If I have found favour in the sight of the king, and if it please the king to grant my petition, and to perform my request, let the king and Haman come to the banquet that I shall prepare for them, and I will do to morrow as the king hath said.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 9, E'Then went Haman forth that day joyful and with a glad heart: but when Haman saw Mordecai in the king’s gate, that he stood not up, nor moved for him, he was full of indignation against Mordecai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 10, E'Nevertheless Haman refrained himself: and when he came home, he sent and called for his friends, and Zeresh his wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 11, E'And Haman told them of the glory of his riches, and the multitude of his children, and all the things wherein the king had promoted him, and how he had advanced him above the princes and servants of the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 12, E'Haman said moreover, Yea, Esther the queen did let no man come in with the king unto the banquet that she had prepared but myself; and to morrow am I invited unto her also with the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 13, E'Yet all this availeth me nothing, so long as I see Mordecai the Jew sitting at the king’s gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 5, 14, E'Then said Zeresh his wife and all his friends unto him, Let a gallows be made of fifty cubits high, and to morrow speak thou unto the king that Mordecai may be hanged thereon: then go thou in merrily with the king unto the banquet. And the thing pleased Haman; and he caused the gallows to be made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 1, E'On that night could not the king sleep, and he commanded to bring the book of records of the chronicles; and they were read before the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 2, E'And it was found written, that Mordecai had told of Bigthana and Teresh, two of the king’s chamberlains, the keepers of the door, who sought to lay hand on the king Ahasuerus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 3, E'And the king said, What honour and dignity hath been done to Mordecai for this? Then said the king’s servants that ministered unto him, There is nothing done for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 4, E'And the king said, Who is in the court? Now Haman was come into the outward court of the king’s house, to speak unto the king to hang Mordecai on the gallows that he had prepared for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 5, E'And the king’s servants said unto him, Behold, Haman standeth in the court. And the king said, Let him come in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 6, E'So Haman came in. And the king said unto him, What shall be done unto the man whom the king delighteth to honour? Now Haman thought in his heart, To whom would the king delight to do honour more than to myself?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 7, E'And Haman answered the king, For the man whom the king delighteth to honour,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 8, E'Let the royal apparel be brought which the king useth to wear, and the horse that the king rideth upon, and the crown royal which is set upon his head:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 9, E'And let this apparel and horse be delivered to the hand of one of the king’s most noble princes, that they may array the man withal whom the king delighteth to honour, and bring him on horseback through the street of the city, and proclaim before him, Thus shall it be done to the man whom the king delighteth to honour.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Esther') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 10, E'Then the king said to Haman, Make haste, and take the apparel and the horse, as thou hast said, and do even so to Mordecai the Jew, that sitteth at the king’s gate: let nothing fail of all that thou hast spoken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 11, E'Then took Haman the apparel and the horse, and arrayed Mordecai, and brought him on horseback through the street of the city, and proclaimed before him, Thus shall it be done unto the man whom the king delighteth to honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 12, E'And Mordecai came again to the king’s gate. But Haman hasted to his house mourning, and having his head covered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 13, E'And Haman told Zeresh his wife and all his friends every thing that had befallen him. Then said his wise men and Zeresh his wife unto him, If Mordecai be of the seed of the Jews, before whom thou hast begun to fall, thou shalt not prevail against him, but shalt surely fall before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 6, 14, E'And while they were yet talking with him, came the king’s chamberlains, and hasted to bring Haman unto the banquet that Esther had prepared.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 7, 1, E'So the king and Haman came to banquet with Esther the queen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 7, 2, E'And the king said again unto Esther on the second day at the banquet of wine, What is thy petition, queen Esther? and it shall be granted thee: and what is thy request? and it shall be performed, even to the half of the kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 7, 3, E'Then Esther the queen answered and said, If I have found favour in thy sight, O king, and if it please the king, let my life be given me at my petition, and my people at my request:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 7, 4, E'For we are sold, I and my people, to be destroyed, to be slain, and to perish. But if we had been sold for bondmen and bondwomen, I had held my tongue, although the enemy could not countervail the king’s damage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 7, 5, E'Then the king Ahasuerus answered and said unto Esther the queen, Who is he, and where is he, that durst presume in his heart to do so?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 7, 6, E'And Esther said, The adversary and enemy is this wicked Haman. Then Haman was afraid before the king and the queen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 7, 7, E'And the king arising from the banquet of wine in his wrath went into the palace garden: and Haman stood up to make request for his life to Esther the queen; for he saw that there was evil determined against him by the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 7, 8, E'Then the king returned out of the palace garden into the place of the banquet of wine; and Haman was fallen upon the bed whereon Esther was. Then said the king, Will he force the queen also before me in the house? As the word went out of the king’s mouth, they covered Haman’s face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 7, 9, E'And Harbonah, one of the chamberlains, said before the king, Behold also, the gallows fifty cubits high, which Haman had made for Mordecai, who had spoken good for the king, standeth in the house of Haman. Then the king said, Hang him thereon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 7, 10, E'So they hanged Haman on the gallows that he had prepared for Mordecai. Then was the king’s wrath pacified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 1, E'On that day did the king Ahasuerus give the house of Haman the Jews’ enemy unto Esther the queen. And Mordecai came before the king; for Esther had told what he was unto her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 2, E'And the king took off his ring, which he had taken from Haman, and gave it unto Mordecai. And Esther set Mordecai over the house of Haman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 3, E'And Esther spake yet again before the king, and fell down at his feet, and besought him with tears to put away the mischief of Haman the Agagite, and his device that he had devised against the Jews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 4, E'Then the king held out the golden sceptre toward Esther. So Esther arose, and stood before the king,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 5, E'And said, If it please the king, and if I have found favour in his sight, and the thing seem right before the king, and I be pleasing in his eyes, let it be written to reverse the letters devised by Haman the son of Hammedatha the Agagite, which he wrote to destroy the Jews which are in all the king’s provinces:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 6, E'For how can I endure to see the evil that shall come unto my people? or how can I endure to see the destruction of my kindred?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 7, E'Then the king Ahasuerus said unto Esther the queen and to Mordecai the Jew, Behold, I have given Esther the house of Haman, and him they have hanged upon the gallows, because he laid his hand upon the Jews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 8, E'Write ye also for the Jews, as it liketh you, in the king’s name, and seal it with the king’s ring: for the writing which is written in the king’s name, and sealed with the king’s ring, may no man reverse.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 9, E'Then were the king’s scribes called at that time in the third month, that is, the month Sivan, on the three and twentieth day thereof; and it was written according to all that Mordecai commanded unto the Jews, and to the lieutenants, and the deputies and rulers of the provinces which are from India unto Ethiopia, an hundred twenty and seven provinces, unto every province according to the writing thereof, and unto every people after their language, and to the Jews according to their writing, and according to their language.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 10, E'And he wrote in the king Ahasuerus’ name, and sealed it with the king’s ring, and sent letters by posts on horseback, and riders on mules, camels, and young dromedaries:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 11, E'Wherein the king granted the Jews which were in every city to gather themselves together, and to stand for their life, to destroy, to slay, and to cause to perish, all the power of the people and province that would assault them, both little ones and women, and to take the spoil of them for a prey,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 12, E'Upon one day in all the provinces of king Ahasuerus, namely, upon the thirteenth day of the twelfth month, which is the month Adar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 13, E'The copy of the writing for a commandment to be given in every province was published unto all people, and that the Jews should be ready against that day to avenge themselves on their enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 14, E'So the posts that rode upon mules and camels went out, being hastened and pressed on by the king’s commandment. And the decree was given at Shushan the palace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 15, E'And Mordecai went out from the presence of the king in royal apparel of blue and white, and with a great crown of gold, and with a garment of fine linen and purple: and the city of Shushan rejoiced and was glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 16, E'The Jews had light, and gladness, and joy, and honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 8, 17, E'And in every province, and in every city, whithersoever the king’s commandment and his decree came, the Jews had joy and gladness, a feast and a good day. And many of the people of the land became Jews; for the fear of the Jews fell upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 1, E'Now in the twelfth month, that is, the month Adar, on the thirteenth day of the same, when the king’s commandment and his decree drew near to be put in execution, in the day that the enemies of the Jews hoped to have power over them, (though it was turned to the contrary, that the Jews had rule over them that hated them;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 2, E'The Jews gathered themselves together in their cities throughout all the provinces of the king Ahasuerus, to lay hand on such as sought their hurt: and no man could withstand them; for the fear of them fell upon all people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 3, E'And all the rulers of the provinces, and the lieutenants, and the deputies, and officers of the king, helped the Jews; because the fear of Mordecai fell upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 4, E'For Mordecai was great in the king’s house, and his fame went out throughout all the provinces: for this man Mordecai waxed greater and greater.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 5, E'Thus the Jews smote all their enemies with the stroke of the sword, and slaughter, and destruction, and did what they would unto those that hated them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 6, E'And in Shushan the palace the Jews slew and destroyed five hundred men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 7, E'And Parshandatha, and Dalphon, and Aspatha,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 8, E'And Poratha, and Adalia, and Aridatha,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 9, E'And Parmashta, and Arisai, and Aridai, and Vajezatha,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 10, E'The ten sons of Haman the son of Hammedatha, the enemy of the Jews, slew they; but on the spoil laid they not their hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 11, E'On that day the number of those that were slain in Shushan the palace was brought before the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 12, E'And the king said unto Esther the queen, The Jews have slain and destroyed five hundred men in Shushan the palace, and the ten sons of Haman; what have they done in the rest of the king’s provinces? now what is thy petition? and it shall be granted thee: or what is thy request further? and it shall be done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 13, E'Then said Esther, If it please the king, let it be granted to the Jews which are in Shushan to do to morrow also according unto this day’s decree, and let Haman’s ten sons be hanged upon the gallows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 14, E'And the king commanded it so to be done: and the decree was given at Shushan; and they hanged Haman’s ten sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 15, E'For the Jews that were in Shushan gathered themselves together on the fourteenth day also of the month Adar, and slew three hundred men at Shushan; but on the prey they laid not their hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 16, E'But the other Jews that were in the king’s provinces gathered themselves together, and stood for their lives, and had rest from their enemies, and slew of their foes seventy and five thousand, but they laid not their hands on the prey,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 17, E'On the thirteenth day of the month Adar; and on the fourteenth day of the same rested they, and made it a day of feasting and gladness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 18, E'But the Jews that were at Shushan assembled together on the thirteenth day thereof, and on the fourteenth thereof; and on the fifteenth day of the same they rested, and made it a day of feasting and gladness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 19, E'Therefore the Jews of the villages, that dwelt in the unwalled towns, made the fourteenth day of the month Adar a day of gladness and feasting, and a good day, and of sending portions one to another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 20, E'And Mordecai wrote these things, and sent letters unto all the Jews that were in all the provinces of the king Ahasuerus, both nigh and far,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 21, E'To stablish this among them, that they should keep the fourteenth day of the month Adar, and the fifteenth day of the same, yearly,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 22, E'As the days wherein the Jews rested from their enemies, and the month which was turned unto them from sorrow to joy, and from mourning into a good day: that they should make them days of feasting and joy, and of sending portions one to another, and gifts to the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 23, E'And the Jews undertook to do as they had begun, and as Mordecai had written unto them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 24, E'Because Haman the son of Hammedatha, the Agagite, the enemy of all the Jews, had devised against the Jews to destroy them, and had cast Pur, that is, the lot, to consume them, and to destroy them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 25, E'But when Esther came before the king, he commanded by letters that his wicked device, which he devised against the Jews, should return upon his own head, and that he and his sons should be hanged on the gallows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 26, E'Wherefore they called these days Purim after the name of Pur. Therefore for all the words of this letter, and of that which they had seen concerning this matter, and which had come unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 27, E'The Jews ordained, and took upon them, and upon their seed, and upon all such as joined themselves unto them, so as it should not fail, that they would keep these two days according to their writing, and according to their appointed time every year;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 28, E'And that these days should be remembered and kept throughout every generation, every family, every province, and every city; and that these days of Purim should not fail from among the Jews, nor the memorial of them perish from their seed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 29, E'Then Esther the queen, the daughter of Abihail, and Mordecai the Jew, wrote with all authority, to confirm this second letter of Purim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 30, E'And he sent the letters unto all the Jews, to the hundred twenty and seven provinces of the kingdom of Ahasuerus, with words of peace and truth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 31, E'To confirm these days of Purim in their times appointed, according as Mordecai the Jew and Esther the queen had enjoined them, and as they had decreed for themselves and for their seed, the matters of the fastings and their cry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 9, 32, E'And the decree of Esther confirmed these matters of Purim; and it was written in the book.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 10, 1, E'And the king Ahasuerus laid a tribute upon the land, and upon the isles of the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 10, 2, E'And all the acts of his power and of his might, and the declaration of the greatness of Mordecai, whereunto the king advanced him, are they not written in the book of the chronicles of the kings of Media and Persia?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6efcfc92-89d1-4940-b0f2-331164dc0b19', 10, 3, E'For Mordecai the Jew was next unto king Ahasuerus, and great among the Jews, and accepted of the multitude of his brethren, seeking the wealth of his people, and speaking peace to all his seed.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Esther') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 1, E'There was a man in the land of Uz, whose name was Job; and that man was perfect and upright, and one that feared God, and eschewed evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 2, E'And there were born unto him seven sons and three daughters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 3, E'His substance also was seven thousand sheep, and three thousand camels, and five hundred yoke of oxen, and five hundred she asses, and a very great household; so that this man was the greatest of all the men of the east.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 4, E'And his sons went and feasted in their houses, every one his day; and sent and called for their three sisters to eat and to drink with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 5, E'And it was so, when the days of their feasting were gone about, that Job sent and sanctified them, and rose up early in the morning, and offered burnt offerings according to the number of them all: for Job said, It may be that my sons have sinned, and cursed God in their hearts. Thus did Job continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 6, E'Now there was a day when the sons of God came to present themselves before the LORD, and Satan came also among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 7, E'And the LORD said unto Satan, Whence comest thou? Then Satan answered the LORD, and said, From going to and fro in the earth, and from walking up and down in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 8, E'And the LORD said unto Satan, Hast thou considered my servant Job, that there is none like him in the earth, a perfect and an upright man, one that feareth God, and escheweth evil?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 9, E'Then Satan answered the LORD, and said, Doth Job fear God for nought?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 10, E'Hast not thou made an hedge about him, and about his house, and about all that he hath on every side? thou hast blessed the work of his hands, and his substance is increased in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 11, E'But put forth thine hand now, and touch all that he hath, and he will curse thee to thy face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 12, E'And the LORD said unto Satan, Behold, all that he hath is in thy power; only upon himself put not forth thine hand. So Satan went forth from the presence of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 13, E'And there was a day when his sons and his daughters were eating and drinking wine in their eldest brother’s house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 14, E'And there came a messenger unto Job, and said, The oxen were plowing, and the asses feeding beside them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 15, E'And the Sabeans fell upon them, and took them away; yea, they have slain the servants with the edge of the sword; and I only am escaped alone to tell thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 16, E'While he was yet speaking, there came also another, and said, The fire of God is fallen from heaven, and hath burned up the sheep, and the servants, and consumed them; and I only am escaped alone to tell thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 17, E'While he was yet speaking, there came also another, and said, The Chaldeans made out three bands, and fell upon the camels, and have carried them away, yea, and slain the servants with the edge of the sword; and I only am escaped alone to tell thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 18, E'While he was yet speaking, there came also another, and said, Thy sons and thy daughters were eating and drinking wine in their eldest brother’s house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 19, E'And, behold, there came a great wind from the wilderness, and smote the four corners of the house, and it fell upon the young men, and they are dead; and I only am escaped alone to tell thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 20, E'Then Job arose, and rent his mantle, and shaved his head, and fell down upon the ground, and worshipped,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 21, E'And said, Naked came I out of my mother’s womb, and naked shall I return thither: the LORD gave, and the LORD hath taken away; blessed be the name of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 1, 22, E'In all this Job sinned not, nor charged God foolishly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 1, E'Again there was a day when the sons of God came to present themselves before the LORD, and Satan came also among them to present himself before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 2, E'And the LORD said unto Satan, From whence comest thou? And Satan answered the LORD, and said, From going to and fro in the earth, and from walking up and down in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 3, E'And the LORD said unto Satan, Hast thou considered my servant Job, that there is none like him in the earth, a perfect and an upright man, one that feareth God, and escheweth evil? and still he holdeth fast his integrity, although thou movedst me against him, to destroy him without cause.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 4, E'And Satan answered the LORD, and said, Skin for skin, yea, all that a man hath will he give for his life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 5, E'But put forth thine hand now, and touch his bone and his flesh, and he will curse thee to thy face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 6, E'And the LORD said unto Satan, Behold, he is in thine hand; but save his life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 7, E'So went Satan forth from the presence of the LORD, and smote Job with sore boils from the sole of his foot unto his crown.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 8, E'And he took him a potsherd to scrape himself withal; and he sat down among the ashes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 9, E'Then said his wife unto him, Dost thou still retain thine integrity? curse God, and die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 10, E'But he said unto her, Thou speakest as one of the foolish women speaketh. What? shall we receive good at the hand of God, and shall we not receive evil? In all this did not Job sin with his lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 11, E'Now when Job’s three friends heard of all this evil that was come upon him, they came every one from his own place; Eliphaz the Temanite, and Bildad the Shuhite, and Zophar the Naamathite: for they had made an appointment together to come to mourn with him and to comfort him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 12, E'And when they lifted up their eyes afar off, and knew him not, they lifted up their voice, and wept; and they rent every one his mantle, and sprinkled dust upon their heads toward heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 2, 13, E'So they sat down with him upon the ground seven days and seven nights, and none spake a word unto him: for they saw that his grief was very great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 1, E'After this opened Job his mouth, and cursed his day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 2, E'And Job spake, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 3, E'Let the day perish wherein I was born, and the night in which it was said, There is a man child conceived.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 4, E'Let that day be darkness; let not God regard it from above, neither let the light shine upon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 5, E'Let darkness and the shadow of death stain it; let a cloud dwell upon it; let the blackness of the day terrify it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 6, E'As for that night, let darkness seize upon it; let it not be joined unto the days of the year, let it not come into the number of the months.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 7, E'Lo, let that night be solitary, let no joyful voice come therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 8, E'Let them curse it that curse the day, who are ready to raise up their mourning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 9, E'Let the stars of the twilight thereof be dark; let it look for light, but have none; neither let it see the dawning of the day:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 10, E'Because it shut not up the doors of my mother’s womb, nor hid sorrow from mine eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 11, E'Why died I not from the womb? why did I not give up the ghost when I came out of the belly?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 12, E'Why did the knees prevent me? or why the breasts that I should suck?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 13, E'For now should I have lain still and been quiet, I should have slept: then had I been at rest,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 14, E'With kings and counsellors of the earth, which built desolate places for themselves;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 15, E'Or with princes that had gold, who filled their houses with silver:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 16, E'Or as an hidden untimely birth I had not been; as infants which never saw light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 17, E'There the wicked cease from troubling; and there the weary be at rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 18, E'There the prisoners rest together; they hear not the voice of the oppressor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 19, E'The small and great are there; and the servant is free from his master.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 20, E'Wherefore is light given to him that is in misery, and life unto the bitter in soul;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 21, E'Which long for death, but it cometh not; and dig for it more than for hid treasures;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 22, E'Which rejoice exceedingly, and are glad, when they can find the grave?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 23, E'Why is light given to a man whose way is hid, and whom God hath hedged in?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 24, E'For my sighing cometh before I eat, and my roarings are poured out like the waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 25, E'For the thing which I greatly feared is come upon me, and that which I was afraid of is come unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 3, 26, E'I was not in safety, neither had I rest, neither was I quiet; yet trouble came.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 1, E'Then Eliphaz the Temanite answered and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 2, E'If we assay to commune with thee, wilt thou be grieved? but who can withhold himself from speaking?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 3, E'Behold, thou hast instructed many, and thou hast strengthened the weak hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 4, E'Thy words have upholden him that was falling, and thou hast strengthened the feeble knees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 5, E'But now it is come upon thee, and thou faintest; it toucheth thee, and thou art troubled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 6, E'Is not this thy fear, thy confidence, thy hope, and the uprightness of thy ways?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 7, E'Remember, I pray thee, who ever perished, being innocent? or where were the righteous cut off?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 8, E'Even as I have seen, they that plow iniquity, and sow wickedness, reap the same.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 9, E'By the blast of God they perish, and by the breath of his nostrils are they consumed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 10, E'The roaring of the lion, and the voice of the fierce lion, and the teeth of the young lions, are broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 11, E'The old lion perisheth for lack of prey, and the stout lion’s whelps are scattered abroad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 12, E'Now a thing was secretly brought to me, and mine ear received a little thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 13, E'In thoughts from the visions of the night, when deep sleep falleth on men,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 14, E'Fear came upon me, and trembling, which made all my bones to shake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 15, E'Then a spirit passed before my face; the hair of my flesh stood up:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 16, E'It stood still, but I could not discern the form thereof: an image was before mine eyes, there was silence, and I heard a voice, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 17, E'Shall mortal man be more just than God? shall a man be more pure than his maker?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 18, E'Behold, he put no trust in his servants; and his angels he charged with folly:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 19, E'How much less in them that dwell in houses of clay, whose foundation is in the dust, which are crushed before the moth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 20, E'They are destroyed from morning to evening: they perish for ever without any regarding it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 4, 21, E'Doth not their excellency which is in them go away? they die, even without wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 1, E'Call now, if there be any that will answer thee; and to which of the saints wilt thou turn?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 2, E'For wrath killeth the foolish man, and envy slayeth the silly one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 3, E'I have seen the foolish taking root: but suddenly I cursed his habitation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 4, E'His children are far from safety, and they are crushed in the gate, neither is there any to deliver them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 5, E'Whose harvest the hungry eateth up, and taketh it even out of the thorns, and the robber swalloweth up their substance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 6, E'Although affliction cometh not forth of the dust, neither doth trouble spring out of the ground;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 7, E'Yet man is born unto trouble, as the sparks fly upward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 8, E'I would seek unto God, and unto God would I commit my cause:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 9, E'Which doeth great things and unsearchable; marvellous things without number:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 10, E'Who giveth rain upon the earth, and sendeth waters upon the fields:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 11, E'To set up on high those that be low; that those which mourn may be exalted to safety.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 12, E'He disappointeth the devices of the crafty, so that their hands cannot perform their enterprise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 13, E'He taketh the wise in their own craftiness: and the counsel of the froward is carried headlong.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 14, E'They meet with darkness in the day time, and grope in the noonday as in the night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 15, E'But he saveth the poor from the sword, from their mouth, and from the hand of the mighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 16, E'So the poor hath hope, and iniquity stoppeth her mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 17, E'Behold, happy is the man whom God correcteth: therefore despise not thou the chastening of the Almighty:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 18, E'For he maketh sore, and bindeth up: he woundeth, and his hands make whole.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 19, E'He shall deliver thee in six troubles: yea, in seven there shall no evil touch thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 20, E'In famine he shall redeem thee from death: and in war from the power of the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 21, E'Thou shalt be hid from the scourge of the tongue: neither shalt thou be afraid of destruction when it cometh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 22, E'At destruction and famine thou shalt laugh: neither shalt thou be afraid of the beasts of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 23, E'For thou shalt be in league with the stones of the field: and the beasts of the field shall be at peace with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 24, E'And thou shalt know that thy tabernacle shall be in peace; and thou shalt visit thy habitation, and shalt not sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 25, E'Thou shalt know also that thy seed shall be great, and thine offspring as the grass of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 26, E'Thou shalt come to thy grave in a full age, like as a shock of corn cometh in in his season.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 5, 27, E'Lo this, we have searched it, so it is; hear it, and know thou it for thy good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 1, E'But Job answered and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 2, E'Oh that my grief were throughly weighed, and my calamity laid in the balances together!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 3, E'For now it would be heavier than the sand of the sea: therefore my words are swallowed up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 4, E'For the arrows of the Almighty are within me, the poison whereof drinketh up my spirit: the terrors of God do set themselves in array against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 5, E'Doth the wild ass bray when he hath grass? or loweth the ox over his fodder?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 6, E'Can that which is unsavoury be eaten without salt? or is there any taste in the white of an egg?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 7, E'The things that my soul refused to touch are as my sorrowful meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 8, E'Oh that I might have my request; and that God would grant me the thing that I long for!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 9, E'Even that it would please God to destroy me; that he would let loose his hand, and cut me off!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 10, E'Then should I yet have comfort; yea, I would harden myself in sorrow: let him not spare; for I have not concealed the words of the Holy One.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 11, E'What is my strength, that I should hope? and what is mine end, that I should prolong my life?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 12, E'Is my strength the strength of stones? or is my flesh of brass?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 13, E'Is not my help in me? and is wisdom driven quite from me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 14, E'To him that is afflicted pity should be shewed from his friend; but he forsaketh the fear of the Almighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 15, E'My brethren have dealt deceitfully as a brook, and as the stream of brooks they pass away;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 16, E'Which are blackish by reason of the ice, and wherein the snow is hid:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 17, E'What time they wax warm, they vanish: when it is hot, they are consumed out of their place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 18, E'The paths of their way are turned aside; they go to nothing, and perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 19, E'The troops of Tema looked, the companies of Sheba waited for them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 20, E'They were confounded because they had hoped; they came thither, and were ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 21, E'For now ye are nothing; ye see my casting down, and are afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 22, E'Did I say, Bring unto me? or, Give a reward for me of your substance?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 23, E'Or, Deliver me from the enemy’s hand? or, Redeem me from the hand of the mighty?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 24, E'Teach me, and I will hold my tongue: and cause me to understand wherein I have erred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 25, E'How forcible are right words! but what doth your arguing reprove?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 26, E'Do ye imagine to reprove words, and the speeches of one that is desperate, which are as wind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 27, E'Yea, ye overwhelm the fatherless, and ye dig a pit for your friend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 28, E'Now therefore be content, look upon me; for it is evident unto you if I lie.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 29, E'Return, I pray you, let it not be iniquity; yea, return again, my righteousness is in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 6, 30, E'Is there iniquity in my tongue? cannot my taste discern perverse things?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 1, E'Is there not an appointed time to man upon earth? are not his days also like the days of an hireling?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 2, E'As a servant earnestly desireth the shadow, and as an hireling looketh for the reward of his work:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 3, E'So am I made to possess months of vanity, and wearisome nights are appointed to me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 4, E'When I lie down, I say, When shall I arise, and the night be gone? and I am full of tossings to and fro unto the dawning of the day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 5, E'My flesh is clothed with worms and clods of dust; my skin is broken, and become loathsome.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 6, E'My days are swifter than a weaver’s shuttle, and are spent without hope.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 7, E'O remember that my life is wind: mine eye shall no more see good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 8, E'The eye of him that hath seen me shall see me no more: thine eyes are upon me, and I am not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 9, E'As the cloud is consumed and vanisheth away: so he that goeth down to the grave shall come up no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 10, E'He shall return no more to his house, neither shall his place know him any more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 11, E'Therefore I will not refrain my mouth; I will speak in the anguish of my spirit; I will complain in the bitterness of my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 12, E'Am I a sea, or a whale, that thou settest a watch over me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 13, E'When I say, My bed shall comfort me, my couch shall ease my complaint;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 14, E'Then thou scarest me with dreams, and terrifiest me through visions:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 15, E'So that my soul chooseth strangling, and death rather than my life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 16, E'I loathe it; I would not live alway: let me alone; for my days are vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 17, E'What is man, that thou shouldest magnify him? and that thou shouldest set thine heart upon him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 18, E'And that thou shouldest visit him every morning, and try him every moment?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 19, E'How long wilt thou not depart from me, nor let me alone till I swallow down my spittle?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 20, E'I have sinned; what shall I do unto thee, O thou preserver of men? why hast thou set me as a mark against thee, so that I am a burden to myself?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 7, 21, E'And why dost thou not pardon my transgression, and take away mine iniquity? for now shall I sleep in the dust; and thou shalt seek me in the morning, but I shall not be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 1, E'Then answered Bildad the Shuhite, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 2, E'How long wilt thou speak these things? and how long shall the words of thy mouth be like a strong wind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 3, E'Doth God pervert judgment? or doth the Almighty pervert justice?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 4, E'If thy children have sinned against him, and he have cast them away for their transgression;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 5, E'If thou wouldest seek unto God betimes, and make thy supplication to the Almighty;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 6, E'If thou wert pure and upright; surely now he would awake for thee, and make the habitation of thy righteousness prosperous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 7, E'Though thy beginning was small, yet thy latter end should greatly increase.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 8, E'For enquire, I pray thee, of the former age, and prepare thyself to the search of their fathers:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 9, E'(For we are but of yesterday, and know nothing, because our days upon earth are a shadow:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 10, E'Shall not they teach thee, and tell thee, and utter words out of their heart?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 11, E'Can the rush grow up without mire? can the flag grow without water?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 12, E'Whilst it is yet in his greenness, and not cut down, it withereth before any other herb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 13, E'So are the paths of all that forget God; and the hypocrite’s hope shall perish:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 14, E'Whose hope shall be cut off, and whose trust shall be a spider’s web.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 15, E'He shall lean upon his house, but it shall not stand: he shall hold it fast, but it shall not endure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 16, E'He is green before the sun, and his branch shooteth forth in his garden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 17, E'His roots are wrapped about the heap, and seeth the place of stones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 18, E'If he destroy him from his place, then it shall deny him, saying, I have not seen thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 19, E'Behold, this is the joy of his way, and out of the earth shall others grow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 20, E'Behold, God will not cast away a perfect man, neither will he help the evil doers:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 21, E'Till he fill thy mouth with laughing, and thy lips with rejoicing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 8, 22, E'They that hate thee shall be clothed with shame; and the dwelling place of the wicked shall come to nought.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 1, E'Then Job answered and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 2, E'I know it is so of a truth: but how should man be just with God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 3, E'If he will contend with him, he cannot answer him one of a thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 4, E'He is wise in heart, and mighty in strength: who hath hardened himself against him, and hath prospered?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 5, E'Which removeth the mountains, and they know not: which overturneth them in his anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 6, E'Which shaketh the earth out of her place, and the pillars thereof tremble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 7, E'Which commandeth the sun, and it riseth not; and sealeth up the stars.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 8, E'Which alone spreadeth out the heavens, and treadeth upon the waves of the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 9, E'Which maketh Arcturus, Orion, and Pleiades, and the chambers of the south.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 10, E'Which doeth great things past finding out; yea, and wonders without number.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 11, E'Lo, he goeth by me, and I see him not: he passeth on also, but I perceive him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 12, E'Behold, he taketh away, who can hinder him? who will say unto him, What doest thou?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 13, E'If God will not withdraw his anger, the proud helpers do stoop under him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 14, E'How much less shall I answer him, and choose out my words to reason with him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 15, E'Whom, though I were righteous, yet would I not answer, but I would make supplication to my judge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 16, E'If I had called, and he had answered me; yet would I not believe that he had hearkened unto my voice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 17, E'For he breaketh me with a tempest, and multiplieth my wounds without cause.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 18, E'He will not suffer me to take my breath, but filleth me with bitterness.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 19, E'If I speak of strength, lo, he is strong: and if of judgment, who shall set me a time to plead?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 20, E'If I justify myself, mine own mouth shall condemn me: if I say, I am perfect, it shall also prove me perverse.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 21, E'Though I were perfect, yet would I not know my soul: I would despise my life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 22, E'This is one thing, therefore I said it, He destroyeth the perfect and the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 23, E'If the scourge slay suddenly, he will laugh at the trial of the innocent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 24, E'The earth is given into the hand of the wicked: he covereth the faces of the judges thereof; if not, where, and who is he?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 25, E'Now my days are swifter than a post: they flee away, they see no good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 26, E'They are passed away as the swift ships: as the eagle that hasteth to the prey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 27, E'If I say, I will forget my complaint, I will leave off my heaviness, and comfort myself:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 28, E'I am afraid of all my sorrows, I know that thou wilt not hold me innocent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 29, E'If I be wicked, why then labour I in vain?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 30, E'If I wash myself with snow water, and make my hands never so clean;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 31, E'Yet shalt thou plunge me in the ditch, and mine own clothes shall abhor me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 32, E'For he is not a man, as I am, that I should answer him, and we should come together in judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 33, E'Neither is there any daysman betwixt us, that might lay his hand upon us both.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 34, E'Let him take his rod away from me, and let not his fear terrify me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 9, 35, E'Then would I speak, and not fear him; but it is not so with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 1, E'My soul is weary of my life; I will leave my complaint upon myself; I will speak in the bitterness of my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 2, E'I will say unto God, Do not condemn me; shew me wherefore thou contendest with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 3, E'Is it good unto thee that thou shouldest oppress, that thou shouldest despise the work of thine hands, and shine upon the counsel of the wicked?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 4, E'Hast thou eyes of flesh? or seest thou as man seeth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 5, E'Are thy days as the days of man? are thy years as man’s days,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 6, E'That thou enquirest after mine iniquity, and searchest after my sin?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 7, E'Thou knowest that I am not wicked; and there is none that can deliver out of thine hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 8, E'Thine hands have made me and fashioned me together round about; yet thou dost destroy me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 9, E'Remember, I beseech thee, that thou hast made me as the clay; and wilt thou bring me into dust again?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 10, E'Hast thou not poured me out as milk, and curdled me like cheese?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 11, E'Thou hast clothed me with skin and flesh, and hast fenced me with bones and sinews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 12, E'Thou hast granted me life and favour, and thy visitation hath preserved my spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 13, E'And these things hast thou hid in thine heart: I know that this is with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 14, E'If I sin, then thou markest me, and thou wilt not acquit me from mine iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 15, E'If I be wicked, woe unto me; and if I be righteous, yet will I not lift up my head. I am full of confusion; therefore see thou mine affliction;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 16, E'For it increaseth. Thou huntest me as a fierce lion: and again thou shewest thyself marvellous upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 17, E'Thou renewest thy witnesses against me, and increasest thine indignation upon me; changes and war are against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 18, E'Wherefore then hast thou brought me forth out of the womb? Oh that I had given up the ghost, and no eye had seen me!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 19, E'I should have been as though I had not been; I should have been carried from the womb to the grave.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 20, E'Are not my days few? cease then, and let me alone, that I may take comfort a little,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 21, E'Before I go whence I shall not return, even to the land of darkness and the shadow of death;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 10, 22, E'A land of darkness, as darkness itself; and of the shadow of death, without any order, and where the light is as darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 1, E'Then answered Zophar the Naamathite, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 2, E'Should not the multitude of words be answered? and should a man full of talk be justified?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 3, E'Should thy lies make men hold their peace? and when thou mockest, shall no man make thee ashamed?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 4, E'For thou hast said, My doctrine is pure, and I am clean in thine eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 5, E'But oh that God would speak, and open his lips against thee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 6, E'And that he would shew thee the secrets of wisdom, that they are double to that which is! Know therefore that God exacteth of thee less than thine iniquity deserveth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 7, E'Canst thou by searching find out God? canst thou find out the Almighty unto perfection?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 8, E'It is as high as heaven; what canst thou do? deeper than hell; what canst thou know?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 9, E'The measure thereof is longer than the earth, and broader than the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 10, E'If he cut off, and shut up, or gather together, then who can hinder him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 11, E'For he knoweth vain men: he seeth wickedness also; will he not then consider it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 12, E'For vain man would be wise, though man be born like a wild ass’s colt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 13, E'If thou prepare thine heart, and stretch out thine hands toward him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 14, E'If iniquity be in thine hand, put it far away, and let not wickedness dwell in thy tabernacles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 15, E'For then shalt thou lift up thy face without spot; yea, thou shalt be stedfast, and shalt not fear:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 16, E'Because thou shalt forget thy misery, and remember it as waters that pass away:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 17, E'And thine age shall be clearer than the noonday: thou shalt shine forth, thou shalt be as the morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 18, E'And thou shalt be secure, because there is hope; yea, thou shalt dig about thee, and thou shalt take thy rest in safety.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 19, E'Also thou shalt lie down, and none shall make thee afraid; yea, many shall make suit unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 11, 20, E'But the eyes of the wicked shall fail, and they shall not escape, and their hope shall be as the giving up of the ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 1, E'And Job answered and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 2, E'No doubt but ye are the people, and wisdom shall die with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 3, E'But I have understanding as well as you; I am not inferior to you: yea, who knoweth not such things as these?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 4, E'I am as one mocked of his neighbour, who calleth upon God, and he answereth him: the just upright man is laughed to scorn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 5, E'He that is ready to slip with his feet is as a lamp despised in the thought of him that is at ease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 6, E'The tabernacles of robbers prosper, and they that provoke God are secure; into whose hand God bringeth abundantly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 7, E'But ask now the beasts, and they shall teach thee; and the fowls of the air, and they shall tell thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 8, E'Or speak to the earth, and it shall teach thee: and the fishes of the sea shall declare unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 9, E'Who knoweth not in all these that the hand of the LORD hath wrought this?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 10, E'In whose hand is the soul of every living thing, and the breath of all mankind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 11, E'Doth not the ear try words? and the mouth taste his meat?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 12, E'With the ancient is wisdom; and in length of days understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 13, E'With him is wisdom and strength, he hath counsel and understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 14, E'Behold, he breaketh down, and it cannot be built again: he shutteth up a man, and there can be no opening.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 15, E'Behold, he withholdeth the waters, and they dry up: also he sendeth them out, and they overturn the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 16, E'With him is strength and wisdom: the deceived and the deceiver are his.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 17, E'He leadeth counsellors away spoiled, and maketh the judges fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 18, E'He looseth the bond of kings, and girdeth their loins with a girdle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 19, E'He leadeth princes away spoiled, and overthroweth the mighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 20, E'He removeth away the speech of the trusty, and taketh away the understanding of the aged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 21, E'He poureth contempt upon princes, and weakeneth the strength of the mighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 22, E'He discovereth deep things out of darkness, and bringeth out to light the shadow of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 23, E'He increaseth the nations, and destroyeth them: he enlargeth the nations, and straiteneth them again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 24, E'He taketh away the heart of the chief of the people of the earth, and causeth them to wander in a wilderness where there is no way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 12, 25, E'They grope in the dark without light, and he maketh them to stagger like a drunken man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 1, E'Lo, mine eye hath seen all this, mine ear hath heard and understood it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 2, E'What ye know, the same do I know also: I am not inferior unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 3, E'Surely I would speak to the Almighty, and I desire to reason with God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 4, E'But ye are forgers of lies, ye are all physicians of no value.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 5, E'O that ye would altogether hold your peace! and it should be your wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 6, E'Hear now my reasoning, and hearken to the pleadings of my lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 7, E'Will ye speak wickedly for God? and talk deceitfully for him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 8, E'Will ye accept his person? will ye contend for God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 9, E'Is it good that he should search you out? or as one man mocketh another, do ye so mock him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 10, E'He will surely reprove you, if ye do secretly accept persons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 11, E'Shall not his excellency make you afraid? and his dread fall upon you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 12, E'Your remembrances are like unto ashes, your bodies to bodies of clay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 13, E'Hold your peace, let me alone, that I may speak, and let come on me what will.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 14, E'Wherefore do I take my flesh in my teeth, and put my life in mine hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 15, E'Though he slay me, yet will I trust in him: but I will maintain mine own ways before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 16, E'He also shall be my salvation: for an hypocrite shall not come before him.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 17, E'Hear diligently my speech, and my declaration with your ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 18, E'Behold now, I have ordered my cause; I know that I shall be justified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 19, E'Who is he that will plead with me? for now, if I hold my tongue, I shall give up the ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 20, E'Only do not two things unto me: then will I not hide myself from thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 21, E'Withdraw thine hand far from me: and let not thy dread make me afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 22, E'Then call thou, and I will answer: or let me speak, and answer thou me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 23, E'How many are mine iniquities and sins? make me to know my transgression and my sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 24, E'Wherefore hidest thou thy face, and holdest me for thine enemy?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 25, E'Wilt thou break a leaf driven to and fro? and wilt thou pursue the dry stubble?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 26, E'For thou writest bitter things against me, and makest me to possess the iniquities of my youth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 27, E'Thou puttest my feet also in the stocks, and lookest narrowly unto all my paths; thou settest a print upon the heels of my feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 13, 28, E'And he, as a rotten thing, consumeth, as a garment that is moth eaten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 1, E'Man that is born of a woman is of few days, and full of trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 2, E'He cometh forth like a flower, and is cut down: he fleeth also as a shadow, and continueth not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 3, E'And dost thou open thine eyes upon such an one, and bringest me into judgment with thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 4, E'Who can bring a clean thing out of an unclean? not one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 5, E'Seeing his days are determined, the number of his months are with thee, thou hast appointed his bounds that he cannot pass;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 6, E'Turn from him, that he may rest, till he shall accomplish, as an hireling, his day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 7, E'For there is hope of a tree, if it be cut down, that it will sprout again, and that the tender branch thereof will not cease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 8, E'Though the root thereof wax old in the earth, and the stock thereof die in the ground;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 9, E'Yet through the scent of water it will bud, and bring forth boughs like a plant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 10, E'But man dieth, and wasteth away: yea, man giveth up the ghost, and where is he?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 11, E'As the waters fail from the sea, and the flood decayeth and drieth up:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 12, E'So man lieth down, and riseth not: till the heavens be no more, they shall not awake, nor be raised out of their sleep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 13, E'O that thou wouldest hide me in the grave, that thou wouldest keep me secret, until thy wrath be past, that thou wouldest appoint me a set time, and remember me!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 14, E'If a man die, shall he live again? all the days of my appointed time will I wait, till my change come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 15, E'Thou shalt call, and I will answer thee: thou wilt have a desire to the work of thine hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 16, E'For now thou numberest my steps: dost thou not watch over my sin?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 17, E'My transgression is sealed up in a bag, and thou sewest up mine iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 18, E'And surely the mountain falling cometh to nought, and the rock is removed out of his place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 19, E'The waters wear the stones: thou washest away the things which grow out of the dust of the earth; and thou destroyest the hope of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 20, E'Thou prevailest for ever against him, and he passeth: thou changest his countenance, and sendest him away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 21, E'His sons come to honour, and he knoweth it not; and they are brought low, but he perceiveth it not of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 14, 22, E'But his flesh upon him shall have pain, and his soul within him shall mourn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 1, E'Then answered Eliphaz the Temanite, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 2, E'Should a wise man utter vain knowledge, and fill his belly with the east wind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 3, E'Should he reason with unprofitable talk? or with speeches wherewith he can do no good?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 4, E'Yea, thou castest off fear, and restrainest prayer before God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 5, E'For thy mouth uttereth thine iniquity, and thou choosest the tongue of the crafty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 6, E'Thine own mouth condemneth thee, and not I: yea, thine own lips testify against thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 7, E'Art thou the first man that was born? or wast thou made before the hills?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 8, E'Hast thou heard the secret of God? and dost thou restrain wisdom to thyself?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 9, E'What knowest thou, that we know not? what understandest thou, which is not in us?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 10, E'With us are both the grayheaded and very aged men, much elder than thy father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 11, E'Are the consolations of God small with thee? is there any secret thing with thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 12, E'Why doth thine heart carry thee away? and what do thy eyes wink at,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 13, E'That thou turnest thy spirit against God, and lettest such words go out of thy mouth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 14, E'What is man, that he should be clean? and he which is born of a woman, that he should be righteous?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 15, E'Behold, he putteth no trust in his saints; yea, the heavens are not clean in his sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 16, E'How much more abominable and filthy is man, which drinketh iniquity like water?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 17, E'I will shew thee, hear me; and that which I have seen I will declare;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 18, E'Which wise men have told from their fathers, and have not hid it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 19, E'Unto whom alone the earth was given, and no stranger passed among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 20, E'The wicked man travaileth with pain all his days, and the number of years is hidden to the oppressor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 21, E'A dreadful sound is in his ears: in prosperity the destroyer shall come upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 22, E'He believeth not that he shall return out of darkness, and he is waited for of the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 23, E'He wandereth abroad for bread, saying, Where is it? he knoweth that the day of darkness is ready at his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 24, E'Trouble and anguish shall make him afraid; they shall prevail against him, as a king ready to the battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 25, E'For he stretcheth out his hand against God, and strengtheneth himself against the Almighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 26, E'He runneth upon him, even on his neck, upon the thick bosses of his bucklers:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 27, E'Because he covereth his face with his fatness, and maketh collops of fat on his flanks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 28, E'And he dwelleth in desolate cities, and in houses which no man inhabiteth, which are ready to become heaps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 29, E'He shall not be rich, neither shall his substance continue, neither shall he prolong the perfection thereof upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 30, E'He shall not depart out of darkness; the flame shall dry up his branches, and by the breath of his mouth shall he go away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 31, E'Let not him that is deceived trust in vanity: for vanity shall be his recompence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 32, E'It shall be accomplished before his time, and his branch shall not be green.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 33, E'He shall shake off his unripe grape as the vine, and shall cast off his flower as the olive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 34, E'For the congregation of hypocrites shall be desolate, and fire shall consume the tabernacles of bribery.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 15, 35, E'They conceive mischief, and bring forth vanity, and their belly prepareth deceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 1, E'Then Job answered and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 2, E'I have heard many such things: miserable comforters are ye all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 3, E'Shall vain words have an end? or what emboldeneth thee that thou answerest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 4, E'I also could speak as ye do: if your soul were in my soul’s stead, I could heap up words against you, and shake mine head at you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 5, E'But I would strengthen you with my mouth, and the moving of my lips should asswage your grief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 6, E'Though I speak, my grief is not asswaged: and though I forbear, what am I eased?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 7, E'But now he hath made me weary: thou hast made desolate all my company.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 8, E'And thou hast filled me with wrinkles, which is a witness against me: and my leanness rising up in me beareth witness to my face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 9, E'He teareth me in his wrath, who hateth me: he gnasheth upon me with his teeth; mine enemy sharpeneth his eyes upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 10, E'They have gaped upon me with their mouth; they have smitten me upon the cheek reproachfully; they have gathered themselves together against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 11, E'God hath delivered me to the ungodly, and turned me over into the hands of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 12, E'I was at ease, but he hath broken me asunder: he hath also taken me by my neck, and shaken me to pieces, and set me up for his mark.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 13, E'His archers compass me round about, he cleaveth my reins asunder, and doth not spare; he poureth out my gall upon the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 14, E'He breaketh me with breach upon breach, he runneth upon me like a giant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 15, E'I have sewed sackcloth upon my skin, and defiled my horn in the dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 16, E'My face is foul with weeping, and on my eyelids is the shadow of death;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 17, E'Not for any injustice in mine hands: also my prayer is pure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 18, E'O earth, cover not thou my blood, and let my cry have no place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 19, E'Also now, behold, my witness is in heaven, and my record is on high.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 20, E'My friends scorn me: but mine eye poureth out tears unto God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 21, E'O that one might plead for a man with God, as a man pleadeth for his neighbour!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 16, 22, E'When a few years are come, then I shall go the way whence I shall not return.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 1, E'My breath is corrupt, my days are extinct, the graves are ready for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 2, E'Are there not mockers with me? and doth not mine eye continue in their provocation?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 3, E'Lay down now, put me in a surety with thee; who is he that will strike hands with me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 4, E'For thou hast hid their heart from understanding: therefore shalt thou not exalt them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 5, E'He that speaketh flattery to his friends, even the eyes of his children shall fail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 6, E'He hath made me also a byword of the people; and aforetime I was as a tabret.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 7, E'Mine eye also is dim by reason of sorrow, and all my members are as a shadow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 8, E'Upright men shall be astonied at this, and the innocent shall stir up himself against the hypocrite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 9, E'The righteous also shall hold on his way, and he that hath clean hands shall be stronger and stronger.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 10, E'But as for you all, do ye return, and come now: for I cannot find one wise man among you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 11, E'My days are past, my purposes are broken off, even the thoughts of my heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 12, E'They change the night into day: the light is short because of darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 13, E'If I wait, the grave is mine house: I have made my bed in the darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 14, E'I have said to corruption, Thou art my father: to the worm, Thou art my mother, and my sister.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 15, E'And where is now my hope? as for my hope, who shall see it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 17, 16, E'They shall go down to the bars of the pit, when our rest together is in the dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 1, E'Then answered Bildad the Shuhite, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 2, E'How long will it be ere ye make an end of words? mark, and afterwards we will speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 3, E'Wherefore are we counted as beasts, and reputed vile in your sight?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 4, E'He teareth himself in his anger: shall the earth be forsaken for thee? and shall the rock be removed out of his place?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 5, E'Yea, the light of the wicked shall be put out, and the spark of his fire shall not shine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 6, E'The light shall be dark in his tabernacle, and his candle shall be put out with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 7, E'The steps of his strength shall be straitened, and his own counsel shall cast him down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 8, E'For he is cast into a net by his own feet, and he walketh upon a snare.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 9, E'The gin shall take him by the heel, and the robber shall prevail against him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 10, E'The snare is laid for him in the ground, and a trap for him in the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 11, E'Terrors shall make him afraid on every side, and shall drive him to his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 12, E'His strength shall be hungerbitten, and destruction shall be ready at his side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 13, E'It shall devour the strength of his skin: even the firstborn of death shall devour his strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 14, E'His confidence shall be rooted out of his tabernacle, and it shall bring him to the king of terrors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 15, E'It shall dwell in his tabernacle, because it is none of his: brimstone shall be scattered upon his habitation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 16, E'His roots shall be dried up beneath, and above shall his branch be cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 17, E'His remembrance shall perish from the earth, and he shall have no name in the street.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 18, E'He shall be driven from light into darkness, and chased out of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 19, E'He shall neither have son nor nephew among his people, nor any remaining in his dwellings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 20, E'They that come after him shall be astonied at his day, as they that went before were affrighted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 18, 21, E'Surely such are the dwellings of the wicked, and this is the place of him that knoweth not God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 1, E'Then Job answered and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 2, E'How long will ye vex my soul, and break me in pieces with words?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 3, E'These ten times have ye reproached me: ye are not ashamed that ye make yourselves strange to me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 4, E'And be it indeed that I have erred, mine error remaineth with myself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 5, E'If indeed ye will magnify yourselves against me, and plead against me my reproach:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 6, E'Know now that God hath overthrown me, and hath compassed me with his net.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 7, E'Behold, I cry out of wrong, but I am not heard: I cry aloud, but there is no judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 8, E'He hath fenced up my way that I cannot pass, and he hath set darkness in my paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 9, E'He hath stripped me of my glory, and taken the crown from my head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 10, E'He hath destroyed me on every side, and I am gone: and mine hope hath he removed like a tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 11, E'He hath also kindled his wrath against me, and he counteth me unto him as one of his enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 12, E'His troops come together, and raise up their way against me, and encamp round about my tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 13, E'He hath put my brethren far from me, and mine acquaintance are verily estranged from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 14, E'My kinsfolk have failed, and my familiar friends have forgotten me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 15, E'They that dwell in mine house, and my maids, count me for a stranger: I am an alien in their sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 16, E'I called my servant, and he gave me no answer; I intreated him with my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 17, E'My breath is strange to my wife, though I intreated for the children’s sake of mine own body.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 18, E'Yea, young children despised me; I arose, and they spake against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 19, E'All my inward friends abhorred me: and they whom I loved are turned against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 20, E'My bone cleaveth to my skin and to my flesh, and I am escaped with the skin of my teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 21, E'Have pity upon me, have pity upon me, O ye my friends; for the hand of God hath touched me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 22, E'Why do ye persecute me as God, and are not satisfied with my flesh?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 23, E'Oh that my words were now written! oh that they were printed in a book!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 24, E'That they were graven with an iron pen and lead in the rock for ever!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 25, E'For I know that my redeemer liveth, and that he shall stand at the latter day upon the earth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 26, E'And though after my skin worms destroy this body, yet in my flesh shall I see God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 27, E'Whom I shall see for myself, and mine eyes shall behold, and not another; though my reins be consumed within me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 28, E'But ye should say, Why persecute we him, seeing the root of the matter is found in me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 19, 29, E'Be ye afraid of the sword: for wrath bringeth the punishments of the sword, that ye may know there is a judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 1, E'Then answered Zophar the Naamathite, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 2, E'Therefore do my thoughts cause me to answer, and for this I make haste.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 3, E'I have heard the check of my reproach, and the spirit of my understanding causeth me to answer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 4, E'Knowest thou not this of old, since man was placed upon earth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 5, E'That the triumphing of the wicked is short, and the joy of the hypocrite but for a moment?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 6, E'Though his excellency mount up to the heavens, and his head reach unto the clouds;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 7, E'Yet he shall perish for ever like his own dung: they which have seen him shall say, Where is he?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 8, E'He shall fly away as a dream, and shall not be found: yea, he shall be chased away as a vision of the night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 9, E'The eye also which saw him shall see him no more; neither shall his place any more behold him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 10, E'His children shall seek to please the poor, and his hands shall restore their goods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 11, E'His bones are full of the sin of his youth, which shall lie down with him in the dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 12, E'Though wickedness be sweet in his mouth, though he hide it under his tongue;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 13, E'Though he spare it, and forsake it not; but keep it still within his mouth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 14, E'Yet his meat in his bowels is turned, it is the gall of asps within him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 15, E'He hath swallowed down riches, and he shall vomit them up again: God shall cast them out of his belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 16, E'He shall suck the poison of asps: the viper’s tongue shall slay him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 17, E'He shall not see the rivers, the floods, the brooks of honey and butter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 18, E'That which he laboured for shall he restore, and shall not swallow it down: according to his substance shall the restitution be, and he shall not rejoice therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 19, E'Because he hath oppressed and hath forsaken the poor; because he hath violently taken away an house which he builded not;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 20, E'Surely he shall not feel quietness in his belly, he shall not save of that which he desired.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 21, E'There shall none of his meat be left; therefore shall no man look for his goods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 22, E'In the fulness of his sufficiency he shall be in straits: every hand of the wicked shall come upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 23, E'When he is about to fill his belly, God shall cast the fury of his wrath upon him, and shall rain it upon him while he is eating.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 24, E'He shall flee from the iron weapon, and the bow of steel shall strike him through.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 25, E'It is drawn, and cometh out of the body; yea, the glittering sword cometh out of his gall: terrors are upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 26, E'All darkness shall be hid in his secret places: a fire not blown shall consume him; it shall go ill with him that is left in his tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 27, E'The heaven shall reveal his iniquity; and the earth shall rise up against him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 28, E'The increase of his house shall depart, and his goods shall flow away in the day of his wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 20, 29, E'This is the portion of a wicked man from God, and the heritage appointed unto him by God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 1, E'But Job answered and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 2, E'Hear diligently my speech, and let this be your consolations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 3, E'Suffer me that I may speak; and after that I have spoken, mock on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 4, E'As for me, is my complaint to man? and if it were so, why should not my spirit be troubled?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 5, E'Mark me, and be astonished, and lay your hand upon your mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 6, E'Even when I remember I am afraid, and trembling taketh hold on my flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 7, E'Wherefore do the wicked live, become old, yea, are mighty in power?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 8, E'Their seed is established in their sight with them, and their offspring before their eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 9, E'Their houses are safe from fear, neither is the rod of God upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 10, E'Their bull gendereth, and faileth not; their cow calveth, and casteth not her calf.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 11, E'They send forth their little ones like a flock, and their children dance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 12, E'They take the timbrel and harp, and rejoice at the sound of the organ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 13, E'They spend their days in wealth, and in a moment go down to the grave.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 14, E'Therefore they say unto God, Depart from us; for we desire not the knowledge of thy ways.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 15, E'What is the Almighty, that we should serve him? and what profit should we have, if we pray unto him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 16, E'Lo, their good is not in their hand: the counsel of the wicked is far from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 17, E'How oft is the candle of the wicked put out! and how oft cometh their destruction upon them! God distributeth sorrows in his anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 18, E'They are as stubble before the wind, and as chaff that the storm carrieth away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 19, E'God layeth up his iniquity for his children: he rewardeth him, and he shall know it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 20, E'His eyes shall see his destruction, and he shall drink of the wrath of the Almighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 21, E'For what pleasure hath he in his house after him, when the number of his months is cut off in the midst?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 22, E'Shall any teach God knowledge? seeing he judgeth those that are high.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 23, E'One dieth in his full strength, being wholly at ease and quiet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 24, E'His breasts are full of milk, and his bones are moistened with marrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 25, E'And another dieth in the bitterness of his soul, and never eateth with pleasure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 26, E'They shall lie down alike in the dust, and the worms shall cover them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 27, E'Behold, I know your thoughts, and the devices which ye wrongfully imagine against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 28, E'For ye say, Where is the house of the prince? and where are the dwelling places of the wicked?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 29, E'Have ye not asked them that go by the way? and do ye not know their tokens,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 30, E'That the wicked is reserved to the day of destruction? they shall be brought forth to the day of wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 31, E'Who shall declare his way to his face? and who shall repay him what he hath done?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 32, E'Yet shall he be brought to the grave, and shall remain in the tomb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 33, E'The clods of the valley shall be sweet unto him, and every man shall draw after him, as there are innumerable before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 21, 34, E'How then comfort ye me in vain, seeing in your answers there remaineth falsehood?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 1, E'Then Eliphaz the Temanite answered and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 2, E'Can a man be profitable unto God, as he that is wise may be profitable unto himself?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 3, E'Is it any pleasure to the Almighty, that thou art righteous? or is it gain to him, that thou makest thy ways perfect?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 4, E'Will he reprove thee for fear of thee? will he enter with thee into judgment?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 5, E'Is not thy wickedness great? and thine iniquities infinite?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 6, E'For thou hast taken a pledge from thy brother for nought, and stripped the naked of their clothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 7, E'Thou hast not given water to the weary to drink, and thou hast withholden bread from the hungry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 8, E'But as for the mighty man, he had the earth; and the honourable man dwelt in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 9, E'Thou hast sent widows away empty, and the arms of the fatherless have been broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 10, E'Therefore snares are round about thee, and sudden fear troubleth thee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 11, E'Or darkness, that thou canst not see; and abundance of waters cover thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 12, E'Is not God in the height of heaven? and behold the height of the stars, how high they are!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 13, E'And thou sayest, How doth God know? can he judge through the dark cloud?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 14, E'Thick clouds are a covering to him, that he seeth not; and he walketh in the circuit of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 15, E'Hast thou marked the old way which wicked men have trodden?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 16, E'Which were cut down out of time, whose foundation was overflown with a flood:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 17, E'Which said unto God, Depart from us: and what can the Almighty do for them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 18, E'Yet he filled their houses with good things: but the counsel of the wicked is far from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 19, E'The righteous see it, and are glad: and the innocent laugh them to scorn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 20, E'Whereas our substance is not cut down, but the remnant of them the fire consumeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 21, E'Acquaint now thyself with him, and be at peace: thereby good shall come unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 22, E'Receive, I pray thee, the law from his mouth, and lay up his words in thine heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 23, E'If thou return to the Almighty, thou shalt be built up, thou shalt put away iniquity far from thy tabernacles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 24, E'Then shalt thou lay up gold as dust, and the gold of Ophir as the stones of the brooks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 25, E'Yea, the Almighty shall be thy defence, and thou shalt have plenty of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 26, E'For then shalt thou have thy delight in the Almighty, and shalt lift up thy face unto God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 27, E'Thou shalt make thy prayer unto him, and he shall hear thee, and thou shalt pay thy vows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 28, E'Thou shalt also decree a thing, and it shall be established unto thee: and the light shall shine upon thy ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 29, E'When men are cast down, then thou shalt say, There is lifting up; and he shall save the humble person.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 22, 30, E'He shall deliver the island of the innocent: and it is delivered by the pureness of thine hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 1, E'Then Job answered and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 2, E'Even to day is my complaint bitter: my stroke is heavier than my groaning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 3, E'Oh that I knew where I might find him! that I might come even to his seat!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 4, E'I would order my cause before him, and fill my mouth with arguments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 5, E'I would know the words which he would answer me, and understand what he would say unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 6, E'Will he plead against me with his great power? No; but he would put strength in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 7, E'There the righteous might dispute with him; so should I be delivered for ever from my judge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 8, E'Behold, I go forward, but he is not there; and backward, but I cannot perceive him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 9, E'On the left hand, where he doth work, but I cannot behold him: he hideth himself on the right hand, that I cannot see him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 10, E'But he knoweth the way that I take: when he hath tried me, I shall come forth as gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 11, E'My foot hath held his steps, his way have I kept, and not declined.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 12, E'Neither have I gone back from the commandment of his lips; I have esteemed the words of his mouth more than my necessary food.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 13, E'But he is in one mind, and who can turn him? and what his soul desireth, even that he doeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 14, E'For he performeth the thing that is appointed for me: and many such things are with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 15, E'Therefore am I troubled at his presence: when I consider, I am afraid of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 16, E'For God maketh my heart soft, and the Almighty troubleth me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 23, 17, E'Because I was not cut off before the darkness, neither hath he covered the darkness from my face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 1, E'Why, seeing times are not hidden from the Almighty, do they that know him not see his days?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 2, E'Some remove the landmarks; they violently take away flocks, and feed thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 3, E'They drive away the ass of the fatherless, they take the widow’s ox for a pledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 4, E'They turn the needy out of the way: the poor of the earth hide themselves together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 5, E'Behold, as wild asses in the desert, go they forth to their work; rising betimes for a prey: the wilderness yieldeth food for them and for their children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 6, E'They reap every one his corn in the field: and they gather the vintage of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 7, E'They cause the naked to lodge without clothing, that they have no covering in the cold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 8, E'They are wet with the showers of the mountains, and embrace the rock for want of a shelter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 9, E'They pluck the fatherless from the breast, and take a pledge of the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 10, E'They cause him to go naked without clothing, and they take away the sheaf from the hungry;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 11, E'Which make oil within their walls, and tread their winepresses, and suffer thirst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 12, E'Men groan from out of the city, and the soul of the wounded crieth out: yet God layeth not folly to them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 13, E'They are of those that rebel against the light; they know not the ways thereof, nor abide in the paths thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 14, E'The murderer rising with the light killeth the poor and needy, and in the night is as a thief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 15, E'The eye also of the adulterer waiteth for the twilight, saying, No eye shall see me: and disguiseth his face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 16, E'In the dark they dig through houses, which they had marked for themselves in the daytime: they know not the light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 17, E'For the morning is to them even as the shadow of death: if one know them, they are in the terrors of the shadow of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 18, E'He is swift as the waters; their portion is cursed in the earth: he beholdeth not the way of the vineyards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 19, E'Drought and heat consume the snow waters: so doth the grave those which have sinned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 20, E'The womb shall forget him; the worm shall feed sweetly on him; he shall be no more remembered; and wickedness shall be broken as a tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 21, E'He evil entreateth the barren that beareth not: and doeth not good to the widow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 22, E'He draweth also the mighty with his power: he riseth up, and no man is sure of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 23, E'Though it be given him to be in safety, whereon he resteth; yet his eyes are upon their ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 24, E'They are exalted for a little while, but are gone and brought low; they are taken out of the way as all other, and cut off as the tops of the ears of corn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 24, 25, E'And if it be not so now, who will make me a liar, and make my speech nothing worth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 25, 1, E'Then answered Bildad the Shuhite, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 25, 2, E'Dominion and fear are with him, he maketh peace in his high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 25, 3, E'Is there any number of his armies? and upon whom doth not his light arise?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 25, 4, E'How then can man be justified with God? or how can he be clean that is born of a woman?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 25, 5, E'Behold even to the moon, and it shineth not; yea, the stars are not pure in his sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 25, 6, E'How much less man, that is a worm? and the son of man, which is a worm?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 1, E'But Job answered and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 2, E'How hast thou helped him that is without power? how savest thou the arm that hath no strength?')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 3, E'How hast thou counselled him that hath no wisdom? and how hast thou plentifully declared the thing as it is?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 4, E'To whom hast thou uttered words? and whose spirit came from thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 5, E'Dead things are formed from under the waters, and the inhabitants thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 6, E'Hell is naked before him, and destruction hath no covering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 7, E'He stretcheth out the north over the empty place, and hangeth the earth upon nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 8, E'He bindeth up the waters in his thick clouds; and the cloud is not rent under them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 9, E'He holdeth back the face of his throne, and spreadeth his cloud upon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 10, E'He hath compassed the waters with bounds, until the day and night come to an end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 11, E'The pillars of heaven tremble and are astonished at his reproof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 12, E'He divideth the sea with his power, and by his understanding he smiteth through the proud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 13, E'By his spirit he hath garnished the heavens; his hand hath formed the crooked serpent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 26, 14, E'Lo, these are parts of his ways: but how little a portion is heard of him? but the thunder of his power who can understand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 1, E'Moreover Job continued his parable, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 2, E'As God liveth, who hath taken away my judgment; and the Almighty, who hath vexed my soul;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 3, E'All the while my breath is in me, and the spirit of God is in my nostrils;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 4, E'My lips shall not speak wickedness, nor my tongue utter deceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 5, E'God forbid that I should justify you: till I die I will not remove mine integrity from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 6, E'My righteousness I hold fast, and will not let it go: my heart shall not reproach me so long as I live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 7, E'Let mine enemy be as the wicked, and he that riseth up against me as the unrighteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 8, E'For what is the hope of the hypocrite, though he hath gained, when God taketh away his soul?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 9, E'Will God hear his cry when trouble cometh upon him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 10, E'Will he delight himself in the Almighty? will he always call upon God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 11, E'I will teach you by the hand of God: that which is with the Almighty will I not conceal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 12, E'Behold, all ye yourselves have seen it; why then are ye thus altogether vain?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 13, E'This is the portion of a wicked man with God, and the heritage of oppressors, which they shall receive of the Almighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 14, E'If his children be multiplied, it is for the sword: and his offspring shall not be satisfied with bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 15, E'Those that remain of him shall be buried in death: and his widows shall not weep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 16, E'Though he heap up silver as the dust, and prepare raiment as the clay;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 17, E'He may prepare it, but the just shall put it on, and the innocent shall divide the silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 18, E'He buildeth his house as a moth, and as a booth that the keeper maketh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 19, E'The rich man shall lie down, but he shall not be gathered: he openeth his eyes, and he is not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 20, E'Terrors take hold on him as waters, a tempest stealeth him away in the night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 21, E'The east wind carrieth him away, and he departeth: and as a storm hurleth him out of his place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 22, E'For God shall cast upon him, and not spare: he would fain flee out of his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 27, 23, E'Men shall clap their hands at him, and shall hiss him out of his place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 1, E'Surely there is a vein for the silver, and a place for gold where they fine it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 2, E'Iron is taken out of the earth, and brass is molten out of the stone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 3, E'He setteth an end to darkness, and searcheth out all perfection: the stones of darkness, and the shadow of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 4, E'The flood breaketh out from the inhabitant; even the waters forgotten of the foot: they are dried up, they are gone away from men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 5, E'As for the earth, out of it cometh bread: and under it is turned up as it were fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 6, E'The stones of it are the place of sapphires: and it hath dust of gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 7, E'There is a path which no fowl knoweth, and which the vulture’s eye hath not seen:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 8, E'The lion’s whelps have not trodden it, nor the fierce lion passed by it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 9, E'He putteth forth his hand upon the rock; he overturneth the mountains by the roots.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 10, E'He cutteth out rivers among the rocks; and his eye seeth every precious thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 11, E'He bindeth the floods from overflowing; and the thing that is hid bringeth he forth to light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 12, E'But where shall wisdom be found? and where is the place of understanding?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 13, E'Man knoweth not the price thereof; neither is it found in the land of the living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 14, E'The depth saith, It is not in me: and the sea saith, It is not with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 15, E'It cannot be gotten for gold, neither shall silver be weighed for the price thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 16, E'It cannot be valued with the gold of Ophir, with the precious onyx, or the sapphire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 17, E'The gold and the crystal cannot equal it: and the exchange of it shall not be for jewels of fine gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 18, E'No mention shall be made of coral, or of pearls: for the price of wisdom is above rubies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 19, E'The topaz of Ethiopia shall not equal it, neither shall it be valued with pure gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 20, E'Whence then cometh wisdom? and where is the place of understanding?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 21, E'Seeing it is hid from the eyes of all living, and kept close from the fowls of the air.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 22, E'Destruction and death say, We have heard the fame thereof with our ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 23, E'God understandeth the way thereof, and he knoweth the place thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 24, E'For he looketh to the ends of the earth, and seeth under the whole heaven;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 25, E'To make the weight for the winds; and he weigheth the waters by measure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 26, E'When he made a decree for the rain, and a way for the lightning of the thunder:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 27, E'Then did he see it, and declare it; he prepared it, yea, and searched it out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 28, 28, E'And unto man he said, Behold, the fear of the LORD, that is wisdom; and to depart from evil is understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 1, E'Moreover Job continued his parable, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 2, E'Oh that I were as in months past, as in the days when God preserved me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 3, E'When his candle shined upon my head, and when by his light I walked through darkness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 4, E'As I was in the days of my youth, when the secret of God was upon my tabernacle;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 5, E'When the Almighty was yet with me, when my children were about me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 6, E'When I washed my steps with butter, and the rock poured me out rivers of oil;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 7, E'When I went out to the gate through the city, when I prepared my seat in the street!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 8, E'The young men saw me, and hid themselves: and the aged arose, and stood up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 9, E'The princes refrained talking, and laid their hand on their mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 10, E'The nobles held their peace, and their tongue cleaved to the roof of their mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 11, E'When the ear heard me, then it blessed me; and when the eye saw me, it gave witness to me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 12, E'Because I delivered the poor that cried, and the fatherless, and him that had none to help him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 13, E'The blessing of him that was ready to perish came upon me: and I caused the widow’s heart to sing for joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 14, E'I put on righteousness, and it clothed me: my judgment was as a robe and a diadem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 15, E'I was eyes to the blind, and feet was I to the lame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 16, E'I was a father to the poor: and the cause which I knew not I searched out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 17, E'And I brake the jaws of the wicked, and plucked the spoil out of his teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 18, E'Then I said, I shall die in my nest, and I shall multiply my days as the sand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 19, E'My root was spread out by the waters, and the dew lay all night upon my branch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 20, E'My glory was fresh in me, and my bow was renewed in my hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 21, E'Unto me men gave ear, and waited, and kept silence at my counsel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 22, E'After my words they spake not again; and my speech dropped upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 23, E'And they waited for me as for the rain; and they opened their mouth wide as for the latter rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 24, E'If I laughed on them, they believed it not; and the light of my countenance they cast not down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 29, 25, E'I chose out their way, and sat chief, and dwelt as a king in the army, as one that comforteth the mourners.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 1, E'But now they that are younger than I have me in derision, whose fathers I would have disdained to have set with the dogs of my flock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 2, E'Yea, whereto might the strength of their hands profit me, in whom old age was perished?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 3, E'For want and famine they were solitary; fleeing into the wilderness in former time desolate and waste.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 4, E'Who cut up mallows by the bushes, and juniper roots for their meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 5, E'They were driven forth from among men, (they cried after them as after a thief;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 6, E'To dwell in the cliffs of the valleys, in caves of the earth, and in the rocks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 7, E'Among the bushes they brayed; under the nettles they were gathered together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 8, E'They were children of fools, yea, children of base men: they were viler than the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 9, E'And now am I their song, yea, I am their byword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 10, E'They abhor me, they flee far from me, and spare not to spit in my face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 11, E'Because he hath loosed my cord, and afflicted me, they have also let loose the bridle before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 12, E'Upon my right hand rise the youth; they push away my feet, and they raise up against me the ways of their destruction.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 13, E'They mar my path, they set forward my calamity, they have no helper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 14, E'They came upon me as a wide breaking in of waters: in the desolation they rolled themselves upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 15, E'Terrors are turned upon me: they pursue my soul as the wind: and my welfare passeth away as a cloud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 16, E'And now my soul is poured out upon me; the days of affliction have taken hold upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 17, E'My bones are pierced in me in the night season: and my sinews take no rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 18, E'By the great force of my disease is my garment changed: it bindeth me about as the collar of my coat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 19, E'He hath cast me into the mire, and I am become like dust and ashes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 20, E'I cry unto thee, and thou dost not hear me: I stand up, and thou regardest me not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 21, E'Thou art become cruel to me: with thy strong hand thou opposest thyself against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 22, E'Thou liftest me up to the wind; thou causest me to ride upon it, and dissolvest my substance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 23, E'For I know that thou wilt bring me to death, and to the house appointed for all living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 24, E'Howbeit he will not stretch out his hand to the grave, though they cry in his destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 25, E'Did not I weep for him that was in trouble? was not my soul grieved for the poor?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 26, E'When I looked for good, then evil came unto me: and when I waited for light, there came darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 27, E'My bowels boiled, and rested not: the days of affliction prevented me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 28, E'I went mourning without the sun: I stood up, and I cried in the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 29, E'I am a brother to dragons, and a companion to owls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 30, E'My skin is black upon me, and my bones are burned with heat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 30, 31, E'My harp also is turned to mourning, and my organ into the voice of them that weep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 1, E'I made a covenant with mine eyes; why then should I think upon a maid?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 2, E'For what portion of God is there from above? and what inheritance of the Almighty from on high?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 3, E'Is not destruction to the wicked? and a strange punishment to the workers of iniquity?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 4, E'Doth not he see my ways, and count all my steps?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 5, E'If I have walked with vanity, or if my foot hath hasted to deceit;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 6, E'Let me be weighed in an even balance that God may know mine integrity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 7, E'If my step hath turned out of the way, and mine heart walked after mine eyes, and if any blot hath cleaved to mine hands;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 8, E'Then let me sow, and let another eat; yea, let my offspring be rooted out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 9, E'If mine heart have been deceived by a woman, or if I have laid wait at my neighbour’s door;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 10, E'Then let my wife grind unto another, and let others bow down upon her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 11, E'For this is an heinous crime; yea, it is an iniquity to be punished by the judges.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 12, E'For it is a fire that consumeth to destruction, and would root out all mine increase.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 13, E'If I did despise the cause of my manservant or of my maidservant, when they contended with me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 14, E'What then shall I do when God riseth up? and when he visiteth, what shall I answer him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 15, E'Did not he that made me in the womb make him? and did not one fashion us in the womb?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 16, E'If I have withheld the poor from their desire, or have caused the eyes of the widow to fail;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 17, E'Or have eaten my morsel myself alone, and the fatherless hath not eaten thereof;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 18, E'(For from my youth he was brought up with me, as with a father, and I have guided her from my mother’s womb;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 19, E'If I have seen any perish for want of clothing, or any poor without covering;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 20, E'If his loins have not blessed me, and if he were not warmed with the fleece of my sheep;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 21, E'If I have lifted up my hand against the fatherless, when I saw my help in the gate:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 22, E'Then let mine arm fall from my shoulder blade, and mine arm be broken from the bone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 23, E'For destruction from God was a terror to me, and by reason of his highness I could not endure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 24, E'If I have made gold my hope, or have said to the fine gold, Thou art my confidence;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 25, E'If I rejoiced because my wealth was great, and because mine hand had gotten much;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 26, E'If I beheld the sun when it shined, or the moon walking in brightness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 27, E'And my heart hath been secretly enticed, or my mouth hath kissed my hand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 28, E'This also were an iniquity to be punished by the judge: for I should have denied the God that is above.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 29, E'If I rejoiced at the destruction of him that hated me, or lifted up myself when evil found him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 30, E'Neither have I suffered my mouth to sin by wishing a curse to his soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 31, E'If the men of my tabernacle said not, Oh that we had of his flesh! we cannot be satisfied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 32, E'The stranger did not lodge in the street: but I opened my doors to the traveller.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 33, E'If I covered my transgressions as Adam, by hiding mine iniquity in my bosom:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 34, E'Did I fear a great multitude, or did the contempt of families terrify me, that I kept silence, and went not out of the door?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 35, E'Oh that one would hear me! behold, my desire is, that the Almighty would answer me, and that mine adversary had written a book.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 36, E'Surely I would take it upon my shoulder, and bind it as a crown to me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 37, E'I would declare unto him the number of my steps; as a prince would I go near unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 38, E'If my land cry against me, or that the furrows likewise thereof complain;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 39, E'If I have eaten the fruits thereof without money, or have caused the owners thereof to lose their life:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 31, 40, E'Let thistles grow instead of wheat, and cockle instead of barley. The words of Job are ended.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 1, E'So these three men ceased to answer Job, because he was righteous in his own eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 2, E'Then was kindled the wrath of Elihu the son of Barachel the Buzite, of the kindred of Ram: against Job was his wrath kindled, because he justified himself rather than God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 3, E'Also against his three friends was his wrath kindled, because they had found no answer, and yet had condemned Job.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 4, E'Now Elihu had waited till Job had spoken, because they were elder than he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 5, E'When Elihu saw that there was no answer in the mouth of these three men, then his wrath was kindled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 6, E'And Elihu the son of Barachel the Buzite answered and said, I am young, and ye are very old; wherefore I was afraid, and durst not shew you mine opinion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 7, E'I said, Days should speak, and multitude of years should teach wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 8, E'But there is a spirit in man: and the inspiration of the Almighty giveth them understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 9, E'Great men are not always wise: neither do the aged understand judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 10, E'Therefore I said, Hearken to me; I also will shew mine opinion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 11, E'Behold, I waited for your words; I gave ear to your reasons, whilst ye searched out what to say.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 12, E'Yea, I attended unto you, and, behold, there was none of you that convinced Job, or that answered his words:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 13, E'Lest ye should say, We have found out wisdom: God thrusteth him down, not man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 14, E'Now he hath not directed his words against me: neither will I answer him with your speeches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 15, E'They were amazed, they answered no more: they left off speaking.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 16, E'When I had waited, (for they spake not, but stood still, and answered no more;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 17, E'I said, I will answer also my part, I also will shew mine opinion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 18, E'For I am full of matter, the spirit within me constraineth me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 19, E'Behold, my belly is as wine which hath no vent; it is ready to burst like new bottles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 20, E'I will speak, that I may be refreshed: I will open my lips and answer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 21, E'Let me not, I pray you, accept any man’s person, neither let me give flattering titles unto man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 32, 22, E'For I know not to give flattering titles; in so doing my maker would soon take me away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 1, E'Wherefore, Job, I pray thee, hear my speeches, and hearken to all my words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 2, E'Behold, now I have opened my mouth, my tongue hath spoken in my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 3, E'My words shall be of the uprightness of my heart: and my lips shall utter knowledge clearly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 4, E'The spirit of God hath made me, and the breath of the Almighty hath given me life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 5, E'If thou canst answer me, set thy words in order before me, stand up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 6, E'Behold, I am according to thy wish in God’s stead: I also am formed out of the clay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 7, E'Behold, my terror shall not make thee afraid, neither shall my hand be heavy upon thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 8, E'Surely thou hast spoken in mine hearing, and I have heard the voice of thy words, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 9, E'I am clean without transgression, I am innocent; neither is there iniquity in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 10, E'Behold, he findeth occasions against me, he counteth me for his enemy,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 11, E'He putteth my feet in the stocks, he marketh all my paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 12, E'Behold, in this thou art not just: I will answer thee, that God is greater than man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 13, E'Why dost thou strive against him? for he giveth not account of any of his matters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 14, E'For God speaketh once, yea twice, yet man perceiveth it not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 15, E'In a dream, in a vision of the night, when deep sleep falleth upon men, in slumberings upon the bed;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 16, E'Then he openeth the ears of men, and sealeth their instruction,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 17, E'That he may withdraw man from his purpose, and hide pride from man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 18, E'He keepeth back his soul from the pit, and his life from perishing by the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 19, E'He is chastened also with pain upon his bed, and the multitude of his bones with strong pain:')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 20, E'So that his life abhorreth bread, and his soul dainty meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 21, E'His flesh is consumed away, that it cannot be seen; and his bones that were not seen stick out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 22, E'Yea, his soul draweth near unto the grave, and his life to the destroyers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 23, E'If there be a messenger with him, an interpreter, one among a thousand, to shew unto man his uprightness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 24, E'Then he is gracious unto him, and saith, Deliver him from going down to the pit: I have found a ransom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 25, E'His flesh shall be fresher than a child’s: he shall return to the days of his youth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 26, E'He shall pray unto God, and he will be favourable unto him: and he shall see his face with joy: for he will render unto man his righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 27, E'He looketh upon men, and if any say, I have sinned, and perverted that which was right, and it profited me not;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 28, E'He will deliver his soul from going into the pit, and his life shall see the light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 29, E'Lo, all these things worketh God oftentimes with man,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 30, E'To bring back his soul from the pit, to be enlightened with the light of the living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 31, E'Mark well, O Job, hearken unto me: hold thy peace, and I will speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 32, E'If thou hast anything to say, answer me: speak, for I desire to justify thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 33, 33, E'If not, hearken unto me: hold thy peace, and I shall teach thee wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 1, E'Furthermore Elihu answered and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 2, E'Hear my words, O ye wise men; and give ear unto me, ye that have knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 3, E'For the ear trieth words, as the mouth tasteth meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 4, E'Let us choose to us judgment: let us know among ourselves what is good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 5, E'For Job hath said, I am righteous: and God hath taken away my judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 6, E'Should I lie against my right? my wound is incurable without transgression.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 7, E'What man is like Job, who drinketh up scorning like water?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 8, E'Which goeth in company with the workers of iniquity, and walketh with wicked men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 9, E'For he hath said, It profiteth a man nothing that he should delight himself with God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 10, E'Therefore hearken unto me ye men of understanding: far be it from God, that he should do wickedness; and from the Almighty, that he should commit iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 11, E'For the work of a man shall he render unto him, and cause every man to find according to his ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 12, E'Yea, surely God will not do wickedly, neither will the Almighty pervert judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 13, E'Who hath given him a charge over the earth? or who hath disposed the whole world?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 14, E'If he set his heart upon man, if he gather unto himself his spirit and his breath;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 15, E'All flesh shall perish together, and man shall turn again unto dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 16, E'If now thou hast understanding, hear this: hearken to the voice of my words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 17, E'Shall even he that hateth right govern? and wilt thou condemn him that is most just?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 18, E'Is it fit to say to a king, Thou art wicked? and to princes, Ye are ungodly?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 19, E'How much less to him that accepteth not the persons of princes, nor regardeth the rich more than the poor? for they all are the work of his hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 20, E'In a moment shall they die, and the people shall be troubled at midnight, and pass away: and the mighty shall be taken away without hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 21, E'For his eyes are upon the ways of man, and he seeth all his goings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 22, E'There is no darkness, nor shadow of death, where the workers of iniquity may hide themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 23, E'For he will not lay upon man more than right; that he should enter into judgment with God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 24, E'He shall break in pieces mighty men without number, and set others in their stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 25, E'Therefore he knoweth their works, and he overturneth them in the night, so that they are destroyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 26, E'He striketh them as wicked men in the open sight of others;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 27, E'Because they turned back from him, and would not consider any of his ways:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 28, E'So that they cause the cry of the poor to come unto him, and he heareth the cry of the afflicted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 29, E'When he giveth quietness, who then can make trouble? and when he hideth his face, who then can behold him? whether it be done against a nation, or against a man only:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 30, E'That the hypocrite reign not, lest the people be ensnared.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 31, E'Surely it is meet to be said unto God, I have borne chastisement, I will not offend any more:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 32, E'That which I see not teach thou me: if I have done iniquity, I will do no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 33, E'Should it be according to thy mind? he will recompense it, whether thou refuse, or whether thou choose; and not I: therefore speak what thou knowest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 34, E'Let men of understanding tell me, and let a wise man hearken unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 35, E'Job hath spoken without knowledge, and his words were without wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 36, E'My desire is that Job may be tried unto the end because of his answers for wicked men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 34, 37, E'For he addeth rebellion unto his sin, he clappeth his hands among us, and multiplieth his words against God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 1, E'Elihu spake moreover, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 2, E'Thinkest thou this to be right, that thou saidst, My righteousness is more than God’s?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 3, E'For thou saidst, What advantage will it be unto thee? and, What profit shall I have, if I be cleansed from my sin?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 4, E'I will answer thee, and thy companions with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 5, E'Look unto the heavens, and see; and behold the clouds which are higher than thou.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 6, E'If thou sinnest, what doest thou against him? or if thy transgressions be multiplied, what doest thou unto him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 7, E'If thou be righteous, what givest thou him? or what receiveth he of thine hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 8, E'Thy wickedness may hurt a man as thou art; and thy righteousness may profit the son of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 9, E'By reason of the multitude of oppressions they make the oppressed to cry: they cry out by reason of the arm of the mighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 10, E'But none saith, Where is God my maker, who giveth songs in the night;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 11, E'Who teacheth us more than the beasts of the earth, and maketh us wiser than the fowls of heaven?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 12, E'There they cry, but none giveth answer, because of the pride of evil men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 13, E'Surely God will not hear vanity, neither will the Almighty regard it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 14, E'Although thou sayest thou shalt not see him, yet judgment is before him; therefore trust thou in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 15, E'But now, because it is not so, he hath visited in his anger; yet he knoweth it not in great extremity:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 35, 16, E'Therefore doth Job open his mouth in vain; he multiplieth words without knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 1, E'Elihu also proceeded, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 2, E'Suffer me a little, and I will shew thee that I have yet to speak on God’s behalf.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 3, E'I will fetch my knowledge from afar, and will ascribe righteousness to my Maker.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 4, E'For truly my words shall not be false: he that is perfect in knowledge is with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 5, E'Behold, God is mighty, and despiseth not any: he is mighty in strength and wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 6, E'He preserveth not the life of the wicked: but giveth right to the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 7, E'He withdraweth not his eyes from the righteous: but with kings are they on the throne; yea, he doth establish them for ever, and they are exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 8, E'And if they be bound in fetters, and be holden in cords of affliction;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 9, E'Then he sheweth them their work, and their transgressions that they have exceeded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 10, E'He openeth also their ear to discipline, and commandeth that they return from iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 11, E'If they obey and serve him, they shall spend their days in prosperity, and their years in pleasures.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 12, E'But if they obey not, they shall perish by the sword, and they shall die without knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 13, E'But the hypocrites in heart heap up wrath: they cry not when he bindeth them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 14, E'They die in youth, and their life is among the unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 15, E'He delivereth the poor in his affliction, and openeth their ears in oppression.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 16, E'Even so would he have removed thee out of the strait into a broad place, where there is no straitness; and that which should be set on thy table should be full of fatness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 17, E'But thou hast fulfilled the judgment of the wicked: judgment and justice take hold on thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 18, E'Because there is wrath, beware lest he take thee away with his stroke: then a great ransom cannot deliver thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 19, E'Will he esteem thy riches? no, not gold, nor all the forces of strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 20, E'Desire not the night, when people are cut off in their place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 21, E'Take heed, regard not iniquity: for this hast thou chosen rather than affliction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 22, E'Behold, God exalteth by his power: who teacheth like him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 23, E'Who hath enjoined him his way? or who can say, Thou hast wrought iniquity?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 24, E'Remember that thou magnify his work, which men behold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 25, E'Every man may see it; man may behold it afar off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 26, E'Behold, God is great, and we know him not, neither can the number of his years be searched out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 27, E'For he maketh small the drops of water: they pour down rain according to the vapour thereof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 28, E'Which the clouds do drop and distil upon man abundantly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 29, E'Also can any understand the spreadings of the clouds, or the noise of his tabernacle?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 30, E'Behold, he spreadeth his light upon it, and covereth the bottom of the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 31, E'For by them judgeth he the people; he giveth meat in abundance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 32, E'With clouds he covereth the light; and commandeth it not to shine by the cloud that cometh betwixt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 36, 33, E'The noise thereof sheweth concerning it, the cattle also concerning the vapour.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 1, E'At this also my heart trembleth, and is moved out of his place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 2, E'Hear attentively the noise of his voice, and the sound that goeth out of his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 3, E'He directeth it under the whole heaven, and his lightning unto the ends of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 4, E'After it a voice roareth: he thundereth with the voice of his excellency; and he will not stay them when his voice is heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 5, E'God thundereth marvellously with his voice; great things doeth he, which we cannot comprehend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 6, E'For he saith to the snow, Be thou on the earth; likewise to the small rain, and to the great rain of his strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 7, E'He sealeth up the hand of every man; that all men may know his work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 8, E'Then the beasts go into dens, and remain in their places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 9, E'Out of the south cometh the whirlwind: and cold out of the north.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 10, E'By the breath of God frost is given: and the breadth of the waters is straitened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 11, E'Also by watering he wearieth the thick cloud: he scattereth his bright cloud:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 12, E'And it is turned round about by his counsels: that they may do whatsoever he commandeth them upon the face of the world in the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 13, E'He causeth it to come, whether for correction, or for his land, or for mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 14, E'Hearken unto this, O Job: stand still, and consider the wondrous works of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 15, E'Dost thou know when God disposed them, and caused the light of his cloud to shine?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 16, E'Dost thou know the balancings of the clouds, the wondrous works of him which is perfect in knowledge?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 17, E'How thy garments are warm, when he quieteth the earth by the south wind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 18, E'Hast thou with him spread out the sky, which is strong, and as a molten looking glass?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 19, E'Teach us what we shall say unto him; for we cannot order our speech by reason of darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 20, E'Shall it be told him that I speak? if a man speak, surely he shall be swallowed up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 21, E'And now men see not the bright light which is in the clouds: but the wind passeth, and cleanseth them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 22, E'Fair weather cometh out of the north: with God is terrible majesty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 23, E'Touching the Almighty, we cannot find him out: he is excellent in power, and in judgment, and in plenty of justice: he will not afflict.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 37, 24, E'Men do therefore fear him: he respecteth not any that are wise of heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 1, E'Then the LORD answered Job out of the whirlwind, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 2, E'Who is this that darkeneth counsel by words without knowledge?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 3, E'Gird up now thy loins like a man; for I will demand of thee, and answer thou me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 4, E'Where wast thou when I laid the foundations of the earth? declare, if thou hast understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 5, E'Who hath laid the measures thereof, if thou knowest? or who hath stretched the line upon it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 6, E'Whereupon are the foundations thereof fastened? or who laid the corner stone thereof;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 7, E'When the morning stars sang together, and all the sons of God shouted for joy?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 8, E'Or who shut up the sea with doors, when it brake forth, as if it had issued out of the womb?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 9, E'When I made the cloud the garment thereof, and thick darkness a swaddlingband for it,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 10, E'And brake up for it my decreed place, and set bars and doors,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 11, E'And said, Hitherto shalt thou come, but no further: and here shall thy proud waves be stayed?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 12, E'Hast thou commanded the morning since thy days; and caused the dayspring to know his place;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 13, E'That it might take hold of the ends of the earth, that the wicked might be shaken out of it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 14, E'It is turned as clay to the seal; and they stand as a garment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 15, E'And from the wicked their light is withholden, and the high arm shall be broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 16, E'Hast thou entered into the springs of the sea? or hast thou walked in the search of the depth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 17, E'Have the gates of death been opened unto thee? or hast thou seen the doors of the shadow of death?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 18, E'Hast thou perceived the breadth of the earth? declare if thou knowest it all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 19, E'Where is the way where light dwelleth? and as for darkness, where is the place thereof,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 20, E'That thou shouldest take it to the bound thereof, and that thou shouldest know the paths to the house thereof?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 21, E'Knowest thou it, because thou wast then born? or because the number of thy days is great?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 22, E'Hast thou entered into the treasures of the snow? or hast thou seen the treasures of the hail,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 23, E'Which I have reserved against the time of trouble, against the day of battle and war?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 24, E'By what way is the light parted, which scattereth the east wind upon the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 25, E'Who hath divided a watercourse for the overflowing of waters, or a way for the lightning of thunder;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 26, E'To cause it to rain on the earth, where no man is; on the wilderness, wherein there is no man;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 27, E'To satisfy the desolate and waste ground; and to cause the bud of the tender herb to spring forth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 28, E'Hath the rain a father? or who hath begotten the drops of dew?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 29, E'Out of whose womb came the ice? and the hoary frost of heaven, who hath gendered it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 30, E'The waters are hid as with a stone, and the face of the deep is frozen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 31, E'Canst thou bind the sweet influences of Pleiades, or loose the bands of Orion?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 32, E'Canst thou bring forth Mazzaroth in his season? or canst thou guide Arcturus with his sons?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 33, E'Knowest thou the ordinances of heaven? canst thou set the dominion thereof in the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 34, E'Canst thou lift up thy voice to the clouds, that abundance of waters may cover thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 35, E'Canst thou send lightnings, that they may go, and say unto thee, Here we are?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 36, E'Who hath put wisdom in the inward parts? or who hath given understanding to the heart?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 37, E'Who can number the clouds in wisdom? or who can stay the bottles of heaven,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 38, E'When the dust groweth into hardness, and the clods cleave fast together?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 39, E'Wilt thou hunt the prey for the lion? or fill the appetite of the young lions,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 40, E'When they couch in their dens, and abide in the covert to lie in wait?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 38, 41, E'Who provideth for the raven his food? when his young ones cry unto God, they wander for lack of meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 1, E'Knowest thou the time when the wild goats of the rock bring forth? or canst thou mark when the hinds do calve?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 2, E'Canst thou number the months that they fulfil? or knowest thou the time when they bring forth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 3, E'They bow themselves, they bring forth their young ones, they cast out their sorrows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 4, E'Their young ones are in good liking, they grow up with corn; they go forth, and return not unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 5, E'Who hath sent out the wild ass free? or who hath loosed the bands of the wild ass?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 6, E'Whose house I have made the wilderness, and the barren land his dwellings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 7, E'He scorneth the multitude of the city, neither regardeth he the crying of the driver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 8, E'The range of the mountains is his pasture, and he searcheth after every green thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 9, E'Will the unicorn be willing to serve thee, or abide by thy crib?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 10, E'Canst thou bind the unicorn with his band in the furrow? or will he harrow the valleys after thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 11, E'Wilt thou trust him, because his strength is great? or wilt thou leave thy labour to him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 12, E'Wilt thou believe him, that he will bring home thy seed, and gather it into thy barn?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 13, E'Gavest thou the goodly wings unto the peacocks? or wings and feathers unto the ostrich?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 14, E'Which leaveth her eggs in the earth, and warmeth them in dust,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 15, E'And forgetteth that the foot may crush them, or that the wild beast may break them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 16, E'She is hardened against her young ones, as though they were not hers: her labour is in vain without fear;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 17, E'Because God hath deprived her of wisdom, neither hath he imparted to her understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 18, E'What time she lifteth up herself on high, she scorneth the horse and his rider.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 19, E'Hast thou given the horse strength? hast thou clothed his neck with thunder?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 20, E'Canst thou make him afraid as a grasshopper? the glory of his nostrils is terrible.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 21, E'He paweth in the valley, and rejoiceth in his strength: he goeth on to meet the armed men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 22, E'He mocketh at fear, and is not affrighted; neither turneth he back from the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 23, E'The quiver rattleth against him, the glittering spear and the shield.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 24, E'He swalloweth the ground with fierceness and rage: neither believeth he that it is the sound of the trumpet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 25, E'He saith among the trumpets, Ha, ha; and he smelleth the battle afar off, the thunder of the captains, and the shouting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 26, E'Doth the hawk fly by thy wisdom, and stretch her wings toward the south?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 27, E'Doth the eagle mount up at thy command, and make her nest on high?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 28, E'She dwelleth and abideth on the rock, upon the crag of the rock, and the strong place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 29, E'From thence she seeketh the prey, and her eyes behold afar off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 39, 30, E'Her young ones also suck up blood: and where the slain are, there is she.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 1, E'Moreover the LORD answered Job, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 2, E'Shall he that contendeth with the Almighty instruct him? he that reproveth God, let him answer it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 3, E'Then Job answered the LORD, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 4, E'Behold, I am vile; what shall I answer thee? I will lay mine hand upon my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 5, E'Once have I spoken; but I will not answer: yea, twice; but I will proceed no further.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 6, E'Then answered the LORD unto Job out of the whirlwind, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 7, E'Gird up thy loins now like a man: I will demand of thee, and declare thou unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 8, E'Wilt thou also disannul my judgment? wilt thou condemn me, that thou mayest be righteous?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 9, E'Hast thou an arm like God? or canst thou thunder with a voice like him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 10, E'Deck thyself now with majesty and excellency; and array thyself with glory and beauty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 11, E'Cast abroad the rage of thy wrath: and behold every one that is proud, and abase him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 12, E'Look on every one that is proud, and bring him low; and tread down the wicked in their place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 13, E'Hide them in the dust together; and bind their faces in secret.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 14, E'Then will I also confess unto thee that thine own right hand can save thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 15, E'Behold now behemoth, which I made with thee; he eateth grass as an ox.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 16, E'Lo now, his strength is in his loins, and his force is in the navel of his belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 17, E'He moveth his tail like a cedar: the sinews of his stones are wrapped together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 18, E'His bones are as strong pieces of brass; his bones are like bars of iron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 19, E'He is the chief of the ways of God: he that made him can make his sword to approach unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 20, E'Surely the mountains bring him forth food, where all the beasts of the field play.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 21, E'He lieth under the shady trees, in the covert of the reed, and fens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 22, E'The shady trees cover him with their shadow; the willows of the brook compass him about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 23, E'Behold, he drinketh up a river, and hasteth not: he trusteth that he can draw up Jordan into his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 24, E'He taketh it with his eyes: his nose pierceth through snares.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 1, E'Canst thou draw out leviathan with an hook? or his tongue with a cord which thou lettest down?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 2, E'Canst thou put an hook into his nose? or bore his jaw through with a thorn?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 3, E'Will he make many supplications unto thee? will he speak soft words unto thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 4, E'Will he make a covenant with thee? wilt thou take him for a servant for ever?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 5, E'Wilt thou play with him as with a bird? or wilt thou bind him for thy maidens?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 6, E'Shall the companions make a banquet of him? shall they part him among the merchants?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 7, E'Canst thou fill his skin with barbed irons? or his head with fish spears?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 8, E'Lay thine hand upon him, remember the battle, do no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 9, E'Behold, the hope of him is in vain: shall not one be cast down even at the sight of him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 10, E'None is so fierce that dare stir him up: who then is able to stand before me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 11, E'Who hath prevented me, that I should repay him? whatsoever is under the whole heaven is mine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 12, E'I will not conceal his parts, nor his power, nor his comely proportion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 13, E'Who can discover the face of his garment? or who can come to him with his double bridle?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 14, E'Who can open the doors of his face? his teeth are terrible round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 15, E'His scales are his pride, shut up together as with a close seal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 16, E'One is so near to another, that no air can come between them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 17, E'They are joined one to another, they stick together, that they cannot be sundered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 18, E'By his neesings a light doth shine, and his eyes are like the eyelids of the morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 19, E'Out of his mouth go burning lamps, and sparks of fire leap out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 20, E'Out of his nostrils goeth smoke, as out of a seething pot or caldron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 21, E'His breath kindleth coals, and a flame goeth out of his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 22, E'In his neck remaineth strength, and sorrow is turned into joy before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 23, E'The flakes of his flesh are joined together: they are firm in themselves; they cannot be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 24, E'His heart is as firm as a stone; yea, as hard as a piece of the nether millstone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 25, E'When he raiseth up himself, the mighty are afraid: by reason of breakings they purify themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 26, E'The sword of him that layeth at him cannot hold: the spear, the dart, nor the habergeon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 27, E'He esteemeth iron as straw, and brass as rotten wood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 28, E'The arrow cannot make him flee: slingstones are turned with him into stubble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 29, E'Darts are counted as stubble: he laugheth at the shaking of a spear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 30, E'Sharp stones are under him: he spreadeth sharp pointed things upon the mire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 31, E'He maketh the deep to boil like a pot: he maketh the sea like a pot of ointment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 32, E'He maketh a path to shine after him; one would think the deep to be hoary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 33, E'Upon earth there is not his like, who is made without fear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 34, E'He beholdeth all high things: he is a king over all the children of pride.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 1, E'Then Job answered the LORD, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 2, E'I know that thou canst do every thing, and that no thought can be withholden from thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 3, E'Who is he that hideth counsel without knowledge? therefore have I uttered that I understood not; things too wonderful for me, which I knew not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 4, E'Hear, I beseech thee, and I will speak: I will demand of thee, and declare thou unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 5, E'I have heard of thee by the hearing of the ear: but now mine eye seeth thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 6, E'Wherefore I abhor myself, and repent in dust and ashes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 7, E'And it was so, that after the LORD had spoken these words unto Job, the LORD said to Eliphaz the Temanite, My wrath is kindled against thee, and against thy two friends: for ye have not spoken of me the thing that is right, as my servant Job hath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 8, E'Therefore take unto you now seven bullocks and seven rams, and go to my servant Job, and offer up for yourselves a burnt offering; and my servant Job shall pray for you: for him will I accept: lest I deal with you after your folly, in that ye have not spoken of me the thing which is right, like my servant Job.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 9, E'So Eliphaz the Temanite and Bildad the Shuhite and Zophar the Naamathite went, and did according as the LORD commanded them: the LORD also accepted Job.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 10, E'And the LORD turned the captivity of Job, when he prayed for his friends: also the LORD gave Job twice as much as he had before.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 11, E'Then came there unto him all his brethren, and all his sisters, and all they that had been of his acquaintance before, and did eat bread with him in his house: and they bemoaned him, and comforted him over all the evil that the LORD had brought upon him: every man also gave him a piece of money, and every one an earring of gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 12, E'So the LORD blessed the latter end of Job more than his beginning: for he had fourteen thousand sheep, and six thousand camels, and a thousand yoke of oxen, and a thousand she asses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 13, E'He had also seven sons and three daughters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 14, E'And he called the name of the first, Jemima; and the name of the second, Kezia; and the name of the third, Kerenhappuch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 15, E'And in all the land were no women found so fair as the daughters of Job: and their father gave them inheritance among their brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 16, E'After this lived Job an hundred and forty years, and saw his sons, and his sons’ sons, even four generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 17, E'So Job died, being old and full of days.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

